import React, { useState, useEffect } from 'react';
import { Poem, View } from './types';
import { INITIAL_POEMS } from './constants';
import { geminiService } from './services/geminiService';

// Sub-components
import Header from './components/Header';
import Footer from './components/Footer';
import Home from './components/Home';
import Feed from './components/Feed';
import PoemDetail from './components/PoemDetail';
import CreatePoem from './components/CreatePoem';
import About from './components/About';

const STORAGE_KEY = 'echo_pages_user_poems';

const App: React.FC = () => {
  const [adminPoems] = useState<Poem[]>(INITIAL_POEMS);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [dailyLine, setDailyLine] = useState<string>('The echoes are louder than the voices.');
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Load user poems from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setUserPoems(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved poems", e);
      }
    }

    const fetchDailyLine = async () => {
      const line = await geminiService.getDailyLine();
      setDailyLine(line);
    };
    fetchDailyLine();
  }, []);

  // Save user poems to local storage when they change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(userPoems));
  }, [userPoems]);

  useEffect(() => {
    document.body.className = isDarkMode ? 'dark-mode' : 'light-mode';
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateTo = (view: View, poemId: string | null = null) => {
    setCurrentView(view);
    setSelectedPoemId(poemId);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddPoem = (newPoem: Poem) => {
    setUserPoems([newPoem, ...userPoems]);
    navigateTo('user-feed');
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col selection:bg-neutral-800 selection:text-neutral-100">
      <Header 
        currentView={currentView} 
        onNavigate={navigateTo} 
        isDarkMode={isDarkMode} 
        onToggleTheme={toggleTheme} 
      />

      <main className="flex-grow">
        {currentView === 'home' && (
          <Home dailyLine={dailyLine} onNavigate={navigateTo} />
        )}

        {currentView === 'feed' && (
          <div className="pt-10">
            <div className="max-w-7xl mx-auto px-6 mb-8 text-center">
              <h2 className="instrument-serif text-4xl italic opacity-80">Read</h2>
              <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Curated by Echo Pages</p>
            </div>
            <Feed poems={adminPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
          </div>
        )}

        {currentView === 'user-feed' && (
          <div className="pt-10">
            <div className="max-w-7xl mx-auto px-6 mb-8 text-center">
              <h2 className="instrument-serif text-4xl italic opacity-80">By Echoes</h2>
              <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Community voices</p>
            </div>
            <Feed poems={userPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
          </div>
        )}

        {currentView === 'detail' && selectedPoem && (
          <PoemDetail 
            poem={selectedPoem} 
            onBack={() => navigateTo(adminPoems.some(p => p.id === selectedPoem.id) ? 'feed' : 'user-feed')} 
          />
        )}

        {currentView === 'create' && (
          <CreatePoem onPublish={handleAddPoem} onCancel={() => navigateTo('user-feed')} />
        )}

        {currentView === 'about' && (
          <About />
        )}
      </main>

      <Footer />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types";

// Always use a named parameter and direct process.env.API_KEY for initialization
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  async getDailyLine(): Promise<string> {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
        config: {
            temperature: 0.9,
            topP: 0.95,
        }
      });
      return response.text?.trim() || "The echoes are louder than the voices.";
    } catch (error) {
      console.error("Error generating daily line:", error);
      return "Silence is the only thing we truly own.";
    }
  },

  async expandPoem(input: string, tone: string): Promise<string> {
    try {
      // Switched to gemini-3-flash-preview for near-instant poetic expansion
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Act as a minimalist, intelligent poet. Take these raw thoughts and expand them into a short, evocative poem with a ${tone} tone. Keep it raw, introspective, and haunting. Do not use cliché metaphors. Input: "${input}"`,
        config: {
          temperature: 0.8,
        }
      });
      return response.text?.trim() || input;
    } catch (error) {
      console.error("Error expanding poem:", error);
      return input;
    }
  },

  async analyzePoem(content: string): Promise<PoemMetadata> {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this poem for its emotional characteristics. Provide a short emotion tag (one word), an emotional weight (0-100), a suggested title, and a subtle CSS linear-gradient background (dark colors) that reflects the mood. Poem: "${content}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'Untitled Echo',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    } catch (error) {
      console.error("Error analyzing poem:", error);
      return {
        emotionTag: 'Quiet',
        emotionalWeight: 50,
        suggestedTitle: 'Fragment',
        backgroundGradient: 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    }
  }
};

import React, { useState } from 'react';
import { Poem } from '../types';
import { TONES, GENRES } from '../constants';
import { geminiService } from '../services/geminiService';

interface CreatePoemProps {
  onPublish: (poem: Poem) => void;
  onCancel: () => void;
}

const CreatePoem: React.FC<CreatePoemProps> = ({ onPublish, onCancel }) => {
  const [input, setInput] = useState('');
  const [selectedTone, setSelectedTone] = useState<typeof TONES[number]['id']>('melancholic');
  const [selectedGenre, setSelectedGenre] = useState<string>('Free Verse');
  const [isExpanding, setIsExpanding] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [draftPoem, setDraftPoem] = useState({
    title: '',
    content: ''
  });

  const handleExpand = async () => {
    if (!input.trim()) return;
    setIsExpanding(true);
    const promptContext = `in the ${selectedGenre} genre with a ${selectedTone} tone`;
    const expanded = await geminiService.expandPoem(input, promptContext);
    setDraftPoem({ ...draftPoem, content: expanded });
    setIsExpanding(false);
  };

  const handleAnalyzeAndPublish = async () => {
    if (!draftPoem.content.trim()) return;
    setIsAnalyzing(true);

    const meta = await geminiService.analyzePoem(draftPoem.content);

    const finalPoem: Poem = {
      id: Date.now().toString(),
      title: draftPoem.title || meta.suggestedTitle,
      content: draftPoem.content,
      author: 'Observer',
      timestamp: Date.now(),
      emotionTag: meta.emotionTag,
      emotionalWeight: meta.emotionalWeight,
      tone: selectedTone as any,
      genre: selectedGenre,
      backgroundColor: meta.backgroundGradient
    };

    onPublish(finalPoem);
    setIsAnalyzing(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in">
      <div className="space-y-16">
        <section className="space-y-8">
          <h2 className="instrument-serif text-4xl italic">Feed the void</h2>
          <p className="text-sm opacity-40 max-w-lg leading-relaxed">
            Pour your raw thoughts. The AI acts as a lens, helping articulate your chosen genre and tone.
          </p>

          <div className="space-y-6">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Start with a feeling, a memory, or a single word..."
              className="w-full h-40 bg-transparent border border-white/10 p-6 focus:border-white/40 focus:outline-none transition-all serif-font text-xl italic"
            />

            <div className="space-y-4">
              <p className="text-[10px] uppercase tracking-widest opacity-30">Choose Tone</p>
              <div className="flex flex-wrap gap-3">
                {TONES.map((tone) => (
                  <button
                    key={tone.id}
                    onClick={() => setSelectedTone(tone.id)}
                    className={`flex items-center space-x-2 px-5 py-2 border text-[10px] uppercase tracking-widest transition-all ${
                      selectedTone === tone.id ? 'border-white bg-white/5' : 'border-white/10 opacity-40 hover:opacity-100'
                    }`}
                  >
                    <span>{tone.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] uppercase tracking-widest opacity-30">Choose Genre</p>
              <div className="flex flex-wrap gap-3">
                {GENRES.map((genre) => (
                  <button
                    key={genre}
                    onClick={() => setSelectedGenre(genre)}
                    className={`px-5 py-2 border text-[10px] uppercase tracking-widest transition-all ${
                      selectedGenre === genre ? 'border-white bg-white/5' : 'border-white/10 opacity-40 hover:opacity-100'
                    }`}
                  >
                    {genre}
                  </button>
                ))}
              </div>
            </div>

            <button
              onClick={handleExpand}
              disabled={isExpanding || !input.trim()}
              className="w-full py-4 border border-white/20 hover:border-white text-xs uppercase tracking-[0.3em] transition-all disabled:opacity-20"
            >
              {isExpanding ? 'Decoding Emotions...' : 'Expand Echo'}
            </button>
          </div>
        </section>

        {draftPoem.content && (
          <section className="space-y-10 animate-fade-in pt-16 border-t border-white/5">
            <div className="space-y-4">
              <input
                type="text"
                value={draftPoem.title}
                onChange={(e) => setDraftPoem({ ...draftPoem, title: e.target.value })}
                placeholder="Give it a name (optional)"
                className="w-full bg-transparent border-b border-white/10 py-4 focus:border-white/40 focus:outline-none instrument-serif text-3xl"
              />
              <textarea
                value={draftPoem.content}
                onChange={(e) => setDraftPoem({ ...draftPoem, content: e.target.value })}
                className="w-full h-80 bg-transparent p-0 focus:outline-none serif-font text-2xl italic leading-relaxed whitespace-pre-line"
              />
            </div>

            <div className="flex flex-col sm:flex-row items-center justify-between gap-6 pt-10">
              <button 
                onClick={onCancel}
                className="text-xs uppercase tracking-widest opacity-40 hover:opacity-100 transition-all"
              >
                Discard
              </button>

              <button
                onClick={handleAnalyzeAndPublish}
                disabled={isAnalyzing}
                className="px-12 py-4 bg-white text-black text-xs uppercase tracking-[0.3em] font-medium hover:bg-neutral-200 transition-all disabled:opacity-50"
              >
                {isAnalyzing ? 'Analyzing Depths...' : 'Publish Echo'}
              </button>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

