import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types";

// Always use a named parameter and direct process.env.API_KEY for initialization
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const CACHE_KEY = 'echo_daily_line';
const CACHE_TIME_KEY = 'echo_daily_line_timestamp';
const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;

export const geminiService = {
  async getDailyLine(): Promise<string> {
    // 1. Check Cache first
    const cachedLine = localStorage.getItem(CACHE_KEY);
    const cachedTimestamp = localStorage.getItem(CACHE_TIME_KEY);
    const now = Date.now();

    if (cachedLine && cachedTimestamp && (now - parseInt(cachedTimestamp)) < TWENTY_FOUR_HOURS) {
      return cachedLine;
    }

    // 2. Fetch new if cache missing or expired
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
        config: {
            temperature: 0.9,
            topP: 0.95,
        }
      });
      const newLine = response.text?.trim() || "The echoes are louder than the voices.";

      // Update cache
      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TIME_KEY, now.toString());

      return newLine;
    } catch (error) {
      console.error("Error generating daily line:", error);
      // Return cached version even if expired if API fails, or fallback
      return cachedLine || "Silence is the only thing we truly own.";
    }
  },

  async expandPoem(input: string, context: string): Promise<string> {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Poetic expansion (${context}). Minimalist, haunting, raw. Max 50 words. Input: "${input}"`,
        config: {
          temperature: 0.7,
          maxOutputTokens: 150
        }
      });
      return response.text?.trim() || input;
    } catch (error) {
      console.error("Error expanding poem:", error);
      return input;
    }
  },

  async analyzePoem(content: string): Promise<PoemMetadata> {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this poem for its emotional characteristics. Provide a short emotion tag (one word), an emotional weight (0-100), a suggested title, and a subtle CSS linear-gradient background (dark colors) that reflects the mood. Poem: "${content}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'Untitled Echo',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    } catch (error) {
      console.error("Error analyzing poem:", error);
      return {
        emotionTag: 'Quiet',
        emotionalWeight: 50,
        suggestedTitle: 'Fragment',
        backgroundGradient: 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types';
import { geminiService } from './services/geminiService';
import { supabaseService } from './services/supabaseService';

// Sub-components
import Header from './components/Header';
import Footer from './components/Footer';
import Home from './components/Home';
import Feed from './components/Feed';
import PoemDetail from './components/PoemDetail';
import CreatePoem from './components/CreatePoem';
import About from './components/About';
import AdminPortal from './components/AdminPortal';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [dailyLine, setDailyLine] = useState<string>(() => localStorage.getItem('echo_daily_line') || 'The echoes are louder than the voices.');
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isLoading, setIsLoading] = useState(true);

  // Initial data load
  useEffect(() => {
    const loadData = async () => {
      // Don't wait for everything if we have a daily line in cache for the home screen
      const hasCache = !!localStorage.getItem('echo_daily_line');
      if (hasCache) setIsLoading(false);

      try {
        const [dbAdminPoems, dbEchoes, line] = await Promise.all([
          supabaseService.getAdminPoems(),
          supabaseService.getEchoes(),
          geminiService.getDailyLine()
        ]);

        setAdminPoems(dbAdminPoems);
        setUserPoems(dbEchoes);
        setDailyLine(line);
      } catch (err) {
        console.error("Critical load error:", err);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  useEffect(() => {
    document.body.className = isDarkMode ? 'dark-mode' : 'light-mode';
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateTo = (view: View, poemId: string | null = null) => {
    setCurrentView(view);
    setSelectedPoemId(poemId);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddPoem = async (newPoem: Poem) => {
    const savedPoem = await supabaseService.createEcho(newPoem);
    if (savedPoem) {
      setUserPoems(prev => [savedPoem, ...prev]);
    } else {
      setUserPoems(prev => [newPoem, ...prev]);
    }
    navigateTo('user-feed');
  };

  const handleAddAdminPoem = async (newPoem: Poem) => {
    const savedPoem = await supabaseService.createAdminPoem(newPoem);
    if (savedPoem) {
      setAdminPoems(prev => [savedPoem, ...prev]);
    }
    navigateTo('feed');
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col selection:bg-neutral-800 selection:text-neutral-100">
      <Header 
        currentView={currentView} 
        onNavigate={navigateTo} 
        isDarkMode={isDarkMode} 
        onToggleTheme={toggleTheme} 
      />

      <main className="flex-grow">
        {isLoading && currentView === 'home' && !dailyLine ? (
          <div className="min-h-[80vh] flex items-center justify-center opacity-20 italic instrument-serif animate-pulse">
            Opening the void...
          </div>
        ) : (
          <div className="animate-fade-in duration-700">
            {currentView === 'home' && (
              <Home dailyLine={dailyLine} onNavigate={navigateTo} />
            )}

            {currentView === 'feed' && (
              <div className="pt-10">
                <div className="max-w-7xl mx-auto px-6 mb-8 text-center animate-fade-in">
                  <h2 className="instrument-serif text-4xl italic opacity-80">Read</h2>
                  <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Curated by Echo Pages</p>
                </div>
                <Feed poems={adminPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
              </div>
            )}

            {currentView === 'user-feed' && (
              <div className="pt-10">
                <div className="max-w-7xl mx-auto px-6 mb-8 text-center animate-fade-in">
                  <h2 className="instrument-serif text-4xl italic opacity-80">By Echoes</h2>
                  <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Community voices</p>
                </div>
                <Feed poems={userPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
              </div>
            )}

            {currentView === 'detail' && selectedPoem && (
              <PoemDetail 
                poem={selectedPoem} 
                onBack={() => navigateTo(adminPoems.some(p => p.id === selectedPoem.id) ? 'feed' : 'user-feed')} 
              />
            )}

            {currentView === 'create' && (
              <CreatePoem onPublish={handleAddPoem} onCancel={() => navigateTo('user-feed')} />
            )}

            {currentView === 'admin' && (
              <AdminPortal onPublish={handleAddAdminPoem} onCancel={() => navigateTo('feed')} />
            )}

            {currentView === 'about' && (
              <About />
            )}
          </div>
        )}
      </main>

      <Footer onAdminClick={() => navigateTo('admin')} />
    </div>
  );
};

export default App;

