interface AdminPortalProps {
  onPublish: (poem: Poem) => void;
  onCancel: () => void;
}

const AdminPortal: React.FC<AdminPortalProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [selectedTone, setSelectedTone] = useState<typeof TONES[number]['id']>('melancholic');
  const [selectedGenre, setSelectedGenre] = useState<string>('Free Verse');
  const [isPublishing, setIsPublishing] = useState(false);

  const handlePublish = async () => {
    if (!content.trim() || !title.trim()) {
      alert("Please provide both a title and the poem content.");
      return;
    }

    setIsPublishing(true);

    try {
      // Use the analysis to get a unique background and metadata,
      // but strictly keep the admin's original title and content.
      const meta = await geminiService.analyzePoem(content);

      const finalPoem: Poem = {
        id: Date.now().toString(),
        title: title,
        content: content,
        author: 'Admin',
        timestamp: Date.now(),
        emotionTag: meta.emotionTag,
        emotionalWeight: meta.emotionalWeight,
        tone: selectedTone as any,
        genre: selectedGenre,
        backgroundColor: meta.backgroundGradient || TONES.find(t => t.id === selectedTone)?.gradient || DEFAULT_GRADIENT
      };

      onPublish(finalPoem);
    } catch (error) {
      console.error("Publication error:", error);
      // Fail-safe publish if AI analysis times out or fails
      const fallbackPoem: Poem = {
        id: Date.now().toString(),
        title: title,
        content: content,
        author: 'Admin',
        timestamp: Date.now(),
        emotionTag: selectedTone.charAt(0).toUpperCase() + selectedTone.slice(1),
        emotionalWeight: 50,
        tone: selectedTone as any,
        genre: selectedGenre,
        backgroundColor: TONES.find(t => t.id === selectedTone)?.gradient || DEFAULT_GRADIENT
      };
      onPublish(fallbackPoem);
    } finally {
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in">
      <div className="space-y-12">
        <div className="flex justify-between items-baseline border-b border-white/5 pb-8">
          <h2 className="instrument-serif text-4xl italic">Admin Publication</h2>
          <button 
            onClick={onCancel}
            className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 transition-opacity"
          >
            Cancel
          </button>
        </div>

        <div className="space-y-10">
          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30">Poem Title</p>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Enter title..."
              className="w-full bg-transparent border-b border-white/10 py-4 focus:border-white/40 focus:outline-none instrument-serif text-4xl"
            />
          </div>

          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30">Poem Content</p>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Paste or type your poem directly here..."
              className="w-full h-96 bg-transparent border border-white/5 p-8 focus:border-white/20 focus:outline-none transition-all serif-font text-2xl italic leading-relaxed whitespace-pre-line"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            <div className="space-y-4">
              <p className="text-[10px] uppercase tracking-widest opacity-30">Atmospheric Tone</p>
              <div className="flex flex-wrap gap-2">
                {TONES.map((tone) => (
                  <button
                    key={tone.id}
                    onClick={() => setSelectedTone(tone.id)}
                    className={`px-5 py-2 border text-[10px] uppercase tracking-widest transition-all ${
                      selectedTone === tone.id ? 'border-white bg-white/5' : 'border-white/10 opacity-40 hover:opacity-100'
                    }`}
                  >
                    {tone.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] uppercase tracking-widest opacity-30">Classification</p>
              <div className="flex flex-wrap gap-2">
                {GENRES.map((genre) => (
                  <button
                    key={genre}
                    onClick={() => setSelectedGenre(genre)}
                    className={`px-5 py-2 border text-[10px] uppercase tracking-widest transition-all ${
                      selectedGenre === genre ? 'border-white bg-white/5' : 'border-white/10 opacity-40 hover:opacity-100'
                    }`}
                  >
                    {genre}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="pt-12">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim() || !title.trim()}
              className="w-full py-6 bg-white text-black text-[11px] uppercase tracking-[0.4em] font-medium hover:bg-neutral-200 transition-all disabled:opacity-20 flex items-center justify-center space-x-4"
            >
              {isPublishing && <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />}
              <span>{isPublishing ? 'Echoing...' : 'Publish to Read Feed'}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

