      // Fallback order if timestamp column differs
      if (error) {
         const retry = await supabase
          .from('admin_poems')
          .select('*')
          .order('created_at', { ascending: false });
         if (retry.error) throw retry.error;
         return (retry.data || []).map(mapFromDb);
