import React, { useState } from 'react';
import { Poem } from '../types';
import { DEFAULT_GRADIENT, TONES } from '../constants';

interface AdminPortalProps {
  onPublish: (poem: Poem) => Promise<void>;
  onCancel: () => void;
}

const AdminPortal: React.FC<AdminPortalProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPublishing, setIsPublishing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handlePublish = async () => {
    if (!content.trim() || !title.trim()) {
      setError("Please provide both a title and the poem content.");
      return;
    }

    setIsPublishing(true);
    setError(null);

    const randomTone = TONES[Math.floor(Math.random() * TONES.length)];

    const newPoem: Poem = {
      id: '', // Database will generate this
      title: title,
      content: content,
      author: 'Admin',
      timestamp: Date.now(),
      emotionTag: 'Curated',
      emotionalWeight: 80,
      tone: randomTone.id as any,
      genre: 'Admin Selection',
      backgroundColor: randomTone.gradient || DEFAULT_GRADIENT
    };

    try {
      await onPublish(newPoem);
    } catch (err) {
      console.error("Publication error:", err);
      setError("The void rejected this echo. (Row-Level Security policy violation)");
    } finally {
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in">
      <div className="space-y-12">
        <div className="flex justify-between items-baseline border-b border-white/5 pb-8">
          <div className="space-y-1">
            <h2 className="instrument-serif text-4xl italic">Direct Upload</h2>
            <p className="text-[10px] uppercase tracking-widest opacity-30">Admin Portal</p>
          </div>
          <button 
            onClick={onCancel}
            className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 transition-opacity"
          >
            Cancel
          </button>
        </div>

        <div className="space-y-12">
          {error && (
            <div className="p-4 bg-red-900/20 border border-red-500/20 text-red-200 text-xs uppercase tracking-widest text-center animate-pulse">
              {error}
            </div>
          )}

          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30">Title</p>
            <input
              type="text"
              value={title}
              onChange={(e) => {
                setTitle(e.target.value);
                if (error) setError(null);
              }}
              placeholder="The title of the echo..."
              className="w-full bg-transparent border-b border-white/10 py-4 focus:border-white/40 focus:outline-none instrument-serif text-4xl"
            />
          </div>

          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30">Content</p>
            <textarea
              value={content}
              onChange={(e) => {
                setContent(e.target.value);
                if (error) setError(null);
              }}
              placeholder="Enter the poem content here..."
              className="w-full h-96 bg-transparent border border-white/5 p-8 focus:border-white/20 focus:outline-none transition-all serif-font text-2xl italic leading-relaxed whitespace-pre-line"
            />
          </div>

          <div className="pt-6">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim() || !title.trim()}
              className="w-full py-6 bg-white text-black text-[11px] uppercase tracking-[0.4em] font-medium hover:bg-neutral-200 transition-all disabled:opacity-20 flex items-center justify-center space-x-4"
            >
              {isPublishing && <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />}
              <span>{isPublishing ? 'Transmitting...' : 'Publish to Curated Feed'}</span>
            </button>
            <p className="text-center mt-6 text-[9px] uppercase tracking-widest opacity-20">
              Note: Supabase RLS policies must allow public inserts for this to succeed.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

