export const supabaseService = {
  async getAdminPoems(): Promise<Poem[]> {
    console.log("Supabase: Fetching curated poems...");
    try {
      // Try fetching with standard created_at ordering
      let { data, error } = await supabase
        .from('admin_poems')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.warn("Supabase: Error fetching with created_at, trying fallback timestamp...");
        const retry = await supabase
          .from('admin_poems')
          .select('*')
          .order('id', { ascending: false }); // Fallback to ID if no timestamps exist
        if (retry.error) throw retry.error;
        data = retry.data;
      }

      const mapped = (data || []).map(mapFromDb);
      console.log(`Supabase: Successfully loaded ${mapped.length} curated poems.`);
      return mapped;
    } catch (e) {
      console.error("Supabase: Critical error fetching curated feed:", e);
      return [];
    }
  },

  async getEchoes(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase
        .from('echoes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        const retry = await supabase
          .from('echoes')
          .select('*')
          .order('id', { ascending: false });
        if (retry.error) throw retry.error;
        return (retry.data || []).map(mapFromDb);
      }
      return (data || []).map(mapFromDb);
    } catch (e) {
      console.error("Supabase: Error fetching echoes", e);
      return [];
    }
  },

  async createEcho(poem: Poem): Promise<Poem | null> {
    try {
      const payload = {
        title: poem.title,
        content: poem.content,
        author: poem.author,
        emotion_tag: poem.emotionTag,
        emotional_weight: poem.emotionalWeight,
        tone: poem.tone,
        genre: poem.genre,
        background_color: poem.backgroundColor
      };

      const { data, error } = await supabase
        .from('echoes')
        .insert([payload])
        .select();

      if (error) throw error;
      return data ? mapFromDb(data[0]) : null;
    } catch (e) {
      console.error("Supabase: Error creating echo", e);
      return null;
    }
  },

  async createAdminPoem(poem: Poem): Promise<Poem | null> {
    console.log("Supabase: Attempting admin publish...");

    // Strategy 1: Full payload
    const fullPayload = {
      title: poem.title,
      content: poem.content,
      author: poem.author || 'Admin',
      background_color: poem.backgroundColor || DEFAULT_GRADIENT,
      emotion_tag: poem.emotionTag || 'Curated',
      emotional_weight: poem.emotionalWeight || 50,
      tone: poem.tone || 'melancholic',
      genre: poem.genre || 'Admin Selection'
    };

    try {
      const { data, error } = await supabase
        .from('admin_poems')
        .insert([fullPayload])
        .select();

      if (error) {
        // If it's specifically an RLS error, we need to let the UI know
        if (error.code === '42501' || error.message.includes('row-level security')) {
          const rlsError = new Error(`RLS Policy Violation: The "admin_poems" table is locked. Run this SQL in Supabase: \n\n CREATE POLICY "Allow public insert" ON public.admin_poems FOR INSERT WITH CHECK (true);`);
          (rlsError as any).code = 'RLS';
          throw rlsError;
        }

        console.warn("Supabase: Full insert failed, trying minimal payload...");
        // Strategy 2: Minimal payload (just title/content)
        const minimalPayload = {
          title: poem.title,
          content: poem.content
        };
        const retry = await supabase
          .from('admin_poems')
          .insert([minimalPayload])
          .select();

        if (retry.error) throw retry.error;
        return retry.data ? mapFromDb(retry.data[0]) : null;
      }

      return data ? mapFromDb(data[0]) : null;
    } catch (e: any) {
      console.error("Supabase Publish Exception:", e.message);
      throw e; // Bubble up to AdminPortal
    }
  }
};

