// Provided Supabase credentials
const supabaseUrl = 'https://wctibhidceonfjmzxbrl.supabase.co';
const supabaseAnonKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6IndjdGliaGlkY2VvbmZqbXp4YnJsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjY2Mzg3NTYsImV4cCI6MjA4MjIxNDc1Nn0.8ZK2qKfAH56Y6rTfBhUidtWbNJhXGTP8IcuSsP9NLsw';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

const ADMIN_TAG = "Curated_Echo";

const mapFromDb = (data: any): Poem => ({
  id: String(data.id),
  title: data.title || 'Untitled',
  content: data.content || '',
  author: data.author === ADMIN_TAG ? 'Admin' : (data.author || 'Observer'),
  timestamp: data.created_at ? new Date(data.created_at).getTime() : Date.now(),
  emotionTag: data.emotion_tag || 'Fragment',
  emotionalWeight: data.emotional_weight || 50,
  tone: data.tone || 'melancholic',
  genre: data.genre || 'Poetry',
  backgroundColor: data.background_color || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
});

const mapToDb = (poem: Poem, isAdmin: boolean = false) => ({
  title: poem.title,
  content: poem.content,
  author: isAdmin ? ADMIN_TAG : poem.author,
  emotion_tag: poem.emotionTag,
  emotional_weight: poem.emotionalWeight,
  tone: poem.tone,
  genre: poem.genre,
  background_color: poem.backgroundColor
  // Note: id and timestamp are excluded to let DB generate them
});

export const supabaseService = {
  async getAdminPoems(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase
        .from('echoes')
        .select('*')
        .eq('author', ADMIN_TAG)
        .order('created_at', { ascending: false });

      if (error) throw error;
      return (data || []).map(mapFromDb);
    } catch (e) {
      console.error("Supabase: Error fetching admin poems", e);
      return [];
    }
  },

  async getEchoes(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase
        .from('echoes')
        .select('*')
        .neq('author', ADMIN_TAG)
        .order('created_at', { ascending: false });

      if (error) throw error;
      return (data || []).map(mapFromDb);
    } catch (e) {
      console.error("Supabase: Error fetching echoes", e);
      return [];
    }
  },

  async createEcho(poem: Poem): Promise<Poem | null> {
    try {
      const dbPoem = mapToDb(poem, false);
      const { data, error } = await supabase
        .from('echoes')
        .insert([dbPoem])
        .select();

      if (error) throw error;
      return data ? mapFromDb(data[0]) : null;
    } catch (e) {
      console.error("Supabase: Error creating echo", e);
      return null;
    }
  },

  async createAdminPoem(poem: Poem): Promise<Poem | null> {
    try {
      const dbPoem = mapToDb(poem, true);
      const { data, error } = await supabase
        .from('echoes')
        .insert([dbPoem])
        .select();

      if (error) throw error;
      return data ? mapFromDb(data[0]) : null;
    } catch (e) {
      console.error("Supabase: Error creating admin poem", e);
      return null;
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types';
import { geminiService } from './services/geminiService';
import { supabaseService } from './services/supabaseService';

import Header from './components/Header';
import Footer from './components/Footer';
import Home from './components/Home';
import Feed from './components/Feed';
import PoemDetail from './components/PoemDetail';
import CreatePoem from './components/CreatePoem';
import About from './components/About';
import AdminPortal from './components/AdminPortal';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [dailyLine, setDailyLine] = useState<string>(() => localStorage.getItem('echo_daily_line') || 'The echoes are louder than the voices.');
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadInitialData = async () => {
      const hasCache = !!localStorage.getItem('echo_daily_line');
      if (hasCache) setIsLoading(false);

      supabaseService.getAdminPoems().then(setAdminPoems);
      supabaseService.getEchoes().then(setUserPoems);

      geminiService.getDailyLine().then(line => {
        setDailyLine(line);
        setIsLoading(false);
      }).catch(() => setIsLoading(false));
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    const html = document.documentElement;
    if (isDarkMode) {
      html.classList.add('dark');
    } else {
      html.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateTo = (view: View, poemId: string | null = null) => {
    setCurrentView(view);
    setSelectedPoemId(poemId);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddPoem = async (newPoem: Poem) => {
    const savedPoem = await supabaseService.createEcho(newPoem);
    if (savedPoem) {
      setUserPoems(prev => [savedPoem, ...prev]);
    }
    navigateTo('user-feed');
  };

  const handleAddAdminPoem = async (newPoem: Poem) => {
    const savedPoem = await supabaseService.createAdminPoem(newPoem);
    if (savedPoem) {
      setAdminPoems(prev => [savedPoem, ...prev]);
      navigateTo('feed');
    } else {
      alert("Submission failed. The void is currently closed.");
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col transition-colors duration-500">
      <Header 
        currentView={currentView} 
        onNavigate={navigateTo} 
        isDarkMode={isDarkMode} 
        onToggleTheme={toggleTheme} 
      />

      <main className="flex-grow">
        {isLoading && currentView === 'home' && !dailyLine ? (
          <div className="min-h-[80vh] flex items-center justify-center opacity-20 italic instrument-serif animate-pulse">
            Opening the void...
          </div>
        ) : (
          <div className="animate-fade-in duration-500">
            {currentView === 'home' && (
              <Home dailyLine={dailyLine} onNavigate={navigateTo} />
            )}

            {currentView === 'feed' && (
              <div className="pt-10">
                <div className="max-w-7xl mx-auto px-6 mb-8 text-center">
                  <h2 className="instrument-serif text-4xl italic opacity-80">Read</h2>
                  <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Curated Fragments</p>
                </div>
                <Feed poems={adminPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
              </div>
            )}

            {currentView === 'user-feed' && (
              <div className="pt-10">
                <div className="max-w-7xl mx-auto px-6 mb-8 text-center">
                  <h2 className="instrument-serif text-4xl italic opacity-80">By Echoes</h2>
                  <p className="text-[10px] uppercase tracking-widest opacity-40 mt-2">Community Echoes</p>
                </div>
                <Feed poems={userPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
              </div>
            )}

            {currentView === 'detail' && selectedPoem && (
              <PoemDetail 
                poem={selectedPoem} 
                onBack={() => navigateTo(adminPoems.some(p => p.id === selectedPoem.id) ? 'feed' : 'user-feed')} 
              />
            )}

            {currentView === 'create' && (
              <CreatePoem onPublish={handleAddPoem} onCancel={() => navigateTo('user-feed')} />
            )}

            {currentView === 'admin' && (
              <AdminPortal onPublish={handleAddAdminPoem} onCancel={() => navigateTo('feed')} />
            )}

            {currentView === 'about' && (
              <About />
            )}
          </div>
        )}
      </main>

      <Footer onAdminClick={() => navigateTo('admin')} />
    </div>
  );
};

export default App;

