    // Select a random brainstorming prompt on mount
    const randomPrompt = BRAINSTORMING_PROMPTS[Math.floor(Math.random() * BRAINSTORMING_PROMPTS.length)];
    setPlaceholder(randomPrompt);
  }, []);

  const handlePublish = async () => {
