const mapFromDb = (data: any): Poem => {
  if (!data) return {} as Poem;

  let ts = Date.now();
  const rawTs = data.timestamp || data.created_at || data.ts;

  if (rawTs) {
    if (typeof rawTs === 'number') {
      ts = rawTs;
    } else {
      const parsed = new Date(rawTs).getTime();
      if (!isNaN(parsed)) ts = parsed;
    }
  }

  return {
    id: String(data.id || Math.random().toString(36).substr(2, 9)),
    title: data.title || 'Untitled',
    content: data.content || '',
    author: data.author || 'Observer',
    timestamp: ts,
    emotionTag: data.emotion_tag || 'Fragment',
    emotional_weight: data.emotional_weight || 50,
    tone: data.tone || 'melancholic',
    genre: data.genre || 'Poetry',
    backgroundColor: data.background_color || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
  } as Poem;
};

const mapToDb = (poem: Poem) => ({
  title: poem.title || 'Untitled',
  content: poem.content || '',
  author: poem.author || 'Observer',
  emotion_tag: poem.emotionTag || 'Fragment',
  emotional_weight: poem.emotionalWeight || 50,
  tone: poem.tone || 'melancholic',
  genre: poem.genre || 'Poetry',
  background_color: poem.backgroundColor || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)',
  timestamp: Math.floor(poem.timestamp || Date.now())
});

export const supabaseService = {
  async getAdminPoems(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase
        .from('admin_poems')
        .select('*');

      if (error) return [];
      return (data || []).map(mapFromDb).sort((a, b) => b.timestamp - a.timestamp);
    } catch (e) {
      return [];
    }
  },

  async getEchoes(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase
        .from('echoes')
        .select('*');

      if (error) return [];
      return (data || []).map(mapFromDb).sort((a, b) => b.timestamp - a.timestamp);
    } catch (e) {
      return [];
    }
  },

  async createEcho(poem: Poem): Promise<Poem | null> {
    try {
      const dbEntry = mapToDb(poem);
      const { data, error } = await supabase
        .from('echoes')
        .insert([dbEntry])
        .select();

      if (error) return null;
      return (data && data.length > 0) ? mapFromDb(data[0]) : null;
    } catch (e) {
      return null;
    }
  },

  async createAdminPoem(poem: Poem): Promise<Poem | null> {
    try {
      const dbEntry = mapToDb(poem);
      const { data, error } = await supabase
        .from('admin_poems')
        .insert([dbEntry])
        .select();

      if (error) return null;
      return (data && data.length > 0) ? mapFromDb(data[0]) : null;
    } catch (e) {
      return null;
    }
  },

  async getDailyEchoes(): Promise<DailyEcho[]> {
    try {
      const { data, error } = await supabase
        .from('daily_echoes')
        .select('*')
        .order('date', { ascending: false });

      if (error) throw error;
      return (data || []).map(d => ({
        date: d.date,
        line: d.line,
        timestamp: new Date(d.date).getTime()
      }));
    } catch (e) {
      // Fallback to local storage if table doesn't exist
      const local = localStorage.getItem('echo_history');
      return local ? JSON.parse(local) : [];
    }
  },

  async saveDailyEcho(echo: DailyEcho): Promise<void> {
    try {
      const { error } = await supabase
        .from('daily_echoes')
        .upsert({ date: echo.date, line: echo.line });

      if (error) throw error;
    } catch (e) {
      // Fallback to local storage
      const local = localStorage.getItem('echo_history');
      const history = local ? JSON.parse(local) : [];
      if (!history.find((h: DailyEcho) => h.date === echo.date)) {
        history.unshift(echo);
        localStorage.setItem('echo_history', JSON.stringify(history.slice(0, 30)));
      }
    }
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata, DailyEcho } from "../types.ts";
import { supabaseService } from "./supabaseService.ts";

const CACHE_KEY_PREFIX = 'echo_daily_line_';

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const today = new Date().toISOString().split('T')[0];
    const cacheKey = CACHE_KEY_PREFIX + today;
    const cachedLine = localStorage.getItem(cacheKey);

    if (cachedLine) return cachedLine;

    // Check Supabase first for a global daily echo
    const history = await supabaseService.getDailyEchoes();
    const existing = history.find(h => h.date === today);
    if (existing) {
      localStorage.setItem(cacheKey, existing.line);
      return existing.line;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation. Maximum 10 words.",
        config: {
            temperature: 0.9,
            topP: 0.95,
        }
      });
      const newLine = response.text?.trim() || "Silence is the only thing we truly own.";

      // Save globally and locally
      const dailyEcho: DailyEcho = {
        date: today,
        line: newLine,
        timestamp: Date.now()
      };

      await supabaseService.saveDailyEcho(dailyEcho);
      localStorage.setItem(cacheKey, newLine);

      return newLine;
    } catch (error) {
      console.error("Error generating daily line:", error);
      return "The echoes are louder than the voices.";
    }
  },

  async analyzePoem(content: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this poem for its emotional characteristics. Provide a short emotion tag (one word), an emotional weight (0-100), a suggested title, and a subtle CSS linear-gradient background (dark colors) that reflects the mood. Poem: "${content}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'Untitled Echo',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    } catch (error) {
      console.error("Error analyzing poem:", error);
      return {
        emotionTag: 'Quiet',
        emotionalWeight: 50,
        suggestedTitle: 'Fragment',
        backgroundGradient: 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)'
      };
    }
  }
};

