export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const mapFromDb = (data: any): Poem => ({
  id: String(data.id),
  title: data.title || 'Untitled',
  content: data.content || '',
  author: data.author || 'Anonymous',
  userId: data.user_id || '',
  timestamp: new Date(data.created_at || data.timestamp).getTime(),
  emotionTag: data.emotion_tag || 'Echo',
  emotionalWeight: data.emotional_weight || 50,
  score: data.score || 0,
  tone: data.tone || 'melancholic',
  genre: data.genre || 'Free Verse',
  backgroundColor: data.background_color || '#000'
});

export const supabaseService = {
  async getEchoes(): Promise<Poem[]> {
    const { data } = await supabase.from('echoes').select('*').order('created_at', { ascending: false });
    return (data || []).map(mapFromDb);
  },

  async getAdminPoems(): Promise<Poem[]> {
    const { data } = await supabase.from('admin_poems').select('*').order('created_at', { ascending: false });
    return (data || []).map(mapFromDb);
  },

  async createEcho(poem: Partial<Poem>): Promise<Poem | null> {
    const { data, error } = await supabase.from('echoes').insert([{
      title: poem.title,
      content: poem.content,
      author: poem.author,
      user_id: poem.userId,
      emotion_tag: poem.emotionTag,
      emotional_weight: poem.emotionalWeight,
      score: poem.score,
      genre: poem.genre,
      background_color: poem.backgroundColor,
    }]).select();
    if (error) return null;
    return data ? mapFromDb(data[0]) : null;
  },

  async getLeaderboard(): Promise<LeaderboardEntry[]> {
    // Aggregating weekly leaderboard logic
    const oneWeekAgo = new Date();
    oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

    const { data, error } = await supabase
      .from('echoes')
      .select('user_id, author, score')
      .gt('created_at', oneWeekAgo.toISOString());

    if (error) return [];

    const userMap: Record<string, { total: number, count: number, name: string }> = {};
    data.forEach(d => {
      if (!userMap[d.user_id]) userMap[d.user_id] = { total: 0, count: 0, name: d.author };
      userMap[d.user_id].total += d.score;
      userMap[d.user_id].count += 1;
    });

    return Object.entries(userMap).map(([id, val]) => ({
      userId: id,
      username: val.name,
      score: Math.round(val.total / val.count),
      poemCount: val.count
    })).sort((a, b) => b.score - a.score);
  }
};

