import React, { useState, useEffect } from 'react';
import { Poem } from '../types.ts';
import { geminiService } from '../services/geminiService.ts';
import { supabase } from '../services/supabaseService.ts';
import { GENRES } from '../constants.ts';

interface CreatePoemProps {
  onPublish: (poem: Poem) => void;
  onCancel: () => void;
}

const CreatePoem: React.FC<CreatePoemProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [genre, setGenre] = useState<string>(GENRES[0]);
  const [isPublishing, setIsPublishing] = useState(false);
  const [user, setUser] = useState<any>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });
  }, []);

  const handlePublish = async () => {
    if (!content.trim()) return;
    if (!user) {
      alert("You must enter the void (login) before echoing.");
      return;
    }

    setIsPublishing(true);

    try {
      const meta = await geminiService.analyzePoem(content, genre);

      if (!meta.isSafe) {
        alert("The void rejected this frequency. Maintain sanctity.");
        setIsPublishing(false);
        return;
      }

      const finalPoem: Partial<Poem> = {
        title: title.trim() || meta.suggestedTitle,
        content: content.trim(),
        author: user.email?.split('@')[0] || 'Observer',
        userId: user.id,
        timestamp: Date.now(),
        emotionTag: meta.emotionTag,
        emotionalWeight: meta.emotionalWeight,
        score: meta.genreScore,
        genre: genre,
        backgroundColor: meta.backgroundGradient
      };

      onPublish(finalPoem as Poem);
    } catch (error) {
      console.error("Publishing error:", error);
      alert("Transmission interrupted.");
    } finally {
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in">
      <div className="space-y-12">
        <header className="flex justify-between items-baseline border-b border-echo-border pb-8">
          <div className="space-y-1">
            <h2 className="instrument-serif text-4xl italic">New Echo</h2>
            <p className="text-[10px] uppercase tracking-widest opacity-30">Select a genre to be measured.</p>
          </div>
          <button onClick={onCancel} className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100">Cancel</button>
        </header>

        <div className="space-y-10">
          <div className="flex flex-wrap gap-4">
            {GENRES.map(g => (
              <button 
                key={g}
                onClick={() => setGenre(g)}
                className={`px-6 py-2 text-[10px] uppercase tracking-widest border transition-all ${genre === g ? 'bg-echo-text text-echo-bg border-echo-text' : 'border-echo-border opacity-40 hover:opacity-100'}`}
              >
                {g}
              </button>
            ))}
          </div>

          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Title (Optional)"
            className="w-full bg-transparent border-b border-echo-border py-4 focus:border-echo-text focus:outline-none instrument-serif text-4xl"
          />

          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Whisper into the dark..."
            className="w-full h-96 bg-transparent border border-echo-border p-8 focus:border-echo-text focus:outline-none transition-all serif-font text-2xl italic leading-relaxed"
          />

          <div className="pt-8 space-y-4">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim()}
              className="w-full py-6 bg-echo-text text-echo-bg text-[11px] uppercase tracking-[0.4em] font-bold hover:opacity-90 transition-all disabled:opacity-20 flex items-center justify-center space-x-4"
            >
              {isPublishing ? 'Analyzing Accuracy...' : 'Echo into the Void'}
            </button>
            <p className="text-center text-[10px] uppercase tracking-widest opacity-20">
              AI calculates genre accuracy for your rank.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

