import React, { useState } from 'react';
import { supabase } from '../services/supabaseService.ts';

const Auth: React.FC = () => {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    // Explicitly provide the current origin as the redirect URL
    const { error } = await supabase.auth.signInWithOtp({ 
      email,
      options: {
        emailRedirectTo: window.location.origin
      }
    });

    if (error) {
      setMessage(error.message);
      setIsSuccess(false);
    } else {
      setMessage('A magic link has been sent to your frequency. Check your inbox.');
      setIsSuccess(true);
    }
    setLoading(false);
  };

  return (
    <div className="max-w-md mx-auto py-40 px-6 space-y-12 animate-fade-in text-center">
      <h1 className="instrument-serif italic text-6xl">Entry</h1>
      <p className="serif-font text-lg italic opacity-60">To own your echoes, we must recognize your frequency.</p>

      {!isSuccess ? (
        <form onSubmit={handleLogin} className="space-y-6">
          <input 
            type="email" 
            placeholder="your@frequency.com"
            className="w-full bg-transparent border-b border-echo-border py-4 focus:outline-none focus:border-echo-text text-center text-xl transition-colors"
            value={email}
            onChange={e => setEmail(e.target.value)}
            required
          />
          <button 
            type="submit" 
            disabled={loading}
            className="w-full py-4 bg-echo-text text-echo-bg uppercase tracking-widest text-[11px] font-bold hover:bg-white transition-all disabled:opacity-30"
          >
            {loading ? 'Transmitting...' : 'Request Access'}
          </button>
        </form>
      ) : (
        <div className="p-8 border border-echo-border bg-white/5 space-y-4 animate-fade-in">
           <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin mx-auto mb-4" />
           <p className="text-sm tracking-widest uppercase opacity-80">{message}</p>
           <p className="text-[10px] uppercase opacity-30">You may close this tab or wait for the link.</p>
        </div>
      )}

      {message && !isSuccess && (
        <p className="text-xs tracking-widest uppercase text-red-400/60 font-medium">
          {message}
        </p>
      )}
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import AdminPortal from './components/AdminPortal.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [dailyLine, setDailyLine] = useState<string>('');
  const [isLoading, setIsLoading] = useState(true);

  const syncStateWithHash = () => {
    const hash = window.location.hash || '#/';

    // Ignore Supabase auth tokens so they don't break the UI router
    if (hash.includes('access_token=') || hash.includes('type=magiclink') || hash.includes('type=recovery')) {
      return;
    }

    if (hash.startsWith('#/p/')) {
      setSelectedPoemId(hash.replace('#/p/', ''));
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/admin': 'admin',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };
      setCurrentView(views[hash] || 'home');
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    window.addEventListener('hashchange', syncStateWithHash);
    syncStateWithHash();
    refreshData();

    // Listen for Auth changes to handle redirects after login
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN') {
        navigateTo('profile');
      }
    });

    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    return () => {
      window.removeEventListener('hashchange', syncStateWithHash);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddCommunityPoem = async (newPoem: Partial<Poem>) => {
    const savedPoem = await supabaseService.createEcho(newPoem);
    if (savedPoem) {
      setUserPoems(prev => [savedPoem, ...prev]);
      navigateTo('user-feed');
    }
  };

  const handleAddCuratePoem = async (newPoem: Partial<Poem>) => {
    const savedPoem = await supabaseService.createAdminCurate(newPoem);
    if (savedPoem) {
      setAdminPoems(prev => [savedPoem, ...prev]);
      navigateTo('feed');
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col transition-colors duration-500 bg-echo-bg text-echo-text">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="animate-fade-in duration-500">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Read</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">Curated Curiosities</p>
              </header>
              <Feed poems={adminPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Echoes</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">The Community Stream</p>
              </header>
              <Feed poems={userPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => navigateTo(selectedPoem.author === 'Admin' ? 'feed' : 'user-feed')} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handleAddCommunityPoem} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
