  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [cooldown, setCooldown] = useState(0);

  useEffect(() => {
    let timer: number;
    if (cooldown > 0) {
      timer = window.setInterval(() => {
        setCooldown(prev => prev - 1);
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [cooldown]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (cooldown > 0) return;

    setLoading(true);
    setError('');

    // Using current origin for redirect. Ensure this is in Supabase Dashboard -> Auth -> URL Config
    const { error } = await supabase.auth.signInWithOtp({ 
      email,
      options: {
        emailRedirectTo: window.location.origin
      }
    });

    if (error) {
      if (error.message.includes('rate limit')) {
        setError('Frequency overload. Please wait 60 seconds before requesting another link.');
        setCooldown(60);
      } else {
        setError(error.message);
      }
      setIsSuccess(false);
    } else {
      setIsSuccess(true);
      setCooldown(60); // Prevent spamming after success
    }
    setLoading(false);
