              value={email}
              onChange={e => setEmail(e.target.value)}
              required
              disabled={loading}
            />
          </div>
          <button 
            type="submit" 
            disabled={loading || cooldown > 0}
            className="w-full py-4 bg-echo-text text-echo-bg uppercase tracking-widest text-[11px] font-bold hover:bg-white transition-all disabled:opacity-30 disabled:cursor-not-allowed"
          >
            {loading ? 'Transmitting...' : cooldown > 0 ? `Wait ${cooldown}s` : 'Request Access'}
          </button>
        </form>
      ) : (
        <div className="p-10 border border-echo-border bg-white/[0.02] space-y-6 animate-fade-in">
           <div className="w-10 h-10 border-2 border-white/10 border-t-white rounded-full animate-spin mx-auto" />
