        await authService.signup(email, password, displayName);
        setSuccess(true);
        // Inform user about next steps (e.g., login or check email if confirmation is on)
        setError('');
        alert("Account initialized. Please log in to confirm your identity.");
        setIsLogin(true);
        setLoading(false);
        setSuccess(false);
