import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types.ts";

const CACHE_KEY = 'echo_daily_line_v1';
const CACHE_TS = 'echo_daily_ts_v1';

const FALLBACK_SEEDS = [
  "The stars are just holes in the ceiling of a house we forgot we built.",
  "Silence is a conversation we aren't brave enough to have yet.",
  "We are all just ghosts wearing skin, looking for a place to haunt.",
  "Memory is a mirror that only shows the things we've lost.",
  "The wind doesn't blow; it's just the world trying to catch its breath.",
  "Ink is the blood of a heart that learned to speak.",
  "We are the architects of our own hauntings.",
  "Shadows are just light that lost its way home."
];

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    // If cache is fresh (less than 24 hours), use it immediately
    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      // Fallback to random seed on failure
      const randomSeed = FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
      return cached || randomSeed;
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Analyze this poem fragment with high literary intelligence. 
        1. Classify emotion (exactly 1 word).
        2. Emotional weight (integer 0-100).
        3. If no title provided (None), suggest a highly specific and poetic title based strictly on its genre and thematic context. DO NOT use generic words like "Fragment", "Untitled", or "Echo".
        4. Dark, moody CSS gradient representing the poem's soul.
        5. isSafe: boolean. Is the content safe for general audiences?
        6. containsRestricted: boolean. Does it contain ANY profanity, explicit content, or toxic language? Be strict.
        7. detectedGenre: Identify which fits best: Noir, Ethereal, Minimalist, Free Verse, Prose, or Haiku.
        8. genreScore: integer 0-100. Calculate how precisely the poem adheres to the technical and tonal requirements of the detected genre.

        Title provided: "${title || 'None'}"
        Poem: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN },
              detectedGenre: { type: Type.STRING },
              genreScore: { type: Type.NUMBER }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "isSafe", "containsRestricted", "detectedGenre", "genreScore"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'A Whisper in the Dark',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)',
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false,
        detectedGenre: result.detectedGenre || 'Free Verse',
        genreScore: result.genreScore || 75
      };
    } catch (error) {
      console.error("Analysis Error:", error);
      return {
        emotionTag: 'Static',
        emotionalWeight: 0,
        suggestedTitle: 'The Unnamed Fragment',
        backgroundGradient: 'linear-gradient(135deg, #000 0%, #111 100%)',
        isSafe: true,
        containsRestricted: false,
        detectedGenre: 'Free Verse',
        genreScore: 75
      };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import AdminPortal from './components/AdminPortal.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);

  // Instant Render Strategy: Initialize synchronously from local cache or a default
  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  const syncStateWithHash = async (isInitialLoad = false) => {
    // MVP Requirement: On page refresh (initial load), always force Home.
    if (isInitialLoad) {
      window.location.hash = '#/';
      setCurrentView('home');
      setSelectedPoemId(null);
      return;
    }

    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const protectedViews: View[] = ['profile', 'create', 'admin'];

    if (hash.startsWith('#/p/')) {
      const id = hash.replace('#/p/', '');
      setSelectedPoemId(id);
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/admin': 'admin',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      if (protectedViews.includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      if (currentView !== 'detail') {
        setPreviousView(currentView);
      }
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash(false);
    window.addEventListener('hashchange', handleHashChange);

    // Initial Load Logic
    syncStateWithHash(true);
    refreshData();

    // Silent fetch update for Daily Echo
    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash(false);
      }
      if (event === 'SIGNED_OUT') {
        sessionStorage.removeItem('echo_onboarded');
        navigateTo('home');
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddCommunityPoem = async (newPoem: Partial<Poem>) => {
    const savedPoem = await supabaseService.createEcho(newPoem);
    if (savedPoem) {
      setUserPoems(prev => [savedPoem, ...prev]);
      navigateTo('user-feed');
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  const handleBackFromDetail = (poem: Poem) => {
    if (previousView === 'feed' || previousView === 'user-feed') {
      navigateTo(previousView);
    } else {
      const fallback = poem.author === 'Admin' ? 'feed' : 'user-feed';
      navigateTo(fallback);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text relative">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="animate-fade-in duration-500">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Read</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">Curated Curiosities</p>
              </header>
              <Feed poems={adminPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Echoes</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">The Community Stream</p>
              </header>
              <Feed poems={userPoems} onSelectPoem={(id) => navigateTo('detail', id)} />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => handleBackFromDetail(selectedPoem)} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handleAddCommunityPoem} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
          {currentView === 'privacy' && <Privacy />}
          {currentView === 'admin' && <AdminPortal onPublish={() => {}} onCancel={() => navigateTo('home')} />}
        </div>
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-echo-bg/95 backdrop-blur-xl animate-fade-in p-6">
          <div className="max-w-md w-full text-center space-y-10">
            <h2 className="instrument-serif italic text-6xl">Echo Pages Guide</h2>
            <div className="space-y-6 serif-font text-xl opacity-70 italic">
              <p>Welcome to a sanctuary for the unspoken.</p>
              <p>Observe the curated 'Read' feed, contribute your own 'Echoes', and track your mastery in the 'Ranks'.</p>
              <p>Every fragment you commit is evaluated for genre precision and emotional depth.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-5 border border-echo-text/20 hover:border-echo-text transition-all text-[11px] uppercase tracking-[0.4em]"
            >
              Begin Observation
            </button>
          </div>
        </div>
      )}

      <Footer onAdminClick={() => navigateTo('admin')} onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

