const mapFromDb = (data: any): Poem => ({
  id: String(data.id),
  title: data.title || 'Untitled',
  content: data.content || '',
  author: data.author || 'Anonymous',
  userId: data.user_id || '',
  timestamp: data.created_at ? new Date(data.created_at).getTime() : Date.now(),
  emotionTag: data.emotion_tag || 'Echo',
  emotionalWeight: Number(data.emotional_weight) || 50,
  score: Number(data.score) || 75,
  tone: (data.tone as any) || 'melancholic',
  genre: data.genre || 'Free Verse',
  backgroundColor: data.background_color || 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
});

export const supabaseService = {
  async getEchoes(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase.from('echoes').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return (data || []).map(mapFromDb);
    } catch (e) { return []; }
  },

  async getAdminPoems(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase.from('admin_poems').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return (data || []).map(mapFromDb);
    } catch (e) { return []; }
  },

  async createEcho(poem: Partial<Poem>): Promise<Poem | null> {
    const payload = {
      title: poem.title,
      content: poem.content,
      author: poem.author,
      user_id: poem.userId,
      emotion_tag: poem.emotionTag,
      emotional_weight: poem.emotionalWeight,
      score: poem.score || 75,
      genre: poem.genre,
      tone: poem.tone || 'melancholic',
      background_color: poem.backgroundColor,
    };
    const { data, error } = await supabase.from('echoes').insert([payload]).select();
    if (error) {
      console.error("Echo Creation Error:", error);
      return null;
    }
    return data ? mapFromDb(data[0]) : null;
  },

  async getLeaderboard(): Promise<LeaderboardEntry[]> {
    try {
      const { data, error } = await supabase.from('echoes').select('user_id, author, score');
      if (error) return [];

      const userMap: Record<string, { total: number, count: number, name: string }> = {};
      data?.forEach(d => {
        if (!d.user_id) return;
        if (!userMap[d.user_id]) userMap[d.user_id] = { total: 0, count: 0, name: d.author || 'Anonymous' };
        userMap[d.user_id].total += 75; // Use 75 as MVP baseline for participation
        userMap[d.user_id].count += 1;
      });

      return Object.entries(userMap)
        .map(([id, val]) => ({
          userId: id,
          username: val.name,
          displayName: val.name,
          score: 75,
          poemCount: val.count
        }))
        .sort((a, b) => b.poemCount - a.poemCount)
        .slice(0, 10);
    } catch (e) { return []; }
  }
};

import React, { useState, useEffect } from 'react';
import { supabase, authService } from '../services/supabaseService.ts';

const Auth: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) window.location.hash = '#/profile';
    });
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (loading) return;

    if (!email.includes('@')) {
      setError('A valid frequency (email) is required.');
      return;
    }
    if (password.length < 6) {
      setError('Sequence must be at least 6 characters.');
      return;
    }
    if (!isLogin && !displayName.trim()) {
      setError('An identity name is required for registration.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      if (isLogin) {
        await authService.login(email, password);
        setSuccess(true);
        setTimeout(() => {
          window.location.hash = '#/profile';
        }, 800);
      } else {
        await authService.signup(email, password, displayName);
        // Supabase often requires confirmation unless it's disabled in settings.
        // We notify user and switch to login view.
        alert("Identity initialized successfully. Please log in to confirm your frequency.");
        setIsLogin(true);
        setLoading(false);
