      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      const randomSeed = FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
      return cached || randomSeed;
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Perform a strict literary analysis of this poem. 

        TASK: Identify the single most appropriate primary genre strictly from this list: [${GENRE_POOL}].

        CRITICAL RULES:
        1. NO INVENTION: Choose ONLY from the provided list.
        2. MEANING-BASED: Detection must be based on theme, meaning, and emotional intent.
        3. AVOID FORM DEFAULTS: Do NOT choose "Free Verse" unless the poem's form is its defining literary feature. 
        4. NO STATIC SCORES: Calculate a unique match percentage (55-95%) reflecting semantic alignment. Never 100%.
        5. OUTPUT: strictly JSON.

        FIELDS:
        - emotionTag: Single word emotion.
        - emotionalWeight: Integer 0-100.
        - suggestedTitle: Specific poetic title if "${title || 'None'}" is 'None'.
        - backgroundGradient: CSS linear gradient.
        - isSafe: content safety check.
        - detectedGenre: The chosen genre.
        - genreScore: The unique calculated match percentage (55-95).

        Poem Content: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN },
              detectedGenre: { type: Type.STRING },
              genreScore: { type: Type.NUMBER }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "isSafe", "containsRestricted", "detectedGenre", "genreScore"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'A Whisper in the Dark',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)',
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false,
        detectedGenre: result.detectedGenre || 'Fragmentary',
        genreScore: (result.genreScore >= 55 && result.genreScore <= 95) ? result.genreScore : 78
      };
    } catch (error) {
      console.error("Analysis Error:", error);
      return {
        emotionTag: 'Static',
        emotionalWeight: 0,
        suggestedTitle: 'The Unnamed Fragment',
        backgroundGradient: 'linear-gradient(135deg, #000 0%, #111 100%)',
        isSafe: true,
        containsRestricted: false,
        detectedGenre: 'Fragmentary',
        genreScore: 55
      };
    }
  }
};

import React from 'react';
import { Poem } from '../types.ts';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  variant?: 'list' | 'grid';
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, variant = 'grid' }) => {
  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    const d = String(date.getDate()).padStart(2, '0');
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const y = date.getFullYear();
    return `${d}-${m}-${y}`;
  };

  const containerClass = "max-w-7xl mx-auto px-6 py-12";
  const gridClass = "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10";

  return (
    <div className={containerClass}>
      <div className={gridClass}>
        {poems.map((poem, index) => (
          <article 
            key={poem.id}
            onClick={() => onSelectPoem(poem.id)}
            className="group cursor-pointer border border-echo-border p-10 flex flex-col justify-between hover:bg-white/[0.02] transition-colors animate-fade-in"
            style={{ animationDelay: `${index * 50}ms`, animationFillMode: 'both' }}
          >
            <div className="space-y-10">
              <div className="text-[11px] uppercase tracking-[0.3em] font-bold text-echo-text/80">
                {poem.genre} · {poem.score}% Match
              </div>

              <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-none group-hover:italic transition-all duration-300">
                {poem.title || 'UNTITLED FRAGMENT'}
              </h2>
            </div>

            <div className="space-y-6 mt-16">
              <hr className="border-echo-border opacity-50" />

              <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-medium text-echo-text/50">
                <span className="italic font-normal">Posted by @{poem.author}</span>
                <span className="font-mono">{formatDate(poem.timestamp)}</span>
              </div>

              <div className="text-[10px] uppercase tracking-[0.5em] font-bold text-echo-text/20 group-hover:text-echo-text/80 transition-all pt-2">
                Observe Echo
              </div>
            </div>
          </article>
        ))}
      </div>

      {poems.length === 0 && (
        <div className="text-center py-40 opacity-20 instrument-serif italic text-2xl">
          The void remains empty.
        </div>
      )}
    </div>
  );
};

