export const supabaseService = {
  async getEchoes(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase.from('echoes').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return (data || []).map(d => mapFromDb(d, 'echoes'));
    } catch (e) { return []; }
  },

  async getAdminPoems(): Promise<Poem[]> {
    try {
      const { data, error } = await supabase.from('admin_poems').select('*').order('created_at', { ascending: false });
      if (error) return [];
      return (data || []).map(d => mapFromDb(d, 'read'));
    } catch (e) { return []; }
  },

  async createEcho(poem: Partial<Poem>): Promise<Poem | null> {
    const payload = {
      title: poem.title || 'Untitled',
      content: poem.content,
      author: poem.author,
      user_id: poem.userId,
      emotion_tag: poem.emotionTag || 'Echo',
      emotional_weight: Math.round(poem.emotionalWeight || 50),
      score: Math.round(poem.score ?? 0),
      genre: poem.genre || 'Echo',
      background_color: poem.backgroundColor || 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
    };

    const { data, error } = await supabase.from('echoes').insert([payload]).select();
    if (error) {
      console.error("Supabase Echo Creation Error:", error);
      return null;
    }
    return (data && data.length > 0) ? mapFromDb(data[0], 'echoes') : null;
  },

  async createAdminPoem(poem: Partial<Poem>): Promise<Poem | null> {
    const payload = {
      title: poem.title || 'Untitled',
      content: poem.content,
      author: 'Admin',
      user_id: poem.userId || 'admin',
      emotion_tag: poem.emotionTag || 'Curated',
      emotional_weight: Math.round(poem.emotionalWeight || 50),
      score: Math.round(poem.score ?? 100),
      genre: poem.genre || 'Curated',
      background_color: poem.backgroundColor || 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
    };

    const { data, error } = await supabase.from('admin_poems').insert([payload]).select();
    if (error) {
      console.error("Supabase Admin Poem Creation Error:", error);
      return null;
    }
    return (data && data.length > 0) ? mapFromDb(data[0], 'read') : null;
  },

  async updatePoem(id: string, visibility: 'read' | 'echoes', updates: Partial<Poem>): Promise<Poem | null> {
    const table = visibility === 'read' ? 'admin_poems' : 'echoes';
    const payload: any = {};

    if (updates.title !== undefined) payload.title = updates.title;
    if (updates.emotionTag !== undefined) payload.emotion_tag = updates.emotionTag;
    if (updates.emotionalWeight !== undefined) payload.emotional_weight = Math.round(updates.emotionalWeight);
    if (updates.score !== undefined) payload.score = Math.round(updates.score);
    if (updates.genre !== undefined) payload.genre = updates.genre;
    if (updates.backgroundColor !== undefined) payload.background_color = updates.backgroundColor;

    const numericId = Number(id);
    const filterId = isNaN(numericId) ? id : numericId;

    const { data, error } = await supabase.from(table).update(payload).eq('id', filterId).select();
    if (error) {
      console.error(`Supabase Update Error (${table}):`, error);
      return null;
    }
    return (data && data.length > 0) ? mapFromDb(data[0], visibility) : null;
  },

  async getLeaderboard(): Promise<LeaderboardEntry[]> {
    try {
      const { data, error } = await supabase.from('echoes').select('user_id, author, score');
      if (error) return [];

      const userMap: Record<string, { totalScore: number, count: number, name: string }> = {};
      data?.forEach(d => {
        if (!d.user_id) return;
        if (!userMap[d.user_id]) {
          userMap[d.user_id] = { totalScore: 0, count: 0, name: d.author || 'Anonymous' };
        }
        userMap[d.user_id].totalScore += (d.score ?? 0);
        userMap[d.user_id].count += 1;
      });

      return Object.entries(userMap)
        .map(([id, val]) => ({
          userId: id,
          username: val.name,
          displayName: val.name,
          score: Math.round(val.totalScore / val.count),
          poemCount: val.count
        }))
        .sort((a, b) => b.poemCount - a.poemCount || b.score - a.score)
        .slice(0, 10);
    } catch (e) { return []; }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  const checkAdmin = (user: any) => {
    return !!user?.email && ADMIN_EMAILS.includes(user.email);
  };

  const syncStateWithHash = async (isInitialLoad = false) => {
    if (isInitialLoad) {
      window.location.hash = '#/';
      setCurrentView('home');
      setSelectedPoemId(null);
      return;
    }

    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const protectedViews: View[] = ['profile', 'create'];

    if (hash.startsWith('#/p/')) {
      const id = hash.replace('#/p/', '');
      setSelectedPoemId(id);
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      if (protectedViews.includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      if (currentView !== 'detail') {
        setPreviousView(currentView);
      }
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash(false);
    window.addEventListener('hashchange', handleHashChange);

    syncStateWithHash(true);
    refreshData();

    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setIsAdmin(checkAdmin(session?.user));
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash(false);
      }
      if (event === 'SIGNED_OUT') {
        sessionStorage.removeItem('echo_onboarded');
        navigateTo('home');
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const isUserAdmin = checkAdmin(session?.user);
      const visibility = isUserAdmin ? 'read' : 'echoes';

      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        title: newPoem.title || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Echo',
        backgroundColor: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
      };

      let savedPoem: Poem | null = null;
      if (isUserAdmin) {
        savedPoem = await supabaseService.createAdminPoem(skeletonPoem);
      } else {
        savedPoem = await supabaseService.createEcho(skeletonPoem);
      }

      if (!savedPoem) {
        throw new Error("Supabase rejected the fragment.");
      }

      // Sync UI and Redirect immediately
      if (isUserAdmin) {
        setAdminPoems(prev => [savedPoem!, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [savedPoem!, ...prev]);
        navigateTo('user-feed');
      }

      // Background Calibration
      const targetPoemId = savedPoem.id;
      (async () => {
        try {
          const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title || '');
          const updates: Partial<Poem> = {
            title: newPoem.title || meta.suggestedTitle,
            emotionTag: meta.emotionTag,
            emotionalWeight: meta.emotionalWeight,
            score: meta.genreScore,
            genre: meta.detectedGenre,
            backgroundColor: meta.backgroundGradient
          };

          const updated = await supabaseService.updatePoem(targetPoemId, visibility, updates);
          if (updated) {
            if (visibility === 'read') {
              setAdminPoems(prev => prev.map(p => p.id === updated.id ? updated : p));
            } else {
              setUserPoems(prev => prev.map(p => p.id === updated.id ? updated : p));
            }
          }
        } catch (bgErr) {
          console.error("Background fragment calibration failed:", bgErr);
        }
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Failed to commit fragment. The frequency was interrupted.");
      throw err; 
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  const handleBackFromDetail = (poem: Poem) => {
    if (previousView === 'feed' || previousView === 'user-feed') {
      navigateTo(previousView);
    } else {
      const fallback = poem.visibility === 'read' ? 'feed' : 'user-feed';
      navigateTo(fallback);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text relative">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="animate-fade-in duration-500">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Read</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">Curated Curiosities</p>
              </header>
              <Feed 
                variant="grid" 
                poems={adminPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Echoes</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">The Community Stream</p>
              </header>
              <Feed 
                variant="grid" 
                poems={userPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => handleBackFromDetail(selectedPoem)} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
          {currentView === 'privacy' && <Privacy />}
        </div>
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-echo-bg/95 backdrop-blur-xl animate-fade-in p-6">
          <div className="max-w-md w-full text-center space-y-10">
            <h2 className="instrument-serif italic text-6xl">Echo Pages Guide</h2>
            <div className="space-y-6 serif-font text-xl opacity-70 italic">
              <p>Welcome to a sanctuary for the unspoken.</p>
              <p>Observe the curated 'Read' feed, contribute your own 'Echoes', and track your mastery in the 'Ranks'.</p>
              <p>Every fragment you commit is evaluated for genre precision and emotional depth.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-5 border border-echo-text/20 hover:border-echo-text transition-all text-[11px] uppercase tracking-[0.4em]"
            >
              Begin Observation
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

