      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `Perform a high-fidelity literary analysis on this fragment.

        TASK:
        1. genre: Select the SINGLE most dominant genre from the GENRE POOL provided. Do not use generic terms if a more specific one fits.
        2. score: Calculate a "Genre Match Score" (55-95) indicating how strongly the text adheres to the conventions of the chosen genre.
           - 90-95: Masterful adherence to form and tone.
           - 75-89: Clear alignment with some creative variation.
           - 55-74: Nuanced or experimental alignment.
        3. justification: A 1-sentence mini-explanation of why this genre was chosen and what structural/tonal elements support the score.
        4. emotionTag: A 1-2 word mood descriptor.
        5. emotionalWeight: Intensity of mood (0-100).
        6. suggestedTitle: If the input title is blank/generic, generate a 2-5 word haunting title.
        7. backgroundGradient: A CSS linear-gradient(135deg, color1, color2) representing the mood.

        GENRE POOL: [${GENRE_POOL}]

        INPUT TITLE: "${title || ''}"
        INPUT CONTENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN },
              genre: { type: Type.STRING },
              score: { type: Type.NUMBER },
              justification: { type: Type.STRING }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "isSafe", "containsRestricted", "genre", "score", "justification"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Strict enforcement of the 55-95 range for 'Match Percentage'
      let finalScore = typeof result.score === 'number' ? Math.round(result.score) : 55;
      finalScore = Math.min(95, Math.max(55, finalScore));

      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'A Whisper in the Dark',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)',
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false,
        genre: result.genre || 'Minimalist',
        score: finalScore,
        justification: result.justification || 'Analyzed based on atmospheric resonance.'
      };
    } catch (error) {
      console.error("Spectral Analysis Error:", error);
      return {
        emotionTag: 'Echo',
        emotionalWeight: 50,
        suggestedTitle: 'The Unnamed Fragment',
        backgroundGradient: 'linear-gradient(135deg, #000 0%, #111 100%)',
        isSafe: true,
        containsRestricted: false,
        genre: 'Minimalist',
        score: 55,
        justification: 'Default analysis applied.'
      };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  const checkAdmin = (user: any) => {
    return !!user?.email && ADMIN_EMAILS.includes(user.email);
  };

  const syncStateWithHash = async (isInitialLoad = false) => {
    if (isInitialLoad) {
      window.location.hash = '#/';
      setCurrentView('home');
      setSelectedPoemId(null);
      return;
    }

    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const protectedViews: View[] = ['profile', 'create'];

    if (hash.startsWith('#/p/')) {
      const id = hash.replace('#/p/', '');
      setSelectedPoemId(id);
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      if (protectedViews.includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      if (currentView !== 'detail') {
        setPreviousView(currentView);
      }
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems((admins || []).filter(p => !!p && !!p.id));
      setUserPoems((users || []).filter(p => !!p && !!p.id));
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash(false);
    window.addEventListener('hashchange', handleHashChange);

    syncStateWithHash(true);
    refreshData();

    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setIsAdmin(checkAdmin(session?.user));
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash(false);
      }
      if (event === 'SIGNED_OUT') {
        sessionStorage.removeItem('echo_onboarded');
        navigateTo('home');
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const isUserAdmin = checkAdmin(session?.user);
      const visibility = isUserAdmin ? 'read' : 'echoes';

      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        title: newPoem.title || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Echo',
        backgroundColor: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
      };

      let savedPoem: Poem | null = null;
      if (isUserAdmin) {
        savedPoem = await supabaseService.createAdminPoem(skeletonPoem);
      } else {
        savedPoem = await supabaseService.createEcho(skeletonPoem);
      }

      if (!savedPoem || !savedPoem.id) {
        throw new Error("Supabase rejected the fragment or returned an empty identity.");
      }

      // Capture final state for background task
      const finalSavedPoem = { ...savedPoem };
      const targetPoemId = String(finalSavedPoem.id);

      // Sync UI and Redirect immediately
      if (isUserAdmin) {
        setAdminPoems(prev => [finalSavedPoem, ...prev].filter(p => !!p && !!p.id));
        navigateTo('feed');
      } else {
        setUserPoems(prev => [finalSavedPoem, ...prev].filter(p => !!p && !!p.id));
        navigateTo('user-feed');
      }

      // Background Calibration
      (async () => {
        try {
          const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title || '');
          const updates: Partial<Poem> = {
            title: newPoem.title || meta.suggestedTitle,
            emotionTag: meta.emotionTag,
            emotionalWeight: meta.emotionalWeight,
            score: meta.score,
            genre: meta.genre,
            justification: meta.justification,
            backgroundColor: meta.backgroundGradient
          };

          const updated = await supabaseService.updatePoem(targetPoemId, visibility, updates);
          if (updated && updated.id) {
            if (visibility === 'read') {
              setAdminPoems(prev => prev.map(p => (p && p.id === updated.id) ? updated : p).filter(p => !!p && !!p.id));
            } else {
              setUserPoems(prev => prev.map(p => (p && p.id === updated.id) ? updated : p).filter(p => !!p && !!p.id));
            }
          }
        } catch (bgErr) {
          console.error("Background fragment calibration failed:", bgErr);
        }
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Failed to commit fragment. The frequency was interrupted.");
      throw err; 
    }
  };

  const allPoems = [...adminPoems, ...userPoems].filter(p => !!p && !!p.id);
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  const handleBackFromDetail = (poem: Poem) => {
    if (previousView === 'feed' || previousView === 'user-feed') {
      navigateTo(previousView);
    } else {
      const fallback = (poem && poem.visibility === 'read') ? 'feed' : 'user-feed';
      navigateTo(fallback);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text relative">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="animate-fade-in duration-500">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Read</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">Curated Curiosities</p>
              </header>
              <Feed 
                variant="grid" 
                poems={adminPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10">
              <header className="mb-12 text-center space-y-2">
                <h2 className="instrument-serif text-5xl italic opacity-90">Echoes</h2>
                <p className="text-[10px] uppercase tracking-[0.3em] opacity-30">The Community Stream</p>
              </header>
              <Feed 
                variant="grid" 
                poems={userPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => handleBackFromDetail(selectedPoem)} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
          {currentView === 'privacy' && <Privacy />}
        </div>
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-echo-bg/95 backdrop-blur-xl animate-fade-in p-6">
          <div className="max-w-md w-full text-center space-y-10">
            <h2 className="instrument-serif italic text-6xl">Echo Pages Guide</h2>
            <div className="space-y-6 serif-font text-xl opacity-70 italic">
              <p>Welcome to a sanctuary for the unspoken.</p>
              <p>Observe the curated 'Read' feed, contribute your own 'Echoes', and track your mastery in the 'Ranks'.</p>
              <p>Every fragment you commit is evaluated for genre precision and emotional depth.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-5 border border-echo-text/20 hover:border-echo-text transition-all text-[11px] uppercase tracking-[0.4em]"
            >
              Begin Observation
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { Poem } from '../types.ts';

interface PoemDetailProps {
  poem: Poem;
  onBack: () => void;
}

const PoemDetail: React.FC<PoemDetailProps> = ({ poem, onBack }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    setIsVisible(true);
    return () => setIsVisible(false);
  }, []);

  const handleCopyLink = () => {
    const url = `${window.location.origin}/#/p/${poem.id}`;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(() => {
        setCopyStatus('copied');
        setTimeout(() => setCopyStatus('idle'), 2000);
      }).catch(err => {
        console.error("Copy failed", err);
        fallbackCopy(url);
      });
    } else {
      fallbackCopy(url);
    }
  };

  const fallbackCopy = (text: string) => {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand('copy');
      setSuccessStatus();
    } catch (err) {
      alert("Please copy manually: " + text);
    }
    document.body.removeChild(textArea);
  };

  const setSuccessStatus = () => {
    setCopyStatus('copied');
    setTimeout(() => setCopyStatus('idle'), 2000);
  };

  const saveAsImage = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = 1080;
    const height = 1350; 
    canvas.width = width;
    canvas.height = height;

    const grad = ctx.createLinearGradient(0, 0, 0, height);
    grad.addColorStop(0, '#0a0a0a');
    grad.addColorStop(1, '#1a1a1a');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    // Dense Watermark (30px)
    ctx.save();
    ctx.rotate(-Math.PI / 12);
    ctx.font = '30px serif';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.textAlign = 'center';

    // Tighter tiling for the export image (85x25)
    const stepX = 85; 
    const stepY = 25; 
    for (let x = -width; x < width * 2; x += stepX) {
      for (let y = -height; y < height * 2; y += stepY) {
        ctx.fillText('ECHO PAGES', x, y);
      }
    }
    ctx.restore();

    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffffff';

    // Poem Title
    ctx.font = 'italic 76px serif';
    ctx.fillText((poem.title || 'UNTITLED').toUpperCase(), width / 2, 350);

    // Visual Divider
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(width / 3, 420);
    ctx.lineTo(2 * width / 3, 420);
    ctx.stroke();

    // Poem Content
    ctx.font = 'italic 44px serif';
    const lines = poem.content.split('\n');
    let startY = 550;
    const lineHeight = 65;
    lines.forEach(line => {
      ctx.fillText(line, width / 2, startY);
      startY += lineHeight;
    });

    // Metadata Footer
    ctx.font = '24px sans-serif';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    const footerY = height - 150;
    ctx.fillText(`BY @${poem.author.toUpperCase()}`, width / 2, footerY);
    ctx.font = 'bold 18px sans-serif';
    ctx.letterSpacing = '3px';
    ctx.fillText(`${poem.genre.toUpperCase()} · ${poem.score}% MATCH`, width / 2, footerY + 50);

    try {
      const link = document.createElement('a');
      link.download = `echo-${(poem.title || 'fragment').toLowerCase().replace(/\s+/g, '-')}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (e) {
      console.error("Canvas Export Failed", e);
    }
  };

  return (
    <div 
      className={`min-h-[90vh] relative transition-opacity duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'} overflow-hidden`}
      style={{ background: poem.backgroundColor || '#000' }}
    >
      {/* Tiled Watermark Background - Denser Tiling (85x25) with 30px font */}
      <div className="absolute inset-0 z-0 pointer-events-none opacity-[0.05] select-none" style={{
        backgroundImage: `url("data:image/svg+xml,%3Csvg width='85' height='25' viewBox='0 0 85 25' xmlns='http://www.w3.org/2000/svg'%3E%3Ctext x='50%25' y='50%25' text-anchor='middle' fill='white' font-family='serif' font-size='30' letter-spacing='-0.12em' transform='rotate(-12 42.5 12.5)'%3EECHO PAGES%3C/text%3E%3C/svg%3E")`,
        backgroundRepeat: 'repeat',
        backgroundSize: '85px 25px'
      }}>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      {/* Main Content Overlay */}
      <div className="max-w-3xl mx-auto px-6 py-20 bg-black/30 backdrop-blur-[2px] min-h-[90vh] flex flex-col justify-center relative z-10 text-white">
        <button 
          onClick={onBack}
          className="mb-12 self-start flex items-center space-x-3 opacity-40 hover:opacity-100 transition-all text-xs uppercase tracking-[0.2em]"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          <span>Return</span>
        </button>

        <article className="space-y-12">
          <header className="space-y-4">
            <div className="flex items-center space-x-4">
              <span className="text-[11px] uppercase tracking-[0.3em] text-white font-bold">
                {poem.genre} · {poem.score}% Match
              </span>
              <div className="h-[1px] flex-grow bg-white/10" />
            </div>
            <h1 className="instrument-serif text-5xl md:text-7xl leading-tight italic">
              {poem.title || 'Untitled Fragment'}
            </h1>
            {poem.justification && (
               <p className="text-[10px] uppercase tracking-[0.2em] opacity-40 border-l border-white/20 pl-4 py-1">
                 {poem.justification}
               </p>
            )}
          </header>

          <div className="serif-font text-xl md:text-2xl leading-relaxed whitespace-pre-line italic opacity-90 min-h-[12rem]">
            {poem.content}
          </div>

          <div className="pt-20 flex flex-col md:flex-row items-center justify-between border-t border-white/10 pt-10 gap-8">
            <div className="flex flex-col space-y-2">
              <span className="text-[10px] uppercase tracking-widest opacity-40">Emotion Spectrum</span>
              <div className="flex items-center space-x-3">
                <span className="instrument-serif text-3xl font-medium tracking-wide">{poem.emotionTag}</span>
                <span className="text-[10px] opacity-20 uppercase font-mono tracking-tighter">({poem.emotionalWeight}%)</span>
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={handleCopyLink}
                className="px-8 py-3 border border-white/20 hover:border-white transition-all text-[10px] uppercase tracking-widest text-white min-w-[140px]"
              >
                {copyStatus === 'copied' ? 'Link Copied' : 'Copy Link'}
              </button>
              <button 
                onClick={saveAsImage}
                className="px-8 py-3 border border-white/20 hover:border-white transition-all text-[10px] uppercase tracking-widest text-white/60 hover:text-white"
              >
                Save as Image
              </button>
            </div>
          </div>

          <div className="pt-10 flex justify-between items-center opacity-30 text-[9px] uppercase tracking-[0.3em]">
            <span>Echoed by @{poem.author}</span>
            <span>{new Date(poem.timestamp).toLocaleDateString('en-GB').replace(/\//g, '-')}</span>
          </div>
        </article>
      </div>
    </div>
  );
};

