          <div className="pt-10 flex justify-between items-center opacity-30 text-[9px] uppercase tracking-[0.3em]">
            <span>Echoed by @{poem.author}</span>
            <span>{new Date(poem.timestamp).toLocaleDateString('en-GB').replace(/\//g, '-')}</span>
          </div>
        </article>
      </div>
    </div>
  );
