    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = 1080;
    const height = 1350; 
    canvas.width = width;
    canvas.height = height;

    // Use poem's actual background
    const bg = poem.backgroundColor || 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)';

    if (bg.includes('gradient')) {
      const grad = ctx.createLinearGradient(0, 0, 0, height);
      grad.addColorStop(0, '#0a0a0a');
      grad.addColorStop(1, '#1a1a1a');
      ctx.fillStyle = grad;
    } else {
      ctx.fillStyle = bg;
    }
    ctx.fillRect(0, 0, width, height);

    // Denser Export Watermark (Matching refined UI tiling)
    ctx.save();
    ctx.rotate(-Math.PI / 12);
    ctx.font = '30px serif';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.04)';
    ctx.textAlign = 'center';

    // Increased tile width/height for breathable but dense pattern (250x100)
    const stepX = 250; 
    const stepY = 100; 
    for (let x = -width; x < width * 2; x += stepX) {
