import React, { useState, useEffect } from 'react';
import { supabase, authService } from '../services/supabaseService.ts';

const Auth: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [displayName, setDisplayName] = useState('');
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [mailSent, setMailSent] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) window.location.hash = '#/profile';
    });
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (loading) return;

    if (!email.includes('@')) {
      setError('A valid frequency (email) is required.');
      return;
    }
    if (password.length < 6) {
      setError('Sequence must be at least 6 characters.');
      return;
    }
    if (!isLogin && !displayName.trim()) {
      setError('An identity name is required for registration.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      if (isLogin) {
        await authService.login(email, password);
        setSuccess(true);
        setTimeout(() => {
          window.location.hash = '#/profile';
        }, 800);
      } else {
        await authService.signup(email, password, displayName);
        // Supabase might require confirmation, but we inform the user to check mail
        setMailSent(true);
        setLoading(false);
      }
    } catch (err: any) {
      const errorMessage = typeof err === 'string' ? err : (err?.message || 'Identity verification failed.');
      setError(errorMessage);
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setError('');
    setLoading(true);
    try {
      await authService.loginWithGoogle();
    } catch (err: any) {
      setError(err?.message || 'Google authentication failed.');
      setLoading(false);
    }
  };

  if (mailSent) {
    return (
      <div className="max-w-md mx-auto py-24 px-6 space-y-12 animate-fade-in text-center min-h-[80vh] flex flex-col justify-center items-center">
        <div className="w-20 h-20 border border-echo-text/20 rounded-full flex items-center justify-center mb-8">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 opacity-40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
          </svg>
        </div>
        <h2 className="instrument-serif italic text-5xl">Transmission Sent</h2>
        <p className="serif-font text-lg italic opacity-40">
          Check your inbox to confirm your frequency. Once verified, you may return to claim your space.
        </p>
        <button 
          onClick={() => { setMailSent(false); setIsLogin(true); }}
          className="px-10 py-4 border border-echo-text/20 hover:border-white transition-all text-[10px] uppercase tracking-[0.4em] font-bold"
        >
          Return to Login
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto py-24 px-6 space-y-12 animate-fade-in text-center min-h-[80vh] flex flex-col justify-center">
      <div className="space-y-4">
        <h1 className="instrument-serif italic text-6xl">
          {success && isLogin ? 'Recognized' : (isLogin ? 'Welcome back' : 'New Identity')}
        </h1>
        <p className="serif-font text-lg italic opacity-40">
          {isLogin ? 'Reconnect with the collective silence.' : 'Claim your space within the void.'}
        </p>
      </div>

      <div className={`space-y-8 transition-all duration-700 ${success && isLogin ? 'opacity-0 scale-95' : 'opacity-100'}`}>
        <form onSubmit={handleSubmit} className="space-y-6 text-left">
          {!isLogin && (
            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest opacity-30 ml-1">Display Name</label>
              <input 
                type="text" 
                placeholder="Observer"
                className="w-full bg-neutral-900 border border-echo-border px-5 py-4 focus:outline-none focus:border-white transition-all text-echo-text"
                value={displayName}
                onChange={e => setDisplayName(e.target.value)}
                required={!isLogin}
              />
            </div>
          )}

          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest opacity-30 ml-1">Email</label>
            <input 
              type="email" 
              placeholder="you@echo.com"
              className="w-full bg-neutral-900 border border-echo-border px-5 py-4 focus:outline-none focus:border-white transition-all text-echo-text"
              value={email}
              onChange={e => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest opacity-30 ml-1">Password</label>
            <div className="relative group">
              <input 
                type={showPassword ? "text" : "password"} 
                placeholder="••••••••"
                className="w-full bg-neutral-900 border border-echo-border px-5 py-4 pr-12 focus:outline-none focus:border-white transition-all text-echo-text"
                value={password}
                onChange={e => setPassword(e.target.value)}
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-4 top-1/2 -translate-y-1/2 opacity-20 hover:opacity-100 transition-opacity p-1"
                title={showPassword ? "Hide Sequence" : "Reveal Sequence"}
              >
                {showPassword ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" />
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                  </svg>
                )}
              </button>
            </div>
          </div>

          {error && (
            <div className="p-4 bg-red-950/20 border border-red-900 text-red-200 text-[10px] animate-fade-in font-medium uppercase tracking-widest">
              {error}
            </div>
          )}

          <button 
            type="submit" 
            disabled={loading}
            className="w-full py-5 bg-echo-text text-echo-bg uppercase tracking-[0.4em] text-[11px] font-bold hover:bg-white transition-all disabled:opacity-20 flex items-center justify-center space-x-3"
          >
            {loading ? (
              <>
                <div className="w-3 h-3 border-2 border-echo-bg/30 border-t-echo-bg rounded-full animate-spin" />
                <span>Transmitting...</span>
              </>
            ) : (
              <span>{isLogin ? 'Confirm Login' : 'Initialize Identity'}</span>
            )}
          </button>
        </form>

        <div className="flex items-center space-x-4 text-[9px] uppercase tracking-widest opacity-20">
          <div className="h-[1px] flex-grow bg-echo-border"></div>
          <span>Frequency Selection</span>
          <div className="h-[1px] flex-grow bg-echo-border"></div>
        </div>

        <button 
          onClick={handleGoogleLogin}
          disabled={loading}
          className="w-full py-4 border border-echo-border hover:border-echo-text transition-all flex items-center justify-center space-x-3 text-[10px] uppercase tracking-widest"
        >
          <svg className="w-4 h-4" viewBox="0 0 24 24"><path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/><path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/><path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 12-4.53z"/></svg>
          <span>Continue with Google</span>
        </button>

        <button 
          onClick={() => { setIsLogin(!isLogin); setError(''); setShowPassword(false); }}
          className="text-[10px] uppercase tracking-widest opacity-40 hover:opacity-100 transition-opacity border-b border-transparent hover:border-white/20 pb-1"
        >
          {isLogin ? "Need a new identity?" : "Already recognized?"}
        </button>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  const checkAdmin = (user: any) => {
    return !!user?.email && ADMIN_EMAILS.includes(user.email);
  };

  const syncStateWithHash = async (isInitialLoad = false) => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const protectedViews: View[] = ['profile', 'create'];

    if (hash.startsWith('#/p/')) {
      const id = hash.replace('#/p/', '');
      setSelectedPoemId(id);
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      if (protectedViews.includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      if (currentView !== 'detail') {
        setPreviousView(currentView);
      }
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems((admins || []).filter(p => !!p && !!p.id));
      setUserPoems((users || []).filter(p => !!p && !!p.id));
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash(false);
    window.addEventListener('hashchange', handleHashChange);

    // On mount, sync hash but allow specific deep links
    syncStateWithHash(false);
    refreshData();

    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setIsAdmin(checkAdmin(session?.user));
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash(false);
      }
      if (event === 'SIGNED_OUT') {
        sessionStorage.removeItem('echo_onboarded');
        navigateTo('home');
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const isUserAdmin = checkAdmin(session?.user);
      const visibility = isUserAdmin ? 'read' : 'echoes';

      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        title: newPoem.title || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Analyzing...',
        backgroundColor: '#121212'
      };

      let savedPoem: Poem | null = null;
      if (isUserAdmin) {
        savedPoem = await supabaseService.createAdminPoem(skeletonPoem);
      } else {
        savedPoem = await supabaseService.createEcho(skeletonPoem);
      }

      if (!savedPoem || !savedPoem.id) {
        throw new Error("Supabase rejected the fragment or returned an empty identity.");
      }

      const finalSavedPoem = { ...savedPoem };
      const targetPoemId = String(finalSavedPoem.id);

      // Instant UI update
      if (isUserAdmin) {
        setAdminPoems(prev => [finalSavedPoem, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [finalSavedPoem, ...prev]);
        navigateTo('user-feed');
      }

      // Spectral Calibration Task
      (async () => {
        try {
          const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title || '');
          const updates: Partial<Poem> = {
            title: newPoem.title || meta.suggestedTitle,
            emotionTag: meta.emotionTag,
            emotionalWeight: meta.emotionalWeight,
            score: meta.score,
            genre: meta.genre,
            justification: meta.justification,
            backgroundColor: meta.backgroundGradient
          };

          const updated = await supabaseService.updatePoem(targetPoemId, visibility, updates);
          if (updated && updated.id) {
            if (visibility === 'read') {
              setAdminPoems(prev => prev.map(p => (p.id === updated.id) ? updated : p));
            } else {
              setUserPoems(prev => prev.map(p => (p.id === updated.id) ? updated : p));
            }
          }
        } catch (bgErr) {
          console.error("Calibration failed:", bgErr);
        }
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Transmission interrupted. Try again.");
      throw err; 
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  const handleBackFromDetail = (poem: Poem) => {
    if (previousView === 'feed' || previousView === 'user-feed') {
      navigateTo(previousView);
    } else {
      const fallback = (poem && poem.visibility === 'read') ? 'feed' : 'user-feed';
      navigateTo(fallback);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text relative overflow-x-hidden">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="transition-all duration-700">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10 animate-fade-in">
              <header className="mb-16 text-center space-y-4">
                <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-90 tracking-tighter">Read</h2>
                <div className="flex items-center justify-center gap-4">
                  <div className="h-[1px] w-8 bg-white/20" />
                  <p className="text-[10px] uppercase tracking-[0.5em] opacity-30">The Curated Fragments</p>
                  <div className="h-[1px] w-8 bg-white/20" />
                </div>
              </header>
              <Feed 
                variant="grid" 
                poems={adminPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10 animate-fade-in">
              <header className="mb-16 text-center space-y-4">
                <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-90 tracking-tighter">Echoes</h2>
                <div className="flex items-center justify-center gap-4">
                  <div className="h-[1px] w-8 bg-white/20" />
                  <p className="text-[10px] uppercase tracking-[0.5em] opacity-30">Community Resonance</p>
                  <div className="h-[1px] w-8 bg-white/20" />
                </div>
              </header>
              <Feed 
                variant="grid" 
                poems={userPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => handleBackFromDetail(selectedPoem)} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
          {currentView === 'privacy' && <Privacy />}
        </div>
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-echo-bg/95 backdrop-blur-2xl animate-fade-in p-6">
          <div className="max-w-xl w-full text-center space-y-12">
            <h2 className="instrument-serif italic text-7xl md:text-8xl tracking-tight">Echosystem</h2>
            <div className="space-y-8 serif-font text-xl md:text-2xl opacity-60 italic leading-relaxed">
              <p>Welcome to a sanctuary for the unspoken.</p>
              <p>Observe the curated 'Read' feed, contribute your own 'Echoes', and track resonance in 'Ranks'.</p>
              <p>Every fragment committed is evaluated for genre precision and emotional depth by our intelligence.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-6 border-2 border-white/20 hover:border-white transition-all text-[12px] uppercase tracking-[0.5em] font-black"
            >
              Enter the Frequency
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

