              <div className="text-right space-y-1">
                <div className="text-4xl instrument-serif text-white">{entry.score}%</div>
                <p className="text-[9px] uppercase tracking-widest opacity-60 text-white font-medium">Avg. Mastery</p>
              </div>
            </div>
          ))}

          {entries.length === 0 && (
            <div className="text-center py-20 border border-white/5 opacity-40 italic instrument-serif text-2xl">
