        backgroundRepeat: 'repeat',
        backgroundSize: '250px 100px'
      }}>
      </div>

      <canvas ref={canvasRef} className="hidden" />

      <div className="max-w-4xl mx-auto px-6 py-12 md:py-20 bg-black/60 backdrop-blur-[6px] flex-grow flex flex-col justify-center relative z-10 text-white w-full border-x border-white/10 shadow-2xl">
        <button 
