import { PoemMetadata } from "../types.ts";

const CACHE_KEY = 'echo_daily_line_v1';
const CACHE_TS = 'echo_daily_ts_v1';

const FALLBACK_SEEDS = [
  "The stars are just holes in the ceiling of a house we forgot we built.",
  "Silence is a conversation we aren't brave enough to have yet.",
  "We are all just ghosts wearing skin, looking for a place to haunt.",
  "Memory is a mirror that only shows the things we've lost.",
  "The wind doesn't blow; it's just the world trying to catch its breath.",
  "Ink is the blood of a heart that learned to speak.",
  "We are the architects of our own hauntings.",
  "Shadows are just light that lost its way home."
];

const GENRE_POOL = "Noir, Ethereal, Minimalist, Free Verse, Prose, Haiku, Lyric, Narrative, Epic, Dramatic, Elegy, Ode, Sonnet, Ballad, Pastoral, Mock-Epic, Love, Romance, Heartbreak, Grief, Mourning, Joy, Celebration, Loneliness, Hope, Despair, Angst, Nostalgia, Regret, Desire, Devotion, Spiritual, Religious, Mystical, Philosophical, Existential, Metaphysical, Didactic, Political, Protest, Revolutionary, Feminist, Social Justice, Nature, Ecological, Scientific, Space, Cosmic, Technological, AI Poetry, Cyber Poetry, Experimental, Surreal, Absurdist, Stream of Consciousness, Fragmentary, Gothic, Dark Poetry, Horror, Macabre, Psychological, Trauma Poetry, Death Poetry, Madness Poetry, Humorous, Comic, Satire, Confessional, Personal, Autobiographical, Identity Poetry, Gender Poetry, Cultural Poetry, Diaspora Poetry, Coming-of-Age, Depression Poetry, Anxiety Poetry, Healing Poetry, Recovery Poetry, Folk Poetry, Tribal Poetry, Classical Poetry, Sanskrit Poetry, Tamil Poetry, Urdu Poetry, Persian Poetry, Ghazal, Tanka, Villanelle, Pantoum, Sestina, Spoken Word, Slam Poetry, Performance Poetry, Rap Poetry, Hip-Hop Poetry, Meta-Poetry, Ars Poetica, Conceptual Poetry, Ekphrastic Poetry, Found Poetry, Erasure Poetry, Micro-Poetry, Flash Poetry, Narrative Verse, Verse Novel, Allegorical Poetry, Mythological Poetry, Folklore Poetry, Fable Poetry, War Poetry, Soldier Poetry, Patriotism Poetry, Exile Poetry, Migration Poetry, Refugee Poetry, Urban Poetry, Street Poetry, Rural Poetry, Dystopian Poetry, Utopian Poetry, Apocalyptic Poetry, Sci-Fi Poetry, Fantasy Poetry, Speculative Poetry, Time Poetry, Memory Poetry, Dream Poetry, Lucid Poetry, Sleep Poetry, Night Poetry, Light Poetry, Silence Poetry, Sound Poetry, Digital Poetry, Hypertext Poetry, Code Poetry, Glitch Poetry, Internet Poetry, Meme Poetry";

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      // Re-initialize per guidelines to ensure fresh API key context
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      const randomSeed = FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
      return cached || randomSeed;
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `Perform a high-fidelity literary analysis on this fragment.

        TASK:
        1. genre: Select the SINGLE most dominant genre from the GENRE POOL.
        2. score: Calculate a "Genre Match Score" (55-95) as an integer.
        3. justification: A 1-sentence mini-explanation of why this genre fits.
        4. emotionTag: A 1-2 word mood descriptor.
        5. emotionalWeight: Intensity of mood (0-100).
        6. suggestedTitle: MANDATORY if current title is blank, generic, or "Whispering...". Generate a 2-5 word haunting title.
        7. backgroundGradient: A CSS linear-gradient(135deg, color1, color2) matching the mood.

        GENRE POOL: [${GENRE_POOL}]

        CURRENT TITLE: "${title || ''}"
        FRAGMENT CONTENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN },
              genre: { type: Type.STRING },
              score: { type: Type.NUMBER },
              justification: { type: Type.STRING }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "isSafe", "containsRestricted", "genre", "score", "justification"]
          }
        }
      });

      const jsonStr = response.text || '{}';
      const result = JSON.parse(jsonStr);

      let finalScore = typeof result.score === 'number' ? Math.round(result.score) : 55;
      finalScore = Math.min(95, Math.max(55, finalScore));

      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'A Whisper in the Dark',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #1a1a1a 0%, #2d3436 100%)',
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false,
        genre: result.genre || 'Minimalist',
        score: finalScore,
        justification: result.justification || 'Analyzed through atmospheric resonance.'
      };
    } catch (error) {
      console.error("Spectral Analysis Error:", error);
      return {
        emotionTag: 'Echo',
        emotionalWeight: 50,
        suggestedTitle: 'The Unnamed Fragment',
        backgroundGradient: 'linear-gradient(135deg, #000 0%, #111 100%)',
        isSafe: true,
        containsRestricted: false,
        genre: 'Minimalist',
        score: 55,
        justification: 'Default classification due to processing interference.'
      };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  const checkAdmin = (user: any) => {
    return !!user?.email && ADMIN_EMAILS.includes(user.email);
  };

  const syncStateWithHash = async (isInitialLoad = false) => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const protectedViews: View[] = ['profile', 'create'];

    if (hash.startsWith('#/p/')) {
      const id = hash.replace('#/p/', '');
      setSelectedPoemId(id);
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      if (protectedViews.includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      if (currentView !== 'detail') {
        setPreviousView(currentView);
      }
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems((admins || []).filter(p => !!p && !!p.id));
      setUserPoems((users || []).filter(p => !!p && !!p.id));
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash(false);
    window.addEventListener('hashchange', handleHashChange);

    syncStateWithHash(false);
    refreshData();

    geminiService.getDailyLine().then(line => {
      setDailyLine(line);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setIsAdmin(checkAdmin(session?.user));
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash(false);
      }
      if (event === 'SIGNED_OUT') {
        sessionStorage.removeItem('echo_onboarded');
        navigateTo('home');
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const isUserAdmin = checkAdmin(session?.user);
      const visibility = isUserAdmin ? 'read' : 'echoes';

      const originalTitle = newPoem.title?.trim();
      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        title: originalTitle || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Analyzing...',
        backgroundColor: '#121212'
      };

      let savedPoem: Poem | null = null;
      if (isUserAdmin) {
        savedPoem = await supabaseService.createAdminPoem(skeletonPoem);
      } else {
        savedPoem = await supabaseService.createEcho(skeletonPoem);
      }

      if (!savedPoem || !savedPoem.id) {
        throw new Error("Supabase rejected the fragment.");
      }

      const finalSavedPoem = { ...savedPoem };
      const targetPoemId = String(finalSavedPoem.id);

      // Instant local UI update
      if (isUserAdmin) {
        setAdminPoems(prev => [finalSavedPoem, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [finalSavedPoem, ...prev]);
        navigateTo('user-feed');
      }

      // Background Calibration Task
      (async () => {
        try {
          const meta = await geminiService.analyzePoem(newPoem.content || '', originalTitle);
          const updates: Partial<Poem> = {
            title: originalTitle || meta.suggestedTitle,
            emotionTag: meta.emotionTag,
            emotionalWeight: meta.emotionalWeight,
            score: meta.score,
            genre: meta.genre,
            justification: meta.justification,
            backgroundColor: meta.backgroundGradient
          };

          const updated = await supabaseService.updatePoem(targetPoemId, visibility, updates);
          if (updated && updated.id) {
            if (visibility === 'read') {
              setAdminPoems(prev => prev.map(p => (p.id === updated.id) ? updated : p));
            } else {
              setUserPoems(prev => prev.map(p => (p.id === updated.id) ? updated : p));
            }
          }
        } catch (bgErr) {
          console.error("Calibration failed:", bgErr);
        }
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Transmission interrupted.");
      throw err; 
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  const handleBackFromDetail = (poem: Poem) => {
    if (previousView === 'feed' || previousView === 'user-feed') {
      navigateTo(previousView);
    } else {
      const fallback = (poem && poem.visibility === 'read') ? 'feed' : 'user-feed';
      navigateTo(fallback);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text relative overflow-x-hidden">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        <div className="transition-all duration-700">
          {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
          {currentView === 'feed' && (
            <div className="pt-10 animate-fade-in">
              <header className="mb-16 text-center space-y-4">
                <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-90 tracking-tighter">Read</h2>
                <div className="flex items-center justify-center gap-4">
                  <div className="h-[1px] w-8 bg-white/20" />
                  <p className="text-[10px] uppercase tracking-[0.5em] opacity-30">The Curated Fragments</p>
                  <div className="h-[1px] w-8 bg-white/20" />
                </div>
              </header>
              <Feed 
                variant="grid" 
                poems={adminPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'user-feed' && (
            <div className="pt-10 animate-fade-in">
              <header className="mb-16 text-center space-y-4">
                <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-90 tracking-tighter">Echoes</h2>
                <div className="flex items-center justify-center gap-4">
                  <div className="h-[1px] w-8 bg-white/20" />
                  <p className="text-[10px] uppercase tracking-[0.5em] opacity-30">Community Resonance</p>
                  <div className="h-[1px] w-8 bg-white/20" />
                </div>
              </header>
              <Feed 
                variant="grid" 
                poems={userPoems} 
                onSelectPoem={(id) => navigateTo('detail', id)} 
              />
            </div>
          )}
          {currentView === 'detail' && selectedPoem && (
            <PoemDetail poem={selectedPoem} onBack={() => handleBackFromDetail(selectedPoem)} />
          )}
          {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
          {currentView === 'leaderboard' && <Leaderboard />}
          {currentView === 'profile' && <Profile />}
          {currentView === 'auth' && <Auth />}
          {currentView === 'about' && <About />}
          {currentView === 'contact' && <Contact />}
          {currentView === 'privacy' && <Privacy />}
        </div>
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-echo-bg/95 backdrop-blur-2xl animate-fade-in p-6">
          <div className="max-w-xl w-full text-center space-y-12">
            <h2 className="instrument-serif italic text-7xl md:text-8xl tracking-tight">Echosystem</h2>
            <div className="space-y-8 serif-font text-xl md:text-2xl opacity-60 italic leading-relaxed">
              <p>Welcome to a sanctuary for the unspoken.</p>
              <p>Observe the curated 'Read' feed, contribute your own 'Echoes', and track resonance in 'Ranks'.</p>
              <p>Every fragment committed is evaluated for genre precision and emotional depth by our intelligence.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-6 border-2 border-white/20 hover:border-white transition-all text-[12px] uppercase tracking-[0.5em] font-black"
            >
              Enter the Frequency
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

