const GENRE_POOL = "Noir, Ethereal, Minimalist, Free Verse, Prose, Haiku, Lyric, Narrative, Elegy, Ode, Sonnet, Ballad, Spiritual, Mystical, Philosophical, Existential, Fragmentary, Gothic, Dark Poetry, Macabre, Psychological, Confessional, Personal, Meta-Poetry, Ars Poetica, Surreal, Absurdist";

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `Perform a literary analysis on this poem fragment.

        TASK:
        1. genre: Pick one from: [${GENRE_POOL}].
        2. score: Genre match percentage (60-98).
        3. justification: Why this genre fits (1 sentence).
        4. emotionTag: 1-word descriptor (e.g. Void, Ache, Pulse).
        5. emotionalWeight: 0-100 intensity.
        6. suggestedTitle: Generate a haunting 2-4 word title. MANDATORY if current title is empty or generic.
        7. backgroundGradient: Generate a unique, moody CSS linear-gradient(135deg, color1, color2) using deep, dark, atmospheric colors (hex values) that reflect the poem's soul.

        CURRENT TITLE: "${title || ''}"
        CONTENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.NUMBER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              genre: { type: Type.STRING },
              score: { type: Type.NUMBER },
              justification: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN }
            },
            required: ["emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "genre", "score", "justification"]
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      return {
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || 'A Fragment in Time',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(135deg, #0f0c29 0%, #302b63 100%)',
        genre: result.genre || 'Minimalist',
        score: result.score || 70,
        justification: result.justification || 'Analyzed via atmospheric resonance.',
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false
      };
    } catch (error) {
      console.error("Analysis Error:", error);
      return {
        emotionTag: 'Echo',
        emotionalWeight: 50,
        suggestedTitle: 'The Unnamed Fragment',
        backgroundGradient: 'linear-gradient(135deg, #1a1a1a 0%, #000 100%)',
        genre: 'Minimalist',
        score: 60,
        justification: 'Default calibration applied.',
        isSafe: true,
        containsRestricted: false
      };
    }
  }
};

