import React, { useEffect, useState } from 'react';
import { View } from '../types.ts';
import { supabase, authService } from '../services/supabaseService.ts';

interface HeaderProps {
  currentView: View;
  onNavigate: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ currentView, onNavigate }) => {
  const [user, setUser] = useState<any>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => setUser(session?.user ?? null));
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_e, session) => setUser(session?.user ?? null));
    return () => subscription.unsubscribe();
  }, []);

  const navItems = [
    { id: 'feed', label: 'Read' },
    { id: 'user-feed', label: 'Echoes' },
    { id: 'leaderboard', label: 'Ranks' },
  ];
  if (user) navItems.push({ id: 'create', label: 'Create' });

  const handleLogout = async () => {
    try {
      await authService.logout();
      onNavigate('home');
    } catch (err) {
      console.error("Logout failed:", err);
    }
  };

  return (
    <header className="sticky top-0 z-50 backdrop-blur-md bg-black/80 px-6 py-6 border-b border-echo-border flex flex-col md:flex-row justify-between items-center gap-6">
      <div className="cursor-pointer" onClick={() => onNavigate('home')}>
        <span className="instrument-serif text-3xl font-medium tracking-tighter text-white">Echo Pages</span>
      </div>

      <nav className="flex items-center space-x-6 text-[10px] uppercase tracking-widest font-black">
        {navItems.map((item) => (
          <button 
            key={item.id}
            onClick={() => onNavigate(item.id as View)}
            className={`transition-all border-b py-1 ${currentView === item.id ? 'opacity-100 border-white' : 'opacity-60 border-transparent hover:opacity-100 hover:border-white/50'}`}
          >
            {item.label}
          </button>
        ))}
        {user ? (
          <div className="flex items-center space-x-6">
            <button onClick={() => onNavigate('profile')} className={`opacity-90 hover:opacity-100 text-white font-black border-b py-1 ${currentView === 'profile' ? 'border-white' : 'border-transparent'}`}>
              {user.user_metadata?.display_name || 'Profile'}
