import React, { useState, useMemo } from 'react';
import { Poem } from '../types.ts';
import { GENRES, TONES, ADMIN_EMAILS } from '../constants.ts';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  currentUser?: any;
  onDelete?: (id: string) => void;
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, currentUser, onDelete }) => {
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedTone, setSelectedTone] = useState('');

  const filteredPoems = useMemo(() => {
    return poems.filter(p => {
      const matchesSearch = search === '' || 
        p.title.toLowerCase().includes(search.toLowerCase()) || 
        p.content.toLowerCase().includes(search.toLowerCase());
      const matchesGenre = selectedGenre === '' || p.genre === selectedGenre;
      // Tone mapping if necessary, or just match if stored directly
      const matchesTone = selectedTone === '' || p.tone === selectedTone;
      return matchesSearch && matchesGenre && matchesTone;
    });
  }, [poems, search, selectedGenre, selectedTone]);

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${String(date.getDate()).padStart(2, '0')}-${String(date.getMonth() + 1).padStart(2, '0')}-${date.getFullYear()}`;
  };

  const getDeterministicGradient = (id: string) => {
    if (!id) return 'linear-gradient(135deg, #1a1a1a 0%, #000 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) hash = id.charCodeAt(i) + ((hash << 5) - hash);
    const h1 = Math.abs(hash % 360);
    const h2 = (h1 + 60) % 360;
    return `linear-gradient(135deg, hsl(${h1}, 45%, 12%) 0%, hsl(${h2}, 40%, 7%) 100%)`;
  };

  const isAdmin = currentUser?.email && ADMIN_EMAILS.includes(currentUser.email);

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-12">
      {/* Search & Filters UI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/5 p-6 border border-white/10 rounded-sm backdrop-blur-md">
        <div className="relative col-span-1 md:col-span-1">
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black">Search Fragment</label>
          <input 
            type="text" 
            placeholder="Keywords..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none focus:border-white/40 transition-all text-white placeholder:opacity-20"
          />
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black">Genre Filter</label>
          <select 
            value={selectedGenre} 
            onChange={(e) => setSelectedGenre(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Genres</option>
            {GENRES.map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black">Tone Filter</label>
          <select 
            value={selectedTone} 
            onChange={(e) => setSelectedTone(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Tones</option>
            {TONES.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
          </select>
        </div>
      </div>

      {/* Poems Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
        {filteredPoems.map((poem, index) => {
          const backgroundStyle = poem.backgroundColor || getDeterministicGradient(poem.id);
          const canDelete = isAdmin || (currentUser && currentUser.id === poem.userId);

          return (
            <article 
              key={poem.id}
              className="group border border-echo-border p-8 md:p-10 flex flex-col justify-between hover:border-white/30 transition-all duration-700 animate-fade-in relative overflow-hidden rounded-sm shadow-2xl"
              style={{ 
                animationDelay: `${index * 50}ms`, 
                animationFillMode: 'both',
                background: backgroundStyle
              }}
            >
              <div onClick={() => onSelectPoem(poem.id)} className="cursor-pointer flex-grow space-y-8 relative z-10">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] uppercase tracking-[0.3em] font-black text-white bg-white/20 px-3 py-1 rounded-full border border-white/10 backdrop-blur-md">
                    {`${poem.genre || 'Echo'} · ${poem.score || 0}% Match`}
                  </span>
                </div>

                <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-[1.1] text-white/90 group-hover:text-white group-hover:italic transition-all duration-500">
                  {poem.title || 'Untitled'}
                </h2>
              </div>

              <div className="mt-12 space-y-6 relative z-10">
                <div className="h-[1px] w-full bg-white/10 group-hover:bg-white/30 transition-colors duration-500" />

                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-bold text-white/70 group-hover:text-white/95 transition-colors">
                  <span className="italic">@{poem.author}</span>
                  <div className="flex items-center space-x-4">
                    <span className="font-mono">{formatDate(poem.timestamp)}</span>
                    {canDelete && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDelete?.(poem.id); }}
                        className="text-red-400 hover:text-red-200 transition-colors opacity-0 group-hover:opacity-100 p-1"
                        title="Delete Echo"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                      </button>
                    )}
                  </div>
                </div>
              </div>

              <div className="absolute inset-0 bg-white/[0.03] opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
              <div className="absolute inset-0 bg-gradient-to-br from-white/[0.05] to-transparent opacity-30 pointer-events-none" />
            </article>
          );
        })}
      </div>

      {filteredPoems.length === 0 && (
        <div className="text-center py-40 opacity-80 instrument-serif italic text-2xl text-white">
          The search returned only silence.
        </div>
      )}
    </div>
  );
};

export default Feed;

import React, { useEffect, useState } from 'react';
import { Poem } from '../types.ts';
import { ADMIN_EMAILS } from '../constants.ts';

interface PoemDetailProps {
  poem: Poem;
  onBack: () => void;
  currentUser?: any;
  onDelete?: () => void;
}

const PoemDetail: React.FC<PoemDetailProps> = ({ poem, onBack, currentUser, onDelete }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');

  useEffect(() => {
    setIsVisible(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    return () => setIsVisible(false);
  }, []);

  const getDeterministicGradient = (id: string) => {
    if (!id) return 'linear-gradient(135deg, #1a1a1a 0%, #000 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) hash = id.charCodeAt(i) + ((hash << 5) - hash);
    const h1 = Math.abs(hash % 360);
    const h2 = (h1 + 60) % 360;
    return `linear-gradient(135deg, hsl(${h1}, 45%, 12%) 0%, hsl(${h2}, 40%, 7%) 100%)`;
  };

  const handleCopyLink = () => {
    const url = `${window.location.origin}/#/p/${poem.id}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopyStatus('copied');
      setTimeout(() => setCopyStatus('idle'), 2000);
    });
  };

  const backgroundStyle = poem.backgroundColor || getDeterministicGradient(poem.id);
  const isAdmin = currentUser?.email && ADMIN_EMAILS.includes(currentUser.email);
  const canDelete = isAdmin || (currentUser && currentUser.id === poem.userId);

  return (
    <div 
      className={`min-h-[90vh] relative transition-all duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'} flex flex-col`}
      style={{ background: backgroundStyle }}
    >
      <div className="absolute inset-0 z-0 pointer-events-none opacity-[0.03] select-none" style={{
        backgroundImage: `url("data:image/svg+xml,%3Csvg width='250' height='100' viewBox='0 0 250 100' xmlns='http://www.w3.org/2000/svg'%3E%3Ctext x='50%25' y='50%25' text-anchor='middle' fill='white' font-family='serif' font-size='30' letter-spacing='0.2em' transform='rotate(-12 125 50)'%3EECHO PAGES%3C/text%3E%3C/svg%3E")`,
        backgroundRepeat: 'repeat',
        backgroundSize: '250px 100px'
      }}></div>

      <div className="max-w-4xl mx-auto px-6 py-12 md:py-20 bg-black/40 backdrop-blur-[12px] flex-grow flex flex-col justify-center relative z-10 text-white w-full border-x border-white/5 shadow-2xl">
        <div className="flex justify-between items-center mb-10">
          <button 
            onClick={onBack}
            className="flex items-center space-x-3 opacity-80 hover:opacity-100 transition-all text-[10px] uppercase tracking-[0.3em] font-bold"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
            <span>Return</span>
          </button>

          {canDelete && (
            <button 
              onClick={onDelete}
              className="text-red-400 hover:text-red-300 text-[10px] uppercase tracking-[0.3em] font-bold border border-red-900/40 px-4 py-1.5 bg-red-950/20 hover:bg-red-900/40 transition-all rounded-sm"
            >
              Erase Echo
            </button>
          )}
        </div>

        <article className="space-y-8">
          <header className="space-y-4">
            <div className="flex flex-wrap items-center gap-4">
              <span className="text-[10px] uppercase tracking-[0.3em] text-white font-black bg-white/20 px-3 py-1 rounded-sm border border-white/10">
                {`${poem.genre || 'Echo'} · ${poem.score || 0}% Match`}
              </span>
              <div className="h-[1px] flex-grow bg-white/10" />
            </div>

            <h1 className="instrument-serif text-4xl md:text-6xl leading-[1.1] italic tracking-tight text-white/95">
              {poem.title || 'Untitled Fragment'}
            </h1>

            {poem.justification && (
               <p className="text-[10px] uppercase tracking-[0.15em] opacity-80 border-l-2 border-white/40 pl-6 py-1 max-w-xl leading-relaxed italic">
                 {poem.justification}
               </p>
            )}
          </header>

          <div className="serif-font text-lg md:text-2xl leading-[1.8] whitespace-pre-line italic text-white/90 min-h-[14rem] tracking-wide">
            {poem.content}
          </div>

          <div className="pt-12 grid grid-cols-1 md:grid-cols-2 items-end border-t border-white/10 gap-10">
            <div className="flex flex-col space-y-4">
              <span className="text-[9px] uppercase tracking-[0.4em] opacity-80 font-bold">Emotion Spectrum</span>
              <div className="flex items-center gap-6">
                <span className="instrument-serif text-3xl md:text-4xl font-medium tracking-wide leading-none">{poem.emotionTag}</span>
                <div className="flex flex-col">
                  <span className="text-[9px] opacity-60 uppercase font-mono tracking-tighter">Intensity</span>
                  <span className="text-lg font-mono text-white font-bold">{poem.emotionalWeight}%</span>
                </div>
              </div>
            </div>

            <div className="flex flex-wrap gap-4 md:justify-end">
              <button 
                onClick={handleCopyLink}
                className="px-8 py-3 border border-white/30 hover:border-white hover:bg-white/5 transition-all text-[10px] uppercase tracking-[0.4em] text-white font-bold"
              >
                {copyStatus === 'copied' ? 'Link Captured' : 'Copy Link'}
              </button>
            </div>
          </div>

          <div className="pt-8 flex justify-between items-center opacity-80 text-[10px] uppercase tracking-[0.4em] font-semibold">
            <div className="flex flex-col">
              <span className="text-[8px] opacity-60 mb-1 font-bold">Origin</span>
              <span>@{poem.author}</span>
            </div>
            <div className="flex flex-col text-right">
              <span className="text-[8px] opacity-60 mb-1 font-bold">Frequency Date</span>
              <span>{new Date(poem.timestamp).toLocaleDateString('en-GB').replace(/\//g, ' . ')}</span>
            </div>
          </div>
        </article>
      </div>
    </div>
  );
};

