    const confirmed = window.confirm("Are you certain? Erasing an echo is permanent and irreversible.");
    if (!confirmed) return;

    const success = await supabaseService.deletePoem(id, visibility);
    if (success) {
      if (visibility === 'read') {
        setAdminPoems(prev => prev.filter(p => p.id !== id));
      } else {
        setUserPoems(prev => prev.filter(p => p.id !== id));
      }
