    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    setCurrentUser(session?.user ?? null);

    if (hash.startsWith('#/p/')) {
      setSelectedPoemId(hash.replace('#/p/', ''));
      setCurrentView('detail');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/admin': 'admin',
        '#/': 'home'
      };

      const targetView = views[hash] || 'home';

      // Protected views
      if (['profile', 'create', 'admin'].includes(targetView) && !session) {
        window.location.hash = '#/auth';
        return;
      }

      // Admin only
      if (targetView === 'admin' && session && !ADMIN_EMAILS.includes(session.user.email || '')) {
        window.location.hash = '#/';
        return;
      }

      if (currentView !== 'detail') setPreviousView(currentView);
      setCurrentView(targetView);
      setSelectedPoemId(null);
    }
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash();
    window.addEventListener('hashchange', handleHashChange);
    syncStateWithHash();
    refreshData();

    geminiService.getDailyLine().then(line => setDailyLine(line));

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setCurrentUser(session?.user ?? null);
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash();
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      // Admin check: either forced by AdminPortal (admin userId) or detected by email
      const isAdminUser = newPoem.userId === 'admin' || (!!session?.user?.email && ADMIN_EMAILS.includes(session.user.email));
      const visibility = isAdminUser ? 'read' : 'echoes';
      const originalTitle = newPoem.title?.trim();

      const tempId = Math.random().toString(36).substring(7);
      const initialBg = getDeterministicGradient(tempId);

      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        title: originalTitle || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Analyzing',
        backgroundColor: initialBg
      };

      let saved: Poem | null = isAdminUser 
        ? await supabaseService.createAdminPoem(skeletonPoem)
        : await supabaseService.createEcho(skeletonPoem);

      if (!saved || !saved.id) throw new Error("Sync failed.");

      saved.backgroundColor = getDeterministicGradient(saved.id);

      if (isAdminUser) {
        setAdminPoems(prev => [saved!, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [saved!, ...prev]);
        navigateTo('user-feed');
      }

      // Trigger AI Analysis for Title, Genre, and Score
      (async () => {
        const meta = await geminiService.analyzePoem(newPoem.content || '', originalTitle);
        const updates = {
          title: originalTitle || meta.suggestedTitle,
          emotion_tag: meta.emotionTag,
          emotional_weight: meta.emotionalWeight,
          score: meta.score,
          genre: meta.genre,
          justification: meta.justification,
          background_color: meta.backgroundGradient || getDeterministicGradient(saved!.id)
        };

        const updated = await supabaseService.updatePoem(saved!.id, visibility, updates);
        if (updated) {
          if (visibility === 'read') {
            setAdminPoems(prev => prev.map(p => p.id === updated.id ? updated : p));
          } else {
            setUserPoems(prev => prev.map(p => p.id === updated.id ? updated : p));
          }
        }
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Transmission interrupted.");
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text selection:bg-white/10">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
        {(currentView === 'feed' || currentView === 'user-feed') && (
          <div className="pt-10 animate-fade-in">
            <header className="mb-12 text-center space-y-4">
              <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-95 tracking-tighter">
                {currentView === 'feed' ? 'Read' : 'Echoes'}
              </h2>
              <p className="text-[10px] uppercase tracking-[0.5em] opacity-80 font-bold">
                {currentView === 'feed' ? 'Curated Introspection' : 'Community Resonance'}
              </p>
            </header>
            <Feed 
              poems={currentView === 'feed' ? adminPoems : userPoems} 
              onSelectPoem={(id) => navigateTo('detail', id)} 
              currentUser={currentUser}
            />
          </div>
        )}
        {currentView === 'detail' && selectedPoem && (
          <PoemDetail 
            poem={selectedPoem} 
            onBack={() => navigateTo(previousView)} 
            currentUser={currentUser}
          />
        )}
        {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'admin' && <AdminPortal onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'leaderboard' && <Leaderboard />}
        {currentView === 'profile' && <Profile />}
        {currentView === 'auth' && <Auth />}
        {currentView === 'about' && <About />}
        {currentView === 'contact' && <Contact />}
        {currentView === 'privacy' && <Privacy />}
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-2xl animate-fade-in p-6 text-white">
          <div className="max-w-xl w-full text-center space-y-12">
            <h2 className="instrument-serif italic text-7xl md:text-8xl">Echosystem</h2>
            <div className="space-y-8 serif-font text-xl md:text-2xl opacity-80 italic leading-relaxed">
              <p>You have entered a sanctuary for fragments.</p>
              <p>Every contribution is analyzed for its unique emotional frequency.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-6 border-2 border-white/40 hover:border-white transition-all text-[12px] uppercase tracking-[0.5em] font-black"
            >
              Enter the Frequency
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { View } from '../types.ts';
import { supabase, authService } from '../services/supabaseService.ts';
import { ADMIN_EMAILS } from '../constants.ts';

interface HeaderProps {
  currentView: View;
  onNavigate: (view: View) => void;
}

const Header: React.FC<HeaderProps> = ({ currentView, onNavigate }) => {
  const [user, setUser] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      setUser(u);
      setIsAdmin(!!u?.email && ADMIN_EMAILS.includes(u.email));
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_e, session) => {
      const u = session?.user ?? null;
      setUser(u);
      setIsAdmin(!!u?.email && ADMIN_EMAILS.includes(u.email));
    });

    return () => subscription.unsubscribe();
  }, []);

  const navItems = [
    { id: 'feed', label: 'Read' },
    { id: 'user-feed', label: 'Echoes' },
    { id: 'leaderboard', label: 'Ranks' },
  ];
  if (user) navItems.push({ id: 'create', label: 'Create' });
  if (isAdmin) navItems.push({ id: 'admin', label: 'Admin' });

  const handleLogout = async () => {
    try {
      await authService.logout();
      onNavigate('home');
    } catch (err) {
      console.error("Logout failed:", err);
    }
  };

  return (
    <header className="sticky top-0 z-50 backdrop-blur-md bg-black/90 px-6 py-6 border-b border-echo-border flex flex-col md:flex-row justify-between items-center gap-6">
      <div className="cursor-pointer" onClick={() => onNavigate('home')}>
        <span className="instrument-serif text-3xl font-medium tracking-tighter text-white">Echo Pages</span>
      </div>

      <nav className="flex items-center space-x-8 text-[10px] uppercase tracking-widest font-black">
        {navItems.map((item) => (
          <button 
            key={item.id}
            onClick={() => onNavigate(item.id as View)}
            className={`transition-all border-b py-1 ${currentView === item.id ? 'opacity-100 border-white' : 'opacity-40 border-transparent hover:opacity-100 hover:border-white/50'}`}
          >
            {item.label}
          </button>
        ))}
        {user ? (
          <div className="flex items-center space-x-6 border-l border-white/20 pl-6">
            <button 
              onClick={() => onNavigate('profile')} 
              className={`opacity-90 hover:opacity-100 text-white font-black border-b py-1 transition-all ${currentView === 'profile' ? 'border-white' : 'border-transparent'}`}
            >
              {user.user_metadata?.display_name || 'Profile'}
            </button>
            <button 
              onClick={handleLogout} 
              className="px-5 py-2 border-2 border-white bg-white text-black hover:bg-transparent hover:text-white font-bold transition-all rounded-sm tracking-[0.2em] shadow-[0_0_15px_rgba(255,255,255,0.2)]"
            >
              SIGN OUT
            </button>
          </div>
        ) : (
          <button 
            onClick={() => onNavigate('auth')} 
            className="px-6 py-2 border border-white/40 hover:border-white text-white font-black transition-all hover:bg-white/5 rounded-sm"
          >
            LOGIN
          </button>
        )}
      </nav>
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { Poem } from '../types.ts';

interface AdminPortalProps {
  onPublish: (poem: Partial<Poem>) => Promise<void>;
  onCancel: () => void;
}

const AdminPortal: React.FC<AdminPortalProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPublishing, setIsPublishing] = useState(false);

  const handlePublish = async () => {
    if (!content.trim() || isPublishing) return;

    setIsPublishing(true);

    const finalPoem: Partial<Poem> = {
      title: title.trim(),
      content: content.trim(),
      author: 'Admin',
      userId: 'admin', // Specifically tag as admin for App.tsx logic
      timestamp: Date.now()
    };

    try {
      await onPublish(finalPoem);
    } catch (err) {
      console.error("Admin upload failed:", err);
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in">
      <div className="space-y-12">
        <div className="flex justify-between items-baseline border-b border-echo-border pb-8">
          <div>
            <h2 className="instrument-serif text-4xl italic text-white">Curate the Read Feed</h2>
            <p className="text-[10px] uppercase tracking-widest opacity-30 mt-2">Publish directly to the curated collection.</p>
          </div>
          <button 
            onClick={onCancel}
            className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 transition-opacity"
          >
            Discard
          </button>
        </div>

        <div className="space-y-10">
          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30 font-bold text-white/60">Title (Optional)</p>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="AI will generate if left blank..."
              className="w-full bg-transparent border-b border-echo-border py-4 focus:border-echo-text focus:outline-none instrument-serif text-4xl transition-colors text-white"
            />
          </div>

          <div className="space-y-3">
            <p className="text-[10px] uppercase tracking-widest opacity-30 font-bold text-white/60">Content</p>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="The Curated Verse..."
              className="w-full h-96 bg-transparent border border-echo-border p-8 focus:border-echo-text focus:outline-none transition-all serif-font text-2xl italic leading-relaxed whitespace-pre-line text-white/90"
            />
          </div>

          <div className="pt-12">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim()}
              className="w-full py-6 bg-echo-text text-echo-bg text-[11px] uppercase tracking-[0.4em] font-bold hover:bg-white transition-all disabled:opacity-20 flex items-center justify-center space-x-4"
