    const l1 = 8 + (Math.abs(hash % 8)); // 8-16% lightness for deep atmosphere

    return `linear-gradient(135deg, hsl(${h1}, ${s1}%, ${l1}%) 0%, hsl(${h2}, ${s1}%, ${l1 - 4}%) 100%)`;
