    if (!id) return 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
      hash = id.charCodeAt(i) + ((hash << 5) - hash);
    }

    // Spread the hue across the full 360 spectrum
    const h = Math.abs(hash % 360);
    // Use medium saturation for visible color without being neon
    const s = 35 + (Math.abs(hash % 35)); 
    // Keep lightness low for "moody" but high enough to distinguish hue
    const l = 12 + (Math.abs(hash % 10)); 

