import React, { useState, useMemo } from 'react';
import { Poem } from '../types.ts';
import { GENRES, TONES, ADMIN_EMAILS } from '../constants.ts';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  currentUser?: any;
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, currentUser }) => {
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedTone, setSelectedTone] = useState('');

  const filteredPoems = useMemo(() => {
    return poems.filter(p => {
      const matchesSearch = search === '' || 
        p.title.toLowerCase().includes(search.toLowerCase()) || 
        p.content.toLowerCase().includes(search.toLowerCase());
      const matchesGenre = selectedGenre === '' || p.genre === selectedGenre;
      const matchesTone = selectedTone === '' || p.tone === selectedTone;
      return matchesSearch && matchesGenre && matchesTone;
    });
  }, [poems, search, selectedGenre, selectedTone]);

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${String(date.getDate()).padStart(2, '0')}-${String(date.getMonth() + 1).padStart(2, '0')}-${date.getFullYear()}`;
  };

  const getDeterministicGradient = (id: string) => {
    if (!id) return 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
      hash = id.charCodeAt(i) + ((hash << 5) - hash);
    }
    const h = Math.abs(hash % 360);
    const s = 30 + (Math.abs(hash % 40)); 
    const l = 8 + (Math.abs(hash % 12)); 
    const h2 = (h + 40 + (Math.abs(hash % 100))) % 360;
    const l2 = Math.max(4, l - 4);
    return `linear-gradient(180deg, hsl(${h}, ${s}%, ${l}%) 0%, hsl(${h2}, ${s}%, ${l2}%) 100%)`;
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-12">
      {/* Search & Filters UI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/5 p-6 border border-white/10 rounded-sm backdrop-blur-md">
        <div className="relative col-span-1 md:col-span-1">
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Search Fragment</label>
          <input 
            type="text" 
            placeholder="Keywords..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none focus:border-white/40 transition-all text-white placeholder:opacity-20"
          />
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Genre Filter</label>
          <select 
            value={selectedGenre} 
            onChange={(e) => setSelectedGenre(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Genres</option>
            {GENRES.map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Tone Filter</label>
          <select 
            value={selectedTone} 
            onChange={(e) => setSelectedTone(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Tones</option>
            {TONES.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
          </select>
        </div>
      </div>

      {/* Poems Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
        {filteredPoems.map((poem, index) => {
          const isAnalyzing = poem.score === 0 || poem.genre === 'Analyzing';
          const backgroundStyle = poem.backgroundColor || getDeterministicGradient(poem.id);

          return (
            <article 
              key={poem.id}
              onClick={() => onSelectPoem(poem.id)}
              className="group cursor-pointer border border-echo-border p-8 md:p-10 flex flex-col justify-between hover:border-white/30 transition-all duration-700 animate-fade-in relative overflow-hidden rounded-sm shadow-2xl"
              style={{ 
                animationDelay: `${index * 50}ms`, 
                animationFillMode: 'both',
                background: backgroundStyle
              }}
            >
              <div className="flex-grow space-y-8 relative z-10">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] uppercase tracking-[0.3em] font-black text-white bg-white/20 px-3 py-1 rounded-full border border-white/10 backdrop-blur-md">
                    {isAnalyzing ? (
                      <span className="flex items-center space-x-2">
                         <div className="w-1.5 h-1.5 bg-white/60 rounded-full" />
                         <span className="opacity-70">Spectral Analysis</span>
                      </span>
                    ) : (
                      `${poem.genre || 'Echo'} · ${poem.score || 0}% Match`
                    )}
                  </span>
                </div>

                <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-[1.1] text-white/90 group-hover:text-white group-hover:italic transition-all duration-500">
                  {poem.title || 'Untitled'}
                </h2>
              </div>

              <div className="mt-12 space-y-6 relative z-10">
                <div className="h-[1px] w-full bg-white/10 group-hover:bg-white/30 transition-colors duration-500" />

                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-bold text-white/70 group-hover:text-white/95 transition-colors">
                  <span className="italic">@{poem.author}</span>
                  <span className="font-mono">{formatDate(poem.timestamp)}</span>
                </div>
              </div>

              <div className="absolute inset-0 bg-white/[0.03] opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
              <div className="absolute inset-0 bg-gradient-to-br from-white/[0.05] to-transparent opacity-30 pointer-events-none" />
            </article>
          );
        })}
      </div>

      {filteredPoems.length === 0 && (
        <div className="text-center py-40 opacity-80 instrument-serif italic text-2xl text-white">
          The search returned only silence.
        </div>
      )}
    </div>
  );
};

