import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types.ts";

const CACHE_KEY = 'echo_daily_line_v1';
const CACHE_TS = 'echo_daily_ts_v1';

const FALLBACK_SEEDS = [
  "The stars are just holes in the ceiling of a house we forgot we built.",
  "Silence is a conversation we aren't brave enough to have yet.",
  "We are all just ghosts wearing skin, looking for a place to haunt.",
  "Memory is a mirror that only shows the things we've lost.",
  "The wind doesn't blow; it's just the world trying to catch its breath.",
  "Ink is the blood of a heart that learned to speak.",
  "We are the architects of our own hauntings.",
  "Shadows are just light that lost its way home."
];

const GENRE_POOL = [
  "Noir", "Ethereal", "Minimalist", "Free Verse", "Prose", "Haiku", "Lyric", 
  "Narrative", "Elegy", "Ode", "Sonnet", "Ballad", "Spiritual", "Mystical", 
  "Philosophical", "Existential", "Fragmentary", "Gothic", "Dark Poetry", 
  "Macabre", "Psychological", "Confessional", "Personal", "Meta-Poetry", 
  "Ars Poetica", "Surreal", "Absurdist"
];

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `Act as a master literary critic and high-end visual designer. Analyze the provided poem fragment.

        CRITERIA:
        1. genre: Categorize into exactly ONE of: [${GENRE_POOL.join(', ')}].
        2. score: Resonance Score (55-95).
        3. justification: Sharp, one-sentence literary justification.
        4. emotionTag: Single atmospheric noun/adjective.
        5. emotionalWeight: 0-100.
        6. suggestedTitle: Evocative 2-4 word title.
        7. backgroundGradient: CSS linear-gradient(180deg, hex1, hex2). 
           MANDATORY: Provide high-quality HEX codes. 
           AVOID defaulting to green/muddy tones.
           EXPLORE: Deep Royal Purples (#1e1b4b), Dark Crimson (#450a0a), Obsidian Blues (#020617), Amber Shadows (#451a03), or Charcoal Violets (#2e1065).
           Each background must look distinct and premium.

        FRAGMENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              genre: { type: Type.STRING },
              score: { type: Type.INTEGER },
              justification: { type: Type.STRING },
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.INTEGER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING }
            },
            required: ["genre", "score", "justification", "emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const text = response.text || '{}';
      const result = JSON.parse(text);

      const validatedGenre = GENRE_POOL.includes(result.genre) ? result.genre : 'Minimalist';
      const validatedScore = Math.min(95, Math.max(55, typeof result.score === 'number' ? result.score : 75));

      return {
        genre: validatedGenre,
        score: validatedScore,
        justification: result.justification || 'Analyzed via spectral resonance.',
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: typeof result.emotionalWeight === 'number' ? result.emotionalWeight : 50,
        suggestedTitle: result.suggestedTitle || 'The Unspoken Verse',
        backgroundGradient: result.backgroundGradient || 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)',
        isSafe: true,
        containsRestricted: false
      };
    } catch (error) {
      console.error("Spectral Analysis Error:", error);
      return {
        genre: 'Minimalist',
        score: 65,
        justification: 'The verse density was too high for a clean read; falling back to minimalist interpretation.',
        emotionTag: 'Echo',
        emotionalWeight: 50,
        suggestedTitle: title || 'A Fragment in Silence',
        backgroundGradient: 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)',
        isSafe: true,
        containsRestricted: false
      };
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';
import AdminPortal from './components/AdminPortal.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);

  const currentViewRef = useRef<View>('home');
  useEffect(() => {
    currentViewRef.current = currentView;
  }, [currentView]);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const [showOnboarding, setShowOnboarding] = useState(false);

  // High-entropy deterministic gradient generator
  const getDeterministicGradient = (id: string) => {
    if (!id) return 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
      hash = ((hash << 5) - hash) + id.charCodeAt(i);
      hash |= 0; // Convert to 32bit integer
    }

    const h = Math.abs(hash % 360);
    const s = 35 + (Math.abs(hash % 40)); 
    const l = 7 + (Math.abs(hash % 10)); 

    const h2 = (h + 60 + (Math.abs(hash % 120))) % 360;
    const l2 = Math.max(3, l - 4);

    return `linear-gradient(180deg, hsl(${h}, ${s}%, ${l}%) 0%, hsl(${h2}, ${s}%, ${l2}%) 100%)`;
  };

  const syncStateWithHash = async () => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    setCurrentUser(session?.user ?? null);

    let targetView: View = 'home';
    let targetPoemId: string | null = null;

    if (hash.startsWith('#/p/')) {
      targetView = 'detail';
      targetPoemId = hash.replace('#/p/', '');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed',
        '#/echoes': 'user-feed',
        '#/create': 'create',
        '#/about': 'about',
        '#/contact': 'contact',
        '#/privacy': 'privacy',
        '#/profile': 'profile',
        '#/ranks': 'leaderboard',
        '#/auth': 'auth',
        '#/admin': 'admin',
        '#/': 'home'
      };
      targetView = views[hash] || 'home';
    }

    if (['profile', 'create', 'admin'].includes(targetView) && !session) {
      window.location.hash = '#/auth';
      return;
    }
    if (targetView === 'admin' && session && !ADMIN_EMAILS.includes(session.user.email || '')) {
      window.location.hash = '#/';
      return;
    }

    const lastView = currentViewRef.current;
    if (lastView !== 'detail' && lastView !== targetView) {
      setPreviousView(lastView);
    }

    setSelectedPoemId(targetPoemId);
    setCurrentView(targetView);
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) {
      console.error("Data Refresh Failed:", err);
    }
  };

  useEffect(() => {
    const handleHashChange = () => syncStateWithHash();
    window.addEventListener('hashchange', handleHashChange);
    syncStateWithHash();
    refreshData();

    // Subscribe to real-time updates to fix the "refresh required" bug
    const adminChannel = supabase.channel('admin_poems_realtime')
      .on('postgres_changes', { event: '*', table: 'admin_poems', schema: 'public' }, (payload) => {
        refreshData();
      })
      .subscribe();

    const echoChannel = supabase.channel('echoes_realtime')
      .on('postgres_changes', { event: '*', table: 'echoes', schema: 'public' }, (payload) => {
        refreshData();
      })
      .subscribe();

    geminiService.getDailyLine().then(line => setDailyLine(line));

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setCurrentUser(session?.user ?? null);
      if (event === 'SIGNED_IN') {
        if (!sessionStorage.getItem('echo_onboarded')) {
          setShowOnboarding(true);
          sessionStorage.setItem('echo_onboarded', 'true');
        }
        syncStateWithHash();
      }
    });

    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      subscription.unsubscribe();
      supabase.removeChannel(adminChannel);
      supabase.removeChannel(echoChannel);
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/',
      'feed': '#/read',
      'user-feed': '#/echoes',
      'create': '#/create',
      'about': '#/about',
      'contact': '#/contact',
      'privacy': '#/privacy',
      'admin': '#/admin',
      'profile': '#/profile',
      'leaderboard': '#/ranks',
      'auth': '#/auth',
      'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();

      const ADMIN_UUID = 'f6909f52-7a1f-455d-a9c3-bbf61ef346e7';
      const effectiveUserId = (newPoem.userId === ADMIN_UUID || newPoem.userId === 'admin') ? 'admin' : newPoem.userId;

      const isAdminUser = effectiveUserId === 'admin' || (!!session?.user?.email && ADMIN_EMAILS.includes(session.user.email));
      const visibility = isAdminUser ? 'read' : 'echoes';
      const originalTitle = newPoem.title?.trim();

      // Use "Whispering..." as a placeholder while AI generates a real title
      const tempId = Math.random().toString(36).substring(7);
      const initialBg = getDeterministicGradient(tempId);

      const skeletonPoem: Partial<Poem> = {
        ...newPoem,
        userId: effectiveUserId,
        title: originalTitle || 'Whispering...', 
        visibility: visibility,
        emotionTag: 'Echo',
        score: 0,
        genre: 'Analyzing',
        backgroundColor: initialBg
      };

      let saved: Poem | null = isAdminUser 
        ? await supabaseService.createAdminPoem(skeletonPoem)
        : await supabaseService.createEcho(skeletonPoem);

      if (!saved || !saved.id) throw new Error("Sync failed.");

      saved.backgroundColor = getDeterministicGradient(saved.id);

      // Local state update for immediate feedback
      if (isAdminUser) {
        setAdminPoems(prev => [saved!, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [saved!, ...prev]);
        navigateTo('user-feed');
      }

      // Asynchronous AI Analysis
      (async () => {
        const meta = await geminiService.analyzePoem(newPoem.content || '', originalTitle);

        // Final updates: If user didn't provide a title, use the AI-generated one
        const updates = {
          title: originalTitle || meta.suggestedTitle,
          emotion_tag: meta.emotionTag,
          emotional_weight: meta.emotionalWeight,
          score: meta.score,
          genre: meta.genre,
          justification: meta.justification,
          background_color: meta.backgroundGradient || getDeterministicGradient(saved!.id)
        };

        // DB update triggers the Real-time subscription in useEffect
        await supabaseService.updatePoem(saved!.id, visibility, updates);
      })();

    } catch (err) {
      console.error("Publication Error:", err);
      alert("Transmission interrupted.");
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text selection:bg-white/10">
      <Header currentView={currentView} onNavigate={navigateTo} />

      <main className="flex-grow">
        {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
        {(currentView === 'feed' || currentView === 'user-feed') && (
          <div className="pt-10 animate-fade-in">
            <header className="mb-12 text-center space-y-4">
              <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-95 tracking-tighter">
                {currentView === 'feed' ? 'Read' : 'Echoes'}
              </h2>
              <p className="text-[10px] uppercase tracking-[0.5em] opacity-80 font-bold">
                {currentView === 'feed' ? 'Curated Introspection' : 'Community Resonance'}
              </p>
            </header>
            <Feed 
              poems={currentView === 'feed' ? adminPoems : userPoems} 
              onSelectPoem={(id) => navigateTo('detail', id)} 
              currentUser={currentUser}
            />
          </div>
        )}
        {currentView === 'detail' && selectedPoem && (
          <PoemDetail 
            poem={selectedPoem} 
            onBack={() => navigateTo(previousView)} 
            currentUser={currentUser}
          />
        )}
        {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'admin' && <AdminPortal onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'leaderboard' && <Leaderboard />}
        {currentView === 'profile' && <Profile />}
        {currentView === 'auth' && <Auth />}
        {currentView === 'about' && <About />}
        {currentView === 'contact' && <Contact />}
        {currentView === 'privacy' && <Privacy />}
      </main>

      {showOnboarding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-2xl animate-fade-in p-6 text-white">
          <div className="max-w-xl w-full text-center space-y-12">
            <h2 className="instrument-serif italic text-7xl md:text-8xl">Echosystem</h2>
            <div className="space-y-8 serif-font text-xl md:text-2xl opacity-80 italic leading-relaxed">
              <p>You have entered a sanctuary for fragments.</p>
              <p>Every contribution is analyzed for its unique emotional frequency.</p>
            </div>
            <button 
              onClick={() => setShowOnboarding(false)}
              className="w-full py-6 border-2 border-white/40 hover:border-white transition-all text-[12px] uppercase tracking-[0.5em] font-black"
            >
              Enter the Frequency
            </button>
          </div>
        </div>
      )}

      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Poem } from '../types.ts';
import { GENRES, TONES, ADMIN_EMAILS } from '../constants.ts';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  currentUser?: any;
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, currentUser }) => {
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedTone, setSelectedTone] = useState('');

  const filteredPoems = useMemo(() => {
    return poems.filter(p => {
      const matchesSearch = search === '' || 
        p.title.toLowerCase().includes(search.toLowerCase()) || 
        p.content.toLowerCase().includes(search.toLowerCase());
      const matchesGenre = selectedGenre === '' || p.genre === selectedGenre;
      const matchesTone = selectedTone === '' || p.tone === selectedTone;
      return matchesSearch && matchesGenre && matchesTone;
    });
  }, [poems, search, selectedGenre, selectedTone]);

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${String(date.getDate()).padStart(2, '0')}-${String(date.getMonth() + 1).padStart(2, '0')}-${date.getFullYear()}`;
  };

  const getDeterministicGradient = (id: string) => {
    if (!id) return 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)';
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
      hash = ((hash << 5) - hash) + id.charCodeAt(i);
      hash |= 0;
    }
    const h = Math.abs(hash % 360);
    const s = 35 + (Math.abs(hash % 40)); 
    const l = 7 + (Math.abs(hash % 10)); 
    const h2 = (h + 60 + (Math.abs(hash % 120))) % 360;
    const l2 = Math.max(3, l - 4);
    return `linear-gradient(180deg, hsl(${h}, ${s}%, ${l}%) 0%, hsl(${h2}, ${s}%, ${l2}%) 100%)`;
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-12">
      {/* Search & Filters UI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/5 p-6 border border-white/10 rounded-sm backdrop-blur-md">
        <div className="relative col-span-1 md:col-span-1">
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Search Fragment</label>
          <input 
            type="text" 
            placeholder="Keywords..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none focus:border-white/40 transition-all text-white placeholder:opacity-20"
          />
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Genre Filter</label>
          <select 
            value={selectedGenre} 
            onChange={(e) => setSelectedGenre(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Genres</option>
            {GENRES.map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Tone Filter</label>
          <select 
            value={selectedTone} 
            onChange={(e) => setSelectedTone(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Tones</option>
            {TONES.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
          </select>
        </div>
      </div>

      {/* Poems Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
        {filteredPoems.map((poem, index) => {
          const isAnalyzing = poem.score === 0 || poem.genre === 'Analyzing';
          const backgroundStyle = poem.backgroundColor || getDeterministicGradient(poem.id);

          return (
            <article 
              key={poem.id}
              onClick={() => onSelectPoem(poem.id)}
              className="group cursor-pointer border border-echo-border p-8 md:p-10 flex flex-col justify-between hover:border-white/30 transition-all duration-700 animate-fade-in relative overflow-hidden rounded-sm shadow-2xl"
              style={{ 
                animationDelay: `${index * 50}ms`, 
                animationFillMode: 'both',
                background: backgroundStyle
              }}
            >
              <div className="flex-grow space-y-8 relative z-10">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] uppercase tracking-[0.3em] font-black text-white bg-white/20 px-3 py-1 rounded-full border border-white/10 backdrop-blur-md">
                    {isAnalyzing ? (
                      <span className="flex items-center space-x-2">
                         <div className="w-1.5 h-1.5 bg-white/60 rounded-full" />
                         <span className="opacity-70">Spectral Analysis</span>
                      </span>
                    ) : (
                      `${poem.genre || 'Echo'} · ${poem.score || 0}% Match`
                    )}
                  </span>
                </div>

                <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-[1.1] text-white/90 group-hover:text-white group-hover:italic transition-all duration-500">
                  {poem.title || 'Untitled'}
                </h2>
              </div>

              <div className="mt-12 space-y-6 relative z-10">
                <div className="h-[1px] w-full bg-white/10 group-hover:bg-white/30 transition-colors duration-500" />

                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-bold text-white/70 group-hover:text-white/95 transition-colors">
                  <span className="italic">@{poem.author}</span>
                  <span className="font-mono">{formatDate(poem.timestamp)}</span>
                </div>
              </div>

              <div className="absolute inset-0 bg-white/[0.03] opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
              <div className="absolute inset-0 bg-gradient-to-br from-white/[0.05] to-transparent opacity-30 pointer-events-none" />
            </article>
          );
        })}
      </div>

      {filteredPoems.length === 0 && (
        <div className="text-center py-40 opacity-80 instrument-serif italic text-2xl text-white">
          The search returned only silence.
        </div>
      )}
    </div>
  );
};

