];

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, title?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `Act as a master literary critic and prestigious visual curator.
        Perform a comparative analysis of the poem fragment provided below.

        1. genre: Determine the MOST dominant genre from: [${GENRE_POOL.join(', ')}].
        2. score: Calculate a "Resonance Score" (integer between 55 and 95) based on genre match.
        3. justification: Write one evocative sentence explaining the genre fit.
        4. emotionTag: Single atmospheric noun/adjective core frequency.
        5. emotionalWeight: Intensity (0-100).
        6. suggestedTitle: Create a meaningful, poetic 2-4 word title that captures the piece's soul.
        7. backgroundGradient: CSS linear-gradient(180deg, hex1, hex2). 
           REQUIRED: Sophisticated, moody colors. AVOID repetitive green/muddy tones.
           EXPLORE: Midnight Indigo (#0f172a / #1e1b4b), Deep Plum (#1a0b2e / #2e1065), Slate Abyss (#020617 / #1f2937), Burnt Sienna Shadow (#2d0a0a / #451a03).

        POEM: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              genre: { type: Type.STRING },
              score: { type: Type.INTEGER },
              justification: { type: Type.STRING },
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.INTEGER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING }
            },
            required: ["genre", "score", "justification", "emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const text = response.text || '{}';
      let result = JSON.parse(text);

      const validatedGenre = GENRE_POOL.includes(result.genre) ? result.genre : 'Minimalist';
      const validatedScore = Math.min(95, Math.max(55, result.score || 75));

      return {
        genre: validatedGenre,
        score: validatedScore,
        justification: result.justification || 'The fragment resonates with spectral clarity.',
        emotionTag: result.emotionTag || 'Echo',
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || (title && title !== 'Whispering...' ? title : 'The Unspoken Verse'),
        backgroundGradient: result.backgroundGradient || 'linear-gradient(180deg, #020617 0%, #0f172a 100%)',
        isSafe: true,
        containsRestricted: false
      };
    } catch (error) {
      console.error("Spectral Analysis Error:", error);
      return {
        genre: 'Minimalist',
        score: 65,
        justification: 'The verse was analyzed with minimalist constraints.',
        emotionTag: 'Echo',
        emotionalWeight: 50,
        suggestedTitle: title && title !== 'Whispering...' ? title : 'A Fragment in Silence',
        backgroundGradient: 'linear-gradient(180deg, #020617 0%, #0f172a 100%)',
        isSafe: true,
        containsRestricted: false
      };
    }
  }
};

