export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.error("Daily Line Fetch Error:", error);
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, providedTitle?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const isTitleMissing = !providedTitle || providedTitle.trim() === '' || providedTitle === 'Whispering...';

      const prompt = `Act as a senior literary critic and visual curator. Analyze the following poetry fragment.

        CRITICAL REQUIREMENTS:
        1. GENRE: Pick exactly one from: [${GENRE_POOL.join(', ')}]. Do not invent new ones.
        2. RESONANCE SCORE: An integer 55-95 representing how perfectly it fits the genre.
        3. EMOTION TAG: A single powerful atmospheric word (e.g., 'Static', 'Void', 'Bloom').
        4. EMOTIONAL WEIGHT: Intensity 0-100.
        5. SUGGESTED TITLE: If the provided title is "None", create a 2-4 word haunting title. If a title is already provided, keep it.
        6. BACKGROUND GRADIENT: A CSS linear-gradient(180deg, hex1, hex2) using sophisticated, dark, moody colors (e.g., deep purples, slates, midnight blues).
        7. JUSTIFICATION: One short sentence on why the genre fits.

        PROVIDED TITLE: "${isTitleMissing ? 'None' : providedTitle}"
        FRAGMENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              genre: { type: Type.STRING, description: "The dominant genre from the list." },
              score: { type: Type.INTEGER, description: "Resonance score 55-95." },
              justification: { type: Type.STRING, description: "Short explanation." },
              emotionTag: { type: Type.STRING, description: "One word emotion." },
              emotionalWeight: { type: Type.INTEGER, description: "Intensity 0-100." },
              suggestedTitle: { type: Type.STRING, description: "New or existing title." },
              backgroundGradient: { type: Type.STRING, description: "CSS linear-gradient." },
              isSafe: { type: Type.BOOLEAN, default: true },
              containsRestricted: { type: Type.BOOLEAN, default: false }
            },
            required: ["genre", "score", "justification", "emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient"]
          }
        }
      });

      const result = JSON.parse(response.text || "{}");

      // Ensure the genre is actually in our pool, otherwise default to Minimalist
      const finalGenre = GENRE_POOL.includes(result.genre) ? result.genre : "Minimalist";
      const finalScore = Math.max(55, Math.min(95, result.score || 75));

      return {
        genre: finalGenre,
        score: finalScore,
        justification: result.justification || "The fragment resonates with spectral clarity.",
        emotionTag: result.emotionTag || "Echo",
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || (isTitleMissing ? "The Unspoken Verse" : providedTitle!),
        backgroundGradient: result.backgroundGradient || "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false
      };
    } catch (error) {
      console.error("Spectral Analysis Error:", error);
      return {
        genre: "Minimalist",
        score: 65,
        justification: "The verse was analyzed with minimalist constraints due to a connectivity shift.",
        emotionTag: "Residual",
        emotionalWeight: 40,
        suggestedTitle: (providedTitle && providedTitle !== 'Whispering...') ? providedTitle : "A Fragment in Time",
        backgroundGradient: "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: true,
        containsRestricted: false
      };
    }
  }
};

