import React, { useState, useEffect } from 'react';
import { Poem } from '../types.ts';
import { supabase } from '../services/supabaseService.ts';
import { ADMIN_EMAILS } from '../constants.ts';
import { geminiService } from '../services/geminiService.ts';

interface CreatePoemProps {
  onPublish: (poem: Partial<Poem>) => Promise<void>;
  onCancel: () => void;
}

const CreatePoem: React.FC<CreatePoemProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPublishing, setIsPublishing] = useState(false);
  const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
  const [safetyError, setSafetyError] = useState<string | null>(null);
  const [regenCount, setRegenCount] = useState(0);
  const [user, setUser] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      if (!u) { window.location.hash = '#/auth'; return; }
      setUser(u);
      setIsAdmin(!!u.email && ADMIN_EMAILS.includes(u.email));
    });
  }, []);

  const handleGenerateTitle = async () => {
    if (!content.trim() || regenCount >= 3 || isGeneratingTitle) return;
    setIsGeneratingTitle(true);
    setSafetyError(null);
    try {
      const analysis = await geminiService.analyzePoem(content.trim());
      if (!analysis.isSafe) {
        setSafetyError(analysis.errorReason || "Violated Resonance detected.");
        return;
      }
      setTitle(analysis.suggestedTitle);
      setRegenCount(prev => prev + 1);
    } catch (err) { console.error("Title Generation Failed:", err); }
    finally { setIsGeneratingTitle(false); }
  };

  const handlePublish = async () => {
    if (!content.trim() || isPublishing) return;
    if (!user) return;

    setIsPublishing(true);
    setSafetyError(null);

    try {
      // Draft is sent to App.tsx's handlePublish which performs the final spectral analysis
      const poemDraft: Partial<Poem> = {
        title: title.trim(),
        content: content.trim(),
        author: user.user_metadata?.display_name || user.email?.split('@')[0] || 'Anonymous',
        userId: user.id,
        timestamp: Date.now()
      };
      await onPublish(poemDraft);
    } catch (err: any) {
      setSafetyError(err.message || "Transmission interrupted by forbidden frequencies.");
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in relative">
      {safetyError && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-3xl animate-fade-in">
          <div className="max-w-xl w-full bg-gradient-to-b from-red-950/20 to-black p-12 border border-red-500/20 text-center space-y-10 shadow-2xl rounded-sm">
            <div className="w-20 h-20 mx-auto border border-red-500/40 rounded-full flex items-center justify-center animate-pulse">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-500/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <div className="space-y-4">
              <h3 className="instrument-serif italic text-4xl text-red-500/90 tracking-tight">Forbidden Resonance</h3>
              <p className="serif-font text-lg italic opacity-60 leading-relaxed text-white">
                "{safetyError}"<br/>
                The Sanctuary requires purity of thought.
              </p>
            </div>
            <button 
              onClick={() => setSafetyError(null)}
              className="w-full py-5 border border-red-500/30 hover:border-red-500 transition-all text-[10px] uppercase tracking-[0.5em] font-black text-red-500/80"
            >
              Adjust Frequency
            </button>
          </div>
        </div>
      )}

      <div className="space-y-12">
        <header className="flex justify-between items-center border-b border-echo-border pb-8">
          <div>
            <h2 className="instrument-serif text-5xl italic text-white">Commit Fragment</h2>
            <p className="text-[9px] uppercase tracking-widest opacity-30 mt-1">
              {isAdmin ? "Admin Publication" : "Community Echo"}
            </p>
          </div>
          <button onClick={onCancel} className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 px-4 py-2 border border-echo-border transition-all text-white">Discard</button>
        </header>

        <div className="space-y-16">
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Title (Label)</p>
              {content.trim() && regenCount < 3 && (
                <button 
                  onClick={handleGenerateTitle}
                  disabled={isGeneratingTitle}
                  className="text-[9px] uppercase tracking-widest opacity-60 hover:opacity-100 transition-all flex items-center space-x-2 border border-white/10 px-3 py-1 bg-white/5 text-white"
                >
                  {isGeneratingTitle ? "Analyzing Content..." : regenCount === 0 ? "Magic Title" : `Regen (${3 - regenCount})`}
                </button>
              )}
            </div>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Leave blank for auto-generation..."
              className="w-full bg-transparent border-b border-echo-border py-4 focus:outline-none instrument-serif text-4xl text-white placeholder:opacity-10 transition-all focus:border-white/40"
              disabled={isPublishing}
            />
          </div>

          <div className="space-y-4">
            <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Fragment</p>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Whisper your thoughts..."
              className="w-full h-80 bg-transparent border border-echo-border p-10 focus:border-white/40 focus:outline-none transition-all serif-font text-2xl italic leading-relaxed shadow-inner text-white/90 rounded-sm"
              disabled={isPublishing}
            />
          </div>

          <div className="space-y-8">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim()}
              className="w-full py-8 bg-white text-black text-[11px] uppercase tracking-[0.5em] font-black hover:bg-neutral-200 transition-all disabled:opacity-20 flex items-center justify-center space-x-4 shadow-2xl"
            >
              {isPublishing ? (
                <>
                  <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />
                  <span>Committing to the Void...</span>
                </>
              ) : (
                <span>Publish Echo</span>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreatePoem;

import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types.ts";

const CACHE_KEY = 'echo_daily_line_v1';
const CACHE_TS = 'echo_daily_ts_v1';

const FALLBACK_SEEDS = [
  "The stars are just holes in the ceiling of a house we forgot we built.",
  "Silence is a conversation we aren't brave enough to have yet.",
  "We are all just ghosts wearing skin, looking for a place to haunt.",
  "Memory is a mirror that only shows the things we've lost.",
  "The wind doesn't blow; it's just the world trying to catch its breath."
];

export const GENRE_POOL = [
  "Noir", "Ethereal", "Minimalist", "Free Verse", "Prose", "Haiku", "Lyric", 
  "Narrative", "Elegy", "Ode", "Sonnet", "Ballad", "Spiritual", "Mystical", 
  "Philosophical", "Existential", "Fragmentary", "Gothic", "Dark Poetry", 
  "Macabre", "Psychological", "Confessional", "Personal", "Meta-Poetry", 
  "Ars Poetica", "Surreal", "Absurdist"
];

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < 86400000) {
      return cached;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];

      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, providedTitle?: string): Promise<PoemMetadata> {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const isTitleMissing = !providedTitle || providedTitle.trim() === '' || providedTitle.toLowerCase() === 'untitled';

      const prompt = `Act as a senior literary critic and safety sentinel for a minimalist poetry sanctuary called "Echo Pages". 
        Analyze this poetry fragment.

        STRICT SAFETY RULES:
        - If the content contains vulgarity, slurs, explicit sexual references, or hate speech, set isSafe: false and errorReason: "Forbidden Resonance detected."
        - The sanctuary is for introspective art. Crude language is rejected.

        LITERARY ANALYSIS CONSTRAINTS:
        1. PREDICTED_GENRE: You MUST choose exactly one from this list: [${GENRE_POOL.join(', ')}]. Do not create new genres.
        2. GENRE_SCORE: Confidence percentage (0-100) of how well it fits that genre.
        3. SUGGESTED_TITLE: Generate a poetic, evocative 2-8 word title based on the theme. Do not use generic titles like "My Poem" or "Reflections".
        4. EMOTION: One word atmospheric tag.
        5. INTENSITY: 0-100 weight.
        6. GRADIENT: CSS 'linear-gradient(180deg, #hex1 0%, #hex2 100%)' using cinematic, atmospheric dark colors.
        7. SAFETY: Boolean flags for isSafe and containsRestricted.

        TITLE PROVIDED: "${isTitleMissing ? 'None' : providedTitle}"
        CONTENT: "${content}"`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              genre: { type: Type.STRING },
              score: { type: Type.INTEGER },
              justification: { type: Type.STRING },
              emotionTag: { type: Type.STRING },
              emotionalWeight: { type: Type.INTEGER },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              containsRestricted: { type: Type.BOOLEAN },
              errorReason: { type: Type.STRING }
            },
            required: ["genre", "score", "justification", "emotionTag", "emotionalWeight", "suggestedTitle", "backgroundGradient", "isSafe", "containsRestricted"]
          }
        }
      });

      const result = JSON.parse(response.text || "{}");
      return {
        genre: GENRE_POOL.includes(result.genre) ? result.genre : "Minimalist",
        score: Math.max(0, Math.min(100, result.score || 70)),
        justification: result.justification || "Atmospheric resonance detected.",
        emotionTag: result.emotionTag || "Echo",
        emotionalWeight: result.emotionalWeight || 50,
        suggestedTitle: result.suggestedTitle || "A Fragmented Echo",
        backgroundGradient: result.backgroundGradient || "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: result.isSafe ?? true,
        containsRestricted: result.containsRestricted ?? false,
        errorReason: result.errorReason
      };
    } catch (error) {
      console.error("AI Analysis Error:", error);
      return {
        genre: "Minimalist",
        score: 50,
        justification: "Processed with default parameters.",
        emotionTag: "Residual",
        emotionalWeight: 40,
        suggestedTitle: providedTitle || "Silent Fragment",
        backgroundGradient: "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: true,
        containsRestricted: false
      };
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Poem, View } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';
import AdminPortal from './components/AdminPortal.tsx';

// Expanded high-contrast atmospheric color pairs for deterministic fallback
const ATMOSPHERIC_PALETTE = [
  ['#0f172a', '#1e1b4b'], ['#1e1b4b', '#450a0a'], ['#020617', '#1e293b'],
  ['#2d0a0a', '#000000'], ['#1e1b0b', '#451a03'], ['#082f49', '#0c4a6e'],
  ['#171717', '#404040'], ['#312e81', '#1e1b4b'], ['#4c1d95', '#1e1b4b']
];

export const getAtmosphericGradient = (id: string) => {
  if (!id) return 'linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)';
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = ((hash << 5) - hash) + id.charCodeAt(i);
    hash |= 0;
  }
  const palette = ATMOSPHERIC_PALETTE[Math.abs(hash) % ATMOSPHERIC_PALETTE.length];
  return `linear-gradient(180deg, ${palette[0]} 0%, ${palette[1]} 100%)`;
};

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const currentViewRef = useRef<View>('home');

  useEffect(() => { currentViewRef.current = currentView; }, [currentView]);

  const [dailyLine, setDailyLine] = useState<string>(() => {
    return localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.";
  });

  const syncStateWithHash = async () => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    setCurrentUser(session?.user ?? null);

    let targetView: View = 'home';
    let targetPoemId: string | null = null;

    if (hash.startsWith('#/p/')) {
      targetView = 'detail';
      targetPoemId = hash.replace('#/p/', '');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed', '#/echoes': 'user-feed', '#/create': 'create', '#/about': 'about',
        '#/contact': 'contact', '#/privacy': 'privacy', '#/profile': 'profile',
        '#/ranks': 'leaderboard', '#/auth': 'auth', '#/admin': 'admin', '#/': 'home'
      };
      targetView = views[hash] || 'home';
    }

    if (['profile', 'create', 'admin'].includes(targetView) && !session) {
      window.location.hash = '#/auth';
      return;
    }

    const lastView = currentViewRef.current;
    if (lastView !== 'detail' && lastView !== targetView) setPreviousView(lastView);

    setSelectedPoemId(targetPoemId);
    setCurrentView(targetView);
  };

  const refreshData = async () => {
    try {
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(),
        supabaseService.getEchoes()
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) { console.error("Data Refresh Failed:", err); }
  };

  useEffect(() => {
    window.addEventListener('hashchange', syncStateWithHash);
    syncStateWithHash();
    refreshData();

    const channel = supabase.channel('global_echo_sync')
      .on('postgres_changes', { event: '*', table: 'echoes', schema: 'public' }, () => refreshData())
      .on('postgres_changes', { event: '*', table: 'admin_poems', schema: 'public' }, () => refreshData())
      .subscribe();

    geminiService.getDailyLine().then(line => setDailyLine(line));

    return () => {
      window.removeEventListener('hashchange', syncStateWithHash);
      supabase.removeChannel(channel);
    };
  }, []);

  const navigateTo = (view: View, poemId: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/', 'feed': '#/read', 'user-feed': '#/echoes', 'create': '#/create',
      'about': '#/about', 'contact': '#/contact', 'privacy': '#/privacy', 'admin': '#/admin',
      'profile': '#/profile', 'leaderboard': '#/ranks', 'auth': '#/auth', 'detail': `#/p/${poemId}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const isAdminUser = newPoem.userId === 'admin' || (!!session?.user?.email && ADMIN_EMAILS.includes(session.user.email));

      // AI analysis - shared for both Read and Echoes
      const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title);

      // Final Safety Barrier
      if (!meta.isSafe) throw new Error(meta.errorReason || "Forbidden Resonance");

      // MVP FEATURE 1: TITLE GENERATION
      // If no title provided by user, always use the AI generated one.
      const finalTitle = (newPoem.title && newPoem.title.trim() !== "" && newPoem.title.toLowerCase() !== 'untitled') 
        ? newPoem.title 
        : meta.suggestedTitle;

      const fullPoem: Partial<Poem> = {
        ...newPoem,
        title: finalTitle,
        emotionTag: meta.emotionTag,
        emotionalWeight: meta.emotionalWeight,
        score: meta.score,
        genre: meta.genre,
        justification: meta.justification,
        backgroundColor: meta.backgroundGradient,
        visibility: isAdminUser ? 'read' : 'echoes'
      };

      let saved: Poem | null = isAdminUser 
        ? await supabaseService.createAdminPoem(fullPoem)
        : await supabaseService.createEcho(fullPoem);

      if (!saved) throw new Error("Sync failure");

      if (isAdminUser) {
        setAdminPoems(prev => [saved!, ...prev]);
        navigateTo('feed');
      } else {
        setUserPoems(prev => [saved!, ...prev]);
        navigateTo('user-feed');
      }
    } catch (err) {
      console.error("Publication Error:", err);
      throw err; 
    }
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text">
      <Header currentView={currentView} onNavigate={navigateTo} />
      <main className="flex-grow">
        {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
        {(currentView === 'feed' || currentView === 'user-feed') && (
          <div className="pt-10 animate-fade-in">
            <header className="mb-12 text-center space-y-4">
              <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-95 tracking-tighter">
                {currentView === 'feed' ? 'Read' : 'Echoes'}
              </h2>
              <p className="text-[10px] uppercase tracking-[0.5em] opacity-80 font-bold">
                {currentView === 'feed' ? 'Curated Introspection' : 'Community Resonance'}
              </p>
            </header>
            <Feed 
              poems={currentView === 'feed' ? adminPoems : userPoems} 
              onSelectPoem={(id) => navigateTo('detail', id)} 
              currentUser={currentUser}
            />
          </div>
        )}
        {currentView === 'detail' && selectedPoem && (
          <PoemDetail poem={selectedPoem} onBack={() => navigateTo(previousView)} />
        )}
        {currentView === 'create' && <CreatePoem onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'admin' && <AdminPortal onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'leaderboard' && <Leaderboard />}
        {currentView === 'profile' && <Profile />}
        {currentView === 'auth' && <Auth />}
        {currentView === 'about' && <About />}
        {currentView === 'contact' && <Contact />}
        {currentView === 'privacy' && <Privacy />}
      </main>
      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Poem } from '../types.ts';
import { GENRES, TONES } from '../constants.ts';
import { getAtmosphericGradient } from '../App.tsx';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  currentUser?: any;
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, currentUser }) => {
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedTone, setSelectedTone] = useState('');

  const filteredPoems = useMemo(() => {
    return poems.filter(p => {
      const matchesSearch = search === '' || 
        p.title.toLowerCase().includes(search.toLowerCase()) || 
        p.content.toLowerCase().includes(search.toLowerCase());
      const matchesGenre = selectedGenre === '' || p.genre === selectedGenre;
      const matchesTone = selectedTone === '' || p.tone === selectedTone;
      return matchesSearch && matchesGenre && matchesTone;
    });
  }, [poems, search, selectedGenre, selectedTone]);

  const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${String(date.getDate()).padStart(2, '0')}-${String(date.getMonth() + 1).padStart(2, '0')}-${date.getFullYear()}`;
  };

  // MVP FEATURE 3: Color Mapping Logic
  const getResonanceColor = (score: number) => {
    if (score < 40) return '#ef4444'; // Red (weak match)
    if (score < 70) return '#f59e0b'; // Yellow/Amber (medium match)
    return '#10b981'; // Green (strong match)
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-12">
      {/* Search & Filters UI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/5 p-6 border border-white/10 rounded-sm backdrop-blur-md">
        <div className="relative">
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Search Fragment</label>
          <input 
            type="text" 
            placeholder="Keywords..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none focus:border-white/40 transition-all text-white placeholder:opacity-20"
          />
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Genre Filter</label>
          <select 
            value={selectedGenre} 
            onChange={(e) => setSelectedGenre(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Genres</option>
            {GENRES.map(g => <option key={g} value={g}>{g}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[8px] uppercase tracking-[0.3em] opacity-40 mb-2 block font-black text-white">Tone Filter</label>
          <select 
            value={selectedTone} 
            onChange={(e) => setSelectedTone(e.target.value)}
            className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none w-full text-white"
          >
            <option value="">All Tones</option>
            {TONES.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
          </select>
        </div>
      </div>

      {/* Poems Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
        {filteredPoems.map((poem, index) => {
          const backgroundStyle = poem.backgroundColor || getAtmosphericGradient(poem.id);
          const resonanceColor = getResonanceColor(poem.score);

          return (
            <article 
              key={poem.id}
              onClick={() => onSelectPoem(poem.id)}
              className="group cursor-pointer border border-echo-border p-8 md:p-10 flex flex-col justify-between hover:border-white/30 transition-all duration-700 animate-fade-in relative overflow-hidden rounded-sm shadow-2xl"
              style={{ 
                animationDelay: `${index * 50}ms`, 
                animationFillMode: 'both',
                background: backgroundStyle
              }}
            >
              <div className="flex-grow space-y-8 relative z-10">
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <span className="text-[9px] uppercase tracking-[0.2em] font-black text-white/90">
                      {poem.genre}
                    </span>
                    <span className="text-[9px] font-mono font-bold text-white/60">
                      Match: {Math.round(poem.score)}%
                    </span>
                  </div>

                  {/* MVP FEATURE 3: RESONANCE BAR */}
                  <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                    <div 
                      className="h-full transition-all duration-1000 ease-out"
                      style={{ 
                        width: `${poem.score}%`, 
                        backgroundColor: resonanceColor,
                        boxShadow: `0 0 8px ${resonanceColor}66`
                      }}
                    />
                  </div>
                </div>

                <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-[1.1] text-white/95 group-hover:text-white group-hover:italic transition-all duration-500">
                  {poem.title}
                </h2>
              </div>

              <div className="mt-12 space-y-6 relative z-10">
                <div className="h-[1px] w-full bg-white/10 group-hover:bg-white/30 transition-colors" />
                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-bold text-white/60 group-hover:text-white/95 transition-colors">
                  <span className="italic">@{poem.author}</span>
                  <span className="font-mono opacity-40">{formatDate(poem.timestamp)}</span>
                </div>
              </div>

              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
            </article>
          );
        })}
      </div>

      {filteredPoems.length === 0 && (
        <div className="text-center py-40 opacity-80 instrument-serif italic text-2xl text-white">
          The silence persists.
        </div>
      )}
    </div>
  );
};

export default Feed;

