/**
 * Echo Pages Validation Service
 * Protects the sanctuary from junk, spam, and forbidden language.
 */

const RATE_LIMIT_MS = 60000; // 1 minute between posts
const DAILY_LIMIT = 10;
const MIN_LENGTH = 10;
const MAX_LENGTH = 2000;

// Local blacklist for immediate rejection (shorter list for performance, AI handles the rest)
const BLACKLIST = ['nazi', 'hitler', 'porn', 'nsfw', 'f*ck', 'sh*t']; 

export const validationService = {
  checkRateLimit(userId: string): { allowed: boolean; reason?: string } {
    const now = Date.now();
    const lastPost = localStorage.getItem(`echo_last_post_${userId}`);
    const postHistory = JSON.parse(localStorage.getItem(`echo_history_${userId}`) || '[]');

    // 1. Minimum Interval Check
    if (lastPost && now - parseInt(lastPost) < RATE_LIMIT_MS) {
      const remaining = Math.ceil((RATE_LIMIT_MS - (now - parseInt(lastPost))) / 1000);
      return { allowed: false, reason: `Frequency flooding detected. Re-tune in ${remaining}s.` };
    }

    // 2. Daily Volume Check
    const today = new Date().toDateString();
    const postsToday = postHistory.filter((p: string) => new Date(parseInt(p)).toDateString() === today);
    if (postsToday.length >= DAILY_LIMIT) {
      return { allowed: false, reason: "Your daily resonance is exhausted. Return with the next moon." };
    }

    return { allowed: true };
  },

  recordPost(userId: string) {
    const now = Date.now();
    localStorage.setItem(`echo_last_post_${userId}`, now.toString());
    const history = JSON.parse(localStorage.getItem(`echo_history_${userId}`) || '[]');
    history.push(now.toString());
    localStorage.setItem(`echo_history_${userId}`, JSON.stringify(history.slice(-20)));
  },

  validateContent(content: string): { valid: boolean; reason?: string } {
    const text = content.trim();

    if (text.length < MIN_LENGTH) return { valid: false, reason: "Fragment is too brief to echo." };
    if (text.length > MAX_LENGTH) return { valid: false, reason: "Resonance is too loud; simplify your fragment." };

    // Junk/Spam detection (e.g., repeated characters)
    if (/(.)\1{5,}/.test(text)) return { valid: false, reason: "Structural static detected (junk patterns)." };

    // Local profanity check
    const containsBlacklist = BLACKLIST.some(word => text.toLowerCase().includes(word));
    if (containsBlacklist) return { valid: false, reason: "Forbidden vocabulary detected." };

    return { valid: true };
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { PoemMetadata } from "../types.ts";
import { CONFIG } from "../config.ts";

const CACHE_KEY = 'echo_daily_line_v1';
const CACHE_TS = 'echo_daily_ts_v1';

const FALLBACK_SEEDS = [
  "The stars are just holes in the ceiling of a house we forgot we built.",
  "Silence is a conversation we aren't brave enough to have yet.",
  "We are all just ghosts wearing skin, looking for a place to haunt.",
  "Memory is a mirror that only shows the things we've lost.",
  "The bottom of the sky is closer than the top of the earth."
];

export const geminiService = {
  async getDailyLine(): Promise<string> {
    const cached = localStorage.getItem(CACHE_KEY);
    const ts = localStorage.getItem(CACHE_TS);
    const now = Date.now();

    if (cached && ts && (now - parseInt(ts)) < CONFIG.DAILY_LINE_CACHE_DURATION) {
      return cached;
    }

    try {
      const key = process.env.API_KEY;
      if (!key || key === 'undefined') throw new Error("Key missing");

      const ai = new GoogleGenAI({ apiKey: key });
      const response = await ai.models.generateContent({
        model: CONFIG.DEFAULT_MODEL,
        contents: "Generate one hauntingly beautiful, short, introspective line of poetry. No quotation marks. No explanation.",
      });
      const newLine = response.text?.trim() || FALLBACK_SEEDS[0];
      localStorage.setItem(CACHE_KEY, newLine);
      localStorage.setItem(CACHE_TS, now.toString());
      return newLine;
    } catch (error) {
      console.warn("AI Frequency Interrupted:", error);
      return cached || FALLBACK_SEEDS[Math.floor(Math.random() * FALLBACK_SEEDS.length)];
    }
  },

  async analyzePoem(content: string, providedTitle?: string): Promise<PoemMetadata> {
    try {
      const key = process.env.API_KEY;
      if (!key || key === 'undefined') throw new Error("Frequency Missing");

      const ai = new GoogleGenAI({ apiKey: key });
      const isTitleMissing = !providedTitle || providedTitle.trim() === '' || providedTitle.toLowerCase() === 'untitled';

      // Enhanced prompt with strict safety instructions
      const systemInstruction = `You are the Sanctuary Guardian for "Echo Pages", a minimalist poetry platform. 
      Your task is to analyze poetry for genre, title, and most importantly, SAFETY.
      REJECT (isSafe: false) if the text contains:
      - Explicit violence, hate speech, or dehumanizing language.
      - Explicit sexual content or graphic anatomical descriptions.
      - Self-harm glorification.
      - Profanity used in a toxic, non-poetic manner.

      Atmosphere: Introspective, Haunting, Dark-Academic.`;

      const response = await ai.models.generateContent({
        model: CONFIG.DEFAULT_MODEL,
        contents: `Analyze this poetic fragment. Title Provided: "${isTitleMissing ? 'None' : providedTitle}". Fragment: "${content}"`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              genre: { type: Type.STRING },
              score: { type: Type.INTEGER },
              justification: { type: Type.STRING },
              suggestedTitle: { type: Type.STRING },
              backgroundGradient: { type: Type.STRING },
              isSafe: { type: Type.BOOLEAN },
              rejectionReason: { type: Type.STRING, description: "If isSafe is false, explain why concisely." }
            },
            required: ["genre", "score", "justification", "suggestedTitle", "backgroundGradient", "isSafe"]
          }
        }
      });

      const result = JSON.parse(response.text || "{}");
      return {
        genre: result.genre || "Minimalist",
        score: Math.max(0, Math.min(100, result.score || 70)),
        justification: result.justification || "Atmospheric resonance detected.",
        suggestedTitle: result.suggestedTitle || "A Fragmented Echo",
        backgroundGradient: result.backgroundGradient || "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: result.isSafe ?? true,
        containsRestricted: !(result.isSafe ?? true),
        errorReason: result.rejectionReason
      };
    } catch (error: any) {
      console.warn("AI Safety Fallback active:", error);
      // If AI service fails, we assume safety for standard cases but fail for known error codes
      const isSafetyError = error?.message?.includes('SAFETY') || error?.status === 400;

      return {
        genre: "Minimalist",
        score: 75,
        justification: "Resonance persists despite external silence.",
        suggestedTitle: (providedTitle && providedTitle !== 'Untitled') ? providedTitle : "Silent Fragment",
        backgroundGradient: "linear-gradient(180deg, #0f172a 0%, #1e1b4b 100%)",
        isSafe: !isSafetyError,
        containsRestricted: isSafetyError,
        errorReason: isSafetyError ? "The AI Sanctuary blocked this frequency for safety reasons." : undefined
      };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Poem } from '../types.ts';
import { CONFIG } from '../config.ts';
import { supabase } from '../services/supabaseService.ts';
import { ADMIN_EMAILS } from '../constants.ts';
import { geminiService } from '../services/geminiService.ts';
import { validationService } from '../services/validationService.ts';

interface CreatePoemProps {
  onPublish: (poem: Partial<Poem>) => Promise<void>;
  onCancel: () => void;
}

const CreatePoem: React.FC<CreatePoemProps> = ({ onPublish, onCancel }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [isPublishing, setIsPublishing] = useState(false);
  const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
  const [safetyError, setSafetyError] = useState<string | null>(null);
  const [regenCount, setRegenCount] = useState(0);
  const [user, setUser] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      if (!u) { window.location.hash = '#/auth'; return; }
      setUser(u);
      setIsAdmin(!!u.email && ADMIN_EMAILS.includes(u.email));
    });
  }, []);

  const handleGenerateTitle = async () => {
    if (!content.trim() || regenCount >= CONFIG.MAX_TITLE_REGEN || isGeneratingTitle) return;

    // Local pre-check
    const localVal = validationService.validateContent(content);
    if (!localVal.valid) {
      setSafetyError(localVal.reason || "Invalid fragment.");
      return;
    }

    setIsGeneratingTitle(true);
    setSafetyError(null);
    try {
      const analysis = await geminiService.analyzePoem(content.trim());
      if (!analysis.isSafe) {
        setSafetyError(analysis.errorReason || "Violated Resonance detected.");
        return;
      }
      setTitle(analysis.suggestedTitle);
      setRegenCount(prev => prev + 1);
    } catch (err) { console.error("Title Generation Failed:", err); }
    finally { setIsGeneratingTitle(false); }
  };

  const handlePublish = async () => {
    if (!content.trim() || isPublishing) return;
    if (!user) return;

    // 1. Rate Limit Check
    const rateCheck = validationService.checkRateLimit(user.id);
    if (!rateCheck.allowed && !isAdmin) {
      setSafetyError(rateCheck.reason || "Frequency limit reached.");
      return;
    }

    // 2. Local Validation Check
    const localVal = validationService.validateContent(content);
    if (!localVal.valid) {
      setSafetyError(localVal.reason || "Structural dissonance detected.");
      return;
    }

    setIsPublishing(true);
    setSafetyError(null);

    try {
      const poemDraft: Partial<Poem> = {
        title: title.trim(),
        content: content.trim(),
        author: user.user_metadata?.display_name || user.email?.split('@')[0] || 'Anonymous',
        userId: user.id,
        timestamp: Date.now()
      };
      await onPublish(poemDraft);
      validationService.recordPost(user.id);
    } catch (err: any) {
      setSafetyError(err.message || "Transmission interrupted by forbidden frequencies.");
      setIsPublishing(false);
    }
  };

  const charCount = content.trim().length;
  const isTooLong = charCount > 2000;
  const isTooShort = charCount > 0 && charCount < 10;

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in relative">
      {safetyError && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-3xl animate-fade-in">
          <div className="max-w-xl w-full bg-gradient-to-b from-red-950/20 to-black p-12 border border-red-500/20 text-center space-y-10 shadow-2xl rounded-sm">
            <div className="w-20 h-20 mx-auto border border-red-500/40 rounded-full flex items-center justify-center animate-pulse">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-500/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <div className="space-y-4">
              <h3 className="instrument-serif italic text-4xl text-red-500/90 tracking-tight">Forbidden Resonance</h3>
              <p className="serif-font text-lg italic opacity-60 leading-relaxed text-white">
                "{safetyError}"<br/>
                The Sanctuary requires purity of thought and rhythm.
              </p>
            </div>
            <button 
              onClick={() => setSafetyError(null)}
              className="w-full py-5 border border-red-500/30 hover:border-red-500 transition-all text-[10px] uppercase tracking-[0.5em] font-black text-red-500/80"
            >
              Adjust Frequency
            </button>
          </div>
        </div>
      )}

      <div className="space-y-12">
        <header className="flex justify-between items-center border-b border-echo-border pb-8">
          <div>
            <h2 className="instrument-serif text-5xl italic text-white">Commit Fragment</h2>
            <p className="text-[9px] uppercase tracking-widest opacity-30 mt-1">
              {isAdmin ? "Admin Publication" : "Community Echo"}
            </p>
          </div>
          <button onClick={onCancel} className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 px-4 py-2 border border-echo-border transition-all text-white">Discard</button>
        </header>

        <div className="space-y-16">
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Title (Label)</p>
              {content.trim() && !isTooLong && !isTooShort && regenCount < CONFIG.MAX_TITLE_REGEN && (
                <button 
                  onClick={handleGenerateTitle}
                  disabled={isGeneratingTitle}
                  className="text-[9px] uppercase tracking-widest opacity-60 hover:opacity-100 transition-all flex items-center space-x-2 border border-white/10 px-3 py-1 bg-white/5 text-white"
                >
                  {isGeneratingTitle ? "Analyzing Content..." : regenCount === 0 ? "Magic Title" : `Regen (${CONFIG.MAX_TITLE_REGEN - regenCount})`}
                </button>
              )}
            </div>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Leave blank for auto-generation..."
              className="w-full bg-transparent border-b border-echo-border py-4 focus:outline-none instrument-serif text-4xl text-white placeholder:opacity-10 transition-all focus:border-white/40"
              disabled={isPublishing}
              maxLength={100}
            />
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Fragment</p>
              <span className={`text-[9px] font-mono tracking-widest ${isTooLong ? 'text-red-500' : 'text-white/40'}`}>
                {charCount} / 2000
              </span>
            </div>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Whisper your thoughts..."
              className={`w-full h-80 bg-transparent border ${isTooLong ? 'border-red-500/50' : 'border-echo-border'} p-10 focus:border-white/40 focus:outline-none transition-all serif-font text-2xl italic leading-relaxed shadow-inner text-white/90 rounded-sm`}
              disabled={isPublishing}
            />
            {isTooShort && <p className="text-[9px] uppercase tracking-widest text-white/20 italic">The silence is too heavy; add more words.</p>}
          </div>

          <div className="space-y-8">
            <button
              onClick={handlePublish}
              disabled={isPublishing || !content.trim() || isTooLong || isTooShort}
              className="w-full py-8 bg-white text-black text-[11px] uppercase tracking-[0.5em] font-black hover:bg-neutral-200 transition-all disabled:opacity-20 flex items-center justify-center space-x-4 shadow-2xl"
            >
              {isPublishing ? (
                <>
                  <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />
                  <span>Committing to the Void...</span>
                </>
              ) : (
                <span>Publish Echo</span>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

