            </div>

            {isEditing ? (
              <div className="space-y-6">
                <div className="space-y-1">
                  <label className="text-[8px] uppercase tracking-widest opacity-40">Display Name</label>
                  <input 
                    type="text" 
                    value={displayName}
                    onChange={e => setDisplayName(e.target.value)}
