const mapFromDb = (data: any, currentUserId?: string): Poem => ({
  id: String(data.id),
  title: data.title || '...',
  content: data.content || '',
  author: data.author || 'Anonymous',
  userId: data.user_id || '',
  timestamp: data.created_at ? new Date(data.created_at).getTime() : Date.now(),
  score: Number(data.score) || 0,
  genre: data.genre || 'Echo',
  justification: data.justification || '',
  backgroundColor: data.background_color || '',
  visibility: data.visibility || 'echoes',
  isEdited: data.is_edited || false,
  likesCount: data.likes_count || 0,
  dislikesCount: data.dislikes_count || 0,
  userReaction: data.user_reaction as ReactionType || null
});

export const supabaseService = {
  async getEchoes(currentUserId?: string): Promise<Poem[]> {
    // In a real app, we'd use a view or join to get reaction counts and user's reaction
    const { data, error } = await supabase.from('echoes').select('*').order('created_at', { ascending: false });
    if (error) return [];

    // Supplement with reaction data (simulated for MVP)
    const echoes = await Promise.all((data || []).map(async d => {
      const counts = await this.getReactionCounts(d.id, currentUserId);
      return mapFromDb({ ...d, ...counts }, currentUserId);
    }));
    return echoes;
  },

  async getAdminPoems(currentUserId?: string): Promise<Poem[]> {
    const { data, error } = await supabase.from('admin_poems').select('*').order('created_at', { ascending: false });
    if (error) return [];
    const poems = await Promise.all((data || []).map(async d => {
      const counts = await this.getReactionCounts(d.id, currentUserId);
      return mapFromDb({ ...d, ...counts }, currentUserId);
    }));
    return poems;
  },

  async createEcho(poem: Partial<Poem>): Promise<Poem | null> {
    const { data, error } = await supabase.from('echoes').insert([{
      title: poem.title,
      content: poem.content,
      author: poem.author,
      user_id: poem.userId,
      score: poem.score,
      genre: poem.genre,
      justification: poem.justification,
      background_color: poem.backgroundColor
    }]).select();
    return (data && data[0]) ? mapFromDb(data[0]) : null;
  },

  async updateEcho(id: string, updates: Partial<Poem>): Promise<boolean> {
    const { error } = await supabase.from('echoes').update({
      title: updates.title,
      content: updates.content,
      is_edited: true
    }).eq('id', id);
    return !error;
  },

  async deleteEcho(id: string): Promise<boolean> {
    const { error } = await supabase.from('echoes').delete().eq('id', id);
    return !error;
  },

  async createAdminPoem(poem: Partial<Poem>): Promise<Poem | null> {
    const { data, error } = await supabase.from('admin_poems').insert([{
      title: poem.title,
      content: poem.content,
      author: 'Admin',
      user_id: poem.userId || 'admin',
      score: poem.score,
      genre: poem.genre,
      justification: poem.justification,
      background_color: poem.backgroundColor
    }]).select();
    return (data && data[0]) ? mapFromDb(data[0]) : null;
  },

  // Reaction System
  async toggleReaction(poemId: string, userId: string, type: ReactionType): Promise<boolean> {
    // 1. Check existing
    const { data: existing } = await supabase.from('reactions').select('*').match({ poem_id: poemId, user_id: userId }).maybeSingle();

    if (existing) {
      if (existing.reaction_type === type) {
        // Remove if same type (toggle off)
        const { error } = await supabase.from('reactions').delete().match({ poem_id: poemId, user_id: userId });
        return !error;
      } else {
        // Update if different type (switch)
        const { error } = await supabase.from('reactions').update({ reaction_type: type }).match({ poem_id: poemId, user_id: userId });
        return !error;
      }
    } else {
      // Create new
      const { error } = await supabase.from('reactions').insert([{ poem_id: poemId, user_id: userId, reaction_type: type }]);
      return !error;
    }
  },

  async getReactionCounts(poemId: string, currentUserId?: string): Promise<{ likes_count: number, dislikes_count: number, user_reaction: ReactionType }> {
    const { data: reactions, error } = await supabase.from('reactions').select('reaction_type, user_id').eq('poem_id', poemId);
    if (error) return { likes_count: 0, dislikes_count: 0, user_reaction: null };

    const likes = reactions.filter(r => r.reaction_type === 'like').length;
    const dislikes = reactions.filter(r => r.reaction_type === 'dislike').length;
    const userReaction = currentUserId ? (reactions.find(r => r.user_id === currentUserId)?.reaction_type as ReactionType || null) : null;

    return { likes_count: likes, dislikes_count: dislikes, user_reaction: userReaction };
  },

  // Follow System
  async followUser(followerId: string, followingId: string) {
    const { error } = await supabase.from('follows').insert([{
      follower_id: followerId,
      following_id: followingId
    }]);
    return !error;
  },

  async unfollowUser(followerId: string, followingId: string) {
    const { error } = await supabase.from('follows').delete().match({
      follower_id: followerId,
      following_id: followingId
    });
    return !error;
  },

  async getFollowingIds(userId: string): Promise<string[]> {
    const { data, error } = await supabase.from('follows').select('following_id').eq('follower_id', userId);
    return error ? [] : (data || []).map(d => d.following_id);
  },

  async getLeaderboard(): Promise<LeaderboardEntry[]> {
    const { data, error } = await supabase.from('echoes').select('user_id, author, score');
    if (error) return [];
    const userMap: Record<string, any> = {};
    data?.forEach(d => {
      if (!userMap[d.user_id]) userMap[d.user_id] = { totalScore: 0, count: 0, name: d.author };
      userMap[d.user_id].totalScore += (d.score ?? 0);
      userMap[d.user_id].count += 1;
    });
    return Object.entries(userMap).map(([id, val]: any) => ({
      userId: id,
      username: val.name,
      displayName: val.name,
      score: Math.round(val.totalScore / val.count),
      poemCount: val.count
    })).sort((a, b) => b.poemCount - a.poemCount).slice(0, 10);
  },

  async getUserProfile(userId: string): Promise<UserProfile | null> {
    const [echoes, followers, following, userData] = await Promise.all([
      supabase.from('echoes').select('score').eq('user_id', userId),
      supabase.from('follows').select('*', { count: 'exact', head: true }).eq('following_id', userId),
      supabase.from('follows').select('*', { count: 'exact', head: true }).eq('follower_id', userId),
      supabase.auth.getUser() // This only gets current user, real profiles table needed for others
    ]);

    const totalPoems = echoes.data?.length || 0;
    const avgScore = totalPoems > 0 ? Math.round(echoes.data!.reduce((acc, c) => acc + (c.score || 0), 0) / totalPoems) : 0;

    return {
      id: userId,
      username: 'observer',
      displayName: 'Observer',
      totalPoems,
      avgScore,
      followersCount: followers.count || 0,
      followingCount: following.count || 0,
      hideReactionsPreference: false // Default
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Poem, View, ReactionType } from './types.ts';
import { geminiService } from './services/geminiService.ts';
import { supabaseService, supabase } from './services/supabaseService.ts';
import { ADMIN_EMAILS } from './constants.ts';

import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import Home from './components/Home.tsx';
import Feed from './components/Feed.tsx';
import PoemDetail from './components/PoemDetail.tsx';
import CreatePoem from './components/CreatePoem.tsx';
import About from './components/About.tsx';
import Contact from './components/Contact.tsx';
import Privacy from './components/Privacy.tsx';
import Profile from './components/Profile.tsx';
import Leaderboard from './components/Leaderboard.tsx';
import Auth from './components/Auth.tsx';
import AdminPortal from './components/AdminPortal.tsx';

const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [followingIds, setFollowingIds] = useState<string[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [targetUserId, setTargetUserId] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [dailyLine, setDailyLine] = useState<string>(() => localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.");
  const [editPoem, setEditPoem] = useState<Poem | null>(null);

  const currentViewRef = useRef<View>('home');
  useEffect(() => { currentViewRef.current = currentView; }, [currentView]);

  const syncStateWithHash = async () => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const u = session?.user ?? null;
    setCurrentUser(u);

    if (u) {
      const ids = await supabaseService.getFollowingIds(u.id);
      setFollowingIds(ids);
    }

    let targetView: View = 'home';
    let targetPoemId: string | null = null;
    let tUserId: string | null = null;

    if (hash.startsWith('#/p/')) {
      targetView = 'detail';
      targetPoemId = hash.replace('#/p/', '');
    } else if (hash.startsWith('#/u/')) {
      targetView = 'user-profile';
      tUserId = hash.replace('#/u/', '');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed', '#/echoes': 'user-feed', '#/create': 'create', '#/about': 'about',
        '#/contact': 'contact', '#/privacy': 'privacy', '#/profile': 'profile',
        '#/ranks': 'leaderboard', '#/auth': 'auth', '#/admin': 'admin', '#/': 'home'
      };
      targetView = views[hash] || 'home';
    }

    if (['profile', 'create', 'admin'].includes(targetView) && !session) {
      window.location.hash = '#/auth';
      return;
    }

    if (currentViewRef.current !== 'detail' && currentViewRef.current !== targetView) setPreviousView(currentViewRef.current);
    setSelectedPoemId(targetPoemId);
    setTargetUserId(tUserId);
    setCurrentView(targetView);
  };

  const refreshData = async () => {
    try {
      const uId = currentUser?.id;
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(uId),
        supabaseService.getEchoes(uId)
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) { console.error("Data Sync Error:", err); }
  };

  useEffect(() => {
    window.addEventListener('hashchange', syncStateWithHash);
    syncStateWithHash();
    geminiService.getDailyLine().then(line => setDailyLine(line));
    return () => window.removeEventListener('hashchange', syncStateWithHash);
  }, []);

  useEffect(() => {
    refreshData();
  }, [currentUser, currentView]);

  const navigateTo = (view: View, id: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/', 'feed': '#/read', 'user-feed': '#/echoes', 'create': '#/create',
      'about': '#/about', 'contact': '#/contact', 'privacy': '#/privacy', 'admin': '#/admin',
      'profile': '#/profile', 'leaderboard': '#/ranks', 'auth': '#/auth', 
      'detail': `#/p/${id}`, 'user-profile': `#/u/${id}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title);
    if (!meta.isSafe) throw new Error("Forbidden Resonance");

    const isAdminUser = !!currentUser?.email && ADMIN_EMAILS.includes(currentUser.email);
    const finalPoem: Partial<Poem> = {
      ...newPoem,
      title: (newPoem.title && newPoem.title.trim() !== "" && newPoem.title.toLowerCase() !== 'untitled') ? newPoem.title : meta.suggestedTitle,
      score: meta.score,
      genre: meta.genre,
      justification: meta.justification,
      backgroundColor: meta.backgroundGradient,
      visibility: isAdminUser ? 'read' : 'echoes'
    };

    const saved = isAdminUser ? await supabaseService.createAdminPoem(finalPoem) : await supabaseService.createEcho(finalPoem);
    if (!saved) throw new Error("Transmission Failed");
    refreshData();
    navigateTo(isAdminUser ? 'feed' : 'user-feed');
  };

  const handleEdit = (poem: Poem) => {
    setEditPoem(poem);
    navigateTo('create');
  };

  const handleUpdate = async (id: string, updates: Partial<Poem>) => {
    const success = await supabaseService.updateEcho(id, updates);
    if (success) {
      setEditPoem(null);
      refreshData();
      navigateTo('detail', id);
    } else {
      throw new Error("Update failed");
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("This echo will be lost to the void forever. Proceed?")) {
      const success = await supabaseService.deleteEcho(id);
      if (success) {
        refreshData();
        navigateTo('user-feed');
      }
    }
  };

  const handleToggleReaction = async (poemId: string, type: ReactionType) => {
    if (!currentUser) { navigateTo('auth'); return; }
    const success = await supabaseService.toggleReaction(poemId, currentUser.id, type);
    if (success) refreshData();
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);
  const hideReactions = currentUser?.user_metadata?.hide_reactions || false;

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text selection:bg-neutral-800">
      <Header currentView={currentView} onNavigate={navigateTo} />
      <main className="flex-grow">
        {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
        {(currentView === 'feed' || currentView === 'user-feed') && (
          <div className="pt-10 animate-fade-in">
            <header className="mb-12 text-center space-y-4">
              <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-95 tracking-tighter">
                {currentView === 'feed' ? 'Read' : 'Echoes'}
              </h2>
              <p className="text-[10px] uppercase tracking-[0.5em] opacity-80 font-bold">
                {currentView === 'feed' ? 'Curated Introspection' : 'Community Resonance'}
              </p>
            </header>
            <Feed 
              poems={currentView === 'feed' ? adminPoems : userPoems} 
              onSelectPoem={(id) => navigateTo('detail', id)} 
              followingIds={followingIds}
              onNavigateUser={(userId) => navigateTo('user-profile', userId)}
              onToggleReaction={handleToggleReaction}
              hideReactionCounts={hideReactions}
            />
          </div>
        )}
        {currentView === 'detail' && selectedPoem && (
          <PoemDetail 
            poem={selectedPoem} 
            onBack={() => navigateTo(previousView)} 
            currentUser={currentUser}
            onEdit={() => handleEdit(selectedPoem)}
            onDelete={() => handleDelete(selectedPoem.id)}
            onNavigateUser={(userId) => navigateTo('user-profile', userId)}
            onToggleReaction={handleToggleReaction}
            hideReactionCounts={hideReactions}
          />
        )}
        {currentView === 'create' && (
          <CreatePoem 
            onPublish={handlePublish} 
            onUpdate={handleUpdate}
            initialPoem={editPoem}
            onCancel={() => { setEditPoem(null); navigateTo('home'); }} 
          />
        )}
        {currentView === 'admin' && <AdminPortal onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'leaderboard' && <Leaderboard />}
        {currentView === 'profile' && <Profile />}
        {currentView === 'user-profile' && <Profile userId={targetUserId} />}
        {currentView === 'auth' && <Auth />}
        {currentView === 'about' && <About />}
        {currentView === 'contact' && <Contact />}
        {currentView === 'privacy' && <Privacy />}
      </main>
      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Poem, ReactionType } from '../types.ts';
import { GENRES, TONES } from '../constants.ts';
import { getAtmosphericGradient, getResonanceColor, formatDate } from '../utils.ts';

interface FeedProps {
  poems: Poem[];
  onSelectPoem: (id: string) => void;
  followingIds?: string[];
  onNavigateUser?: (userId: string) => void;
  onToggleReaction?: (poemId: string, type: ReactionType) => void;
  hideReactionCounts?: boolean;
}

const Feed: React.FC<FeedProps> = ({ poems, onSelectPoem, followingIds = [], onNavigateUser, onToggleReaction, hideReactionCounts }) => {
  const [search, setSearch] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedTone, setSelectedTone] = useState('');

  const filteredPoems = useMemo(() => {
    const filtered = poems.filter(p => {
      const matchesSearch = search === '' || p.title.toLowerCase().includes(search.toLowerCase()) || p.content.toLowerCase().includes(search.toLowerCase());
      const matchesGenre = selectedGenre === '' || p.genre === selectedGenre;
      const matchesTone = selectedTone === '' || p.tone === selectedTone;
      return matchesSearch && matchesGenre && matchesTone;
    });

    // Signal > Noise Prioritization
    return filtered.sort((a, b) => {
      const aFollowed = followingIds.includes(a.userId);
      const bFollowed = followingIds.includes(b.userId);

      if (aFollowed && !bFollowed) return -1;
      if (!aFollowed && bFollowed) return 1;

      return b.timestamp - a.timestamp;
    });
  }, [poems, search, selectedGenre, selectedTone, followingIds]);

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-12">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-white/5 p-6 border border-white/10 rounded-sm backdrop-blur-md">
        <input 
          type="text" placeholder="Search Keywords..." value={search} onChange={(e) => setSearch(e.target.value)}
          className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none focus:border-white/40 transition-all text-white"
        />
        <select value={selectedGenre} onChange={(e) => setSelectedGenre(e.target.value)} className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none text-white">
          <option value="">All Genres</option>
          {GENRES.map(g => <option key={g} value={g}>{g}</option>)}
        </select>
        <select value={selectedTone} onChange={(e) => setSelectedTone(e.target.value)} className="bg-black/40 border border-white/10 px-4 py-3 text-[10px] uppercase tracking-widest focus:outline-none text-white">
          <option value="">All Tones</option>
          {TONES.map(t => <option key={t.id} value={t.id}>{t.label}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
        {filteredPoems.map((poem, index) => {
          const isFollowed = followingIds.includes(poem.userId);
          return (
            <article 
              key={poem.id}
              className={`group border p-8 md:p-10 flex flex-col justify-between hover:border-white/40 transition-all duration-700 animate-fade-in relative overflow-hidden rounded-sm shadow-2xl ${isFollowed ? 'border-white/40 ring-1 ring-white/10' : 'border-echo-border'}`}
              style={{ animationDelay: `${index * 50}ms`, background: poem.backgroundColor || getAtmosphericGradient(poem.id) }}
            >
              <div onClick={() => onSelectPoem(poem.id)} className="flex-grow space-y-8 relative z-10 cursor-pointer">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2">
                    <span className="text-[9px] uppercase tracking-[0.2em] font-black text-white/90">{poem.genre}</span>
                    {isFollowed && (
                      <span className="bg-white/20 text-[7px] px-1.5 py-0.5 rounded-full uppercase tracking-tighter text-white font-black">Following</span>
                    )}
                  </div>
                  <span className="text-[9px] font-mono font-bold text-white/60">Match: {Math.round(poem.score)}%</span>
                </div>
                <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden">
                  <div className="h-full transition-all duration-1000 ease-out" style={{ width: `${poem.score}%`, backgroundColor: getResonanceColor(poem.score) }} />
                </div>
                <h2 className="instrument-serif text-3xl md:text-4xl uppercase tracking-tight leading-[1.1] text-white/95 group-hover:text-white group-hover:italic transition-all duration-500">
                  {poem.title}
                </h2>
              </div>

              <div className="mt-8 flex items-center space-x-6 relative z-10">
                <button 
                  onClick={(e) => { e.stopPropagation(); onToggleReaction?.(poem.id, 'like'); }}
                  className={`flex items-center space-x-2 transition-all ${poem.userReaction === 'like' ? 'text-white' : 'opacity-40 hover:opacity-100 text-white'}`}
                >
                  <span className="text-sm">{poem.userReaction === 'like' ? '👍' : '👍'}</span>
                  {!hideReactionCounts && <span className="text-[9px] font-mono">{poem.likesCount}</span>}
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); onToggleReaction?.(poem.id, 'dislike'); }}
                  className={`flex items-center space-x-2 transition-all ${poem.userReaction === 'dislike' ? 'text-white' : 'opacity-40 hover:opacity-100 text-white'}`}
                >
                  <span className="text-sm">{poem.userReaction === 'dislike' ? '👎' : '👎'}</span>
                  {!hideReactionCounts && <span className="text-[9px] font-mono">{poem.dislikesCount}</span>}
                </button>
              </div>

              <div className="mt-8 space-y-6 relative z-10">
                <div className="h-[1px] w-full bg-white/10 group-hover:bg-white/30 transition-colors" />
                <div className="flex justify-between items-center text-[10px] uppercase tracking-widest font-bold text-white/60">
                  <span 
                    className="italic hover:text-white cursor-pointer transition-colors"
                    onClick={(e) => { e.stopPropagation(); onNavigateUser?.(poem.userId); }}
                  >
                    @{poem.author}
                  </span>
                  <span className="font-mono opacity-40">{formatDate(poem.timestamp)}</span>
                </div>
              </div>
            </article>
          );
        })}
      </div>

      {filteredPoems.length === 0 && <div className="text-center py-40 opacity-80 instrument-serif italic text-2xl text-white">The silence persists.</div>}
    </div>
  );
};

export default Feed;

import React, { useEffect, useState } from 'react';
import { Poem, ReactionType } from '../types.ts';
import { getAtmosphericGradient, getResonanceColor, formatLongDate } from '../utils.ts';

interface PoemDetailProps {
  poem: Poem;
  onBack: () => void;
  currentUser?: any;
  onEdit?: () => void;
  onDelete?: () => void;
  onNavigateUser?: (userId: string) => void;
  onToggleReaction?: (poemId: string, type: ReactionType) => void;
  hideReactionCounts?: boolean;
}

const PoemDetail: React.FC<PoemDetailProps> = ({ poem, onBack, currentUser, onEdit, onDelete, onNavigateUser, onToggleReaction, hideReactionCounts }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');

  useEffect(() => {
    setIsVisible(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    return () => setIsVisible(false);
  }, []);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(`${window.location.origin}/#/p/${poem.id}`).then(() => {
      setCopyStatus('copied');
      setTimeout(() => setCopyStatus('idle'), 2000);
    });
  };

  const isAuthor = currentUser && currentUser.id === poem.userId;
  const isAnalyzing = poem.score === 0 || poem.genre === 'Analyzing';

  return (
    <div 
      className={`min-h-[90vh] relative transition-all duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'} flex flex-col overflow-hidden`}
