                <span className="text-[8px] uppercase tracking-widest opacity-40">Likes</span>
              </div>
            </button>
            <button 
              onClick={() => onToggleReaction?.(poem.id, 'dislike')}
              className={`flex items-center space-x-4 transition-all ${poem.userReaction === 'dislike' ? 'scale-110' : 'opacity-40 hover:opacity-100'}`}
