const App: React.FC = () => {
  const [adminPoems, setAdminPoems] = useState<Poem[]>([]);
  const [userPoems, setUserPoems] = useState<Poem[]>([]);
  const [followingIds, setFollowingIds] = useState<string[]>([]);
  const [currentView, setCurrentView] = useState<View>('home');
  const [previousView, setPreviousView] = useState<View>('home');
  const [selectedPoemId, setSelectedPoemId] = useState<string | null>(null);
  const [targetUserId, setTargetUserId] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [dailyLine, setDailyLine] = useState<string>(() => localStorage.getItem('echo_daily_line_v1') || "Silence is the only thing we truly own.");
  const [editPoem, setEditPoem] = useState<Poem | null>(null);

  const currentViewRef = useRef<View>('home');
  useEffect(() => { currentViewRef.current = currentView; }, [currentView]);

  const syncStateWithHash = async () => {
    const hash = window.location.hash || '#/';
    const { data: { session } } = await supabase.auth.getSession();
    const u = session?.user ?? null;
    setCurrentUser(u);

    if (u) {
      const ids = await supabaseService.getFollowingIds(u.id);
      setFollowingIds(ids);
    }

    let targetView: View = 'home';
    let targetPoemId: string | null = null;
    let tUserId: string | null = null;

    if (hash.startsWith('#/p/')) {
      targetView = 'detail';
      targetPoemId = hash.replace('#/p/', '');
    } else if (hash.startsWith('#/u/')) {
      targetView = 'user-profile';
      tUserId = hash.replace('#/u/', '');
    } else {
      const views: Record<string, View> = {
        '#/read': 'feed', '#/echoes': 'user-feed', '#/create': 'create', '#/about': 'about',
        '#/contact': 'contact', '#/privacy': 'privacy', '#/profile': 'profile',
        '#/ranks': 'leaderboard', '#/auth': 'auth', '#/admin': 'admin', '#/': 'home'
      };
      targetView = views[hash] || 'home';
    }

    if (['profile', 'create', 'admin'].includes(targetView) && !session) {
      window.location.hash = '#/auth';
      return;
    }

    if (currentViewRef.current !== 'detail' && currentViewRef.current !== targetView) setPreviousView(currentViewRef.current);
    setSelectedPoemId(targetPoemId);
    setTargetUserId(tUserId);
    setCurrentView(targetView);
  };

  const refreshData = async () => {
    try {
      const uId = currentUser?.id;
      const [admins, users] = await Promise.all([
        supabaseService.getAdminPoems(uId),
        supabaseService.getEchoes(uId)
      ]);
      setAdminPoems(admins || []);
      setUserPoems(users || []);
    } catch (err) { console.error("Data Sync Error:", err); }
  };

  useEffect(() => {
    window.addEventListener('hashchange', syncStateWithHash);
    syncStateWithHash();
    geminiService.getDailyLine().then(line => setDailyLine(line));
    return () => window.removeEventListener('hashchange', syncStateWithHash);
  }, []);

  useEffect(() => {
    refreshData();
  }, [currentUser, currentView]);

  const navigateTo = (view: View, id: string | null = null) => {
    const routes: Record<View, string> = {
      'home': '#/', 'feed': '#/read', 'user-feed': '#/echoes', 'create': '#/create',
      'about': '#/about', 'contact': '#/contact', 'privacy': '#/privacy', 'admin': '#/admin',
      'profile': '#/profile', 'leaderboard': '#/ranks', 'auth': '#/auth', 
      'detail': `#/p/${id}`, 'user-profile': `#/u/${id}`
    };
    window.location.hash = routes[view];
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePublish = async (newPoem: Partial<Poem>) => {
    const meta = await geminiService.analyzePoem(newPoem.content || '', newPoem.title);
    if (!meta.isSafe) throw new Error("Forbidden Resonance");

    const isAdminUser = !!currentUser?.email && ADMIN_EMAILS.includes(currentUser.email);
    const finalPoem: Partial<Poem> = {
      ...newPoem,
      title: (newPoem.title && newPoem.title.trim() !== "" && newPoem.title.toLowerCase() !== 'untitled') ? newPoem.title : meta.suggestedTitle,
      score: meta.score,
      genre: meta.genre,
      tone: meta.tone,
      justification: meta.justification,
      backgroundColor: meta.backgroundGradient,
      visibility: isAdminUser ? 'read' : 'echoes'
    };

    const saved = isAdminUser ? await supabaseService.createAdminPoem(finalPoem) : await supabaseService.createEcho(finalPoem);
    if (!saved) throw new Error("Transmission Failed");
    refreshData();
    navigateTo(isAdminUser ? 'feed' : 'user-feed');
  };

  const handleEdit = (poem: Poem) => {
    setEditPoem(poem);
    navigateTo('create');
  };

  const handleUpdate = async (id: string, updates: Partial<Poem>) => {
    const success = await supabaseService.updateEcho(id, updates);
    if (success) {
      setEditPoem(null);
      refreshData();
      navigateTo('detail', id);
    } else {
      throw new Error("Update failed");
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("This echo will be lost to the void forever. Proceed?")) {
      const success = await supabaseService.deleteEcho(id);
      if (success) {
        refreshData();
        navigateTo('user-feed');
      }
    }
  };

  const handleToggleReaction = async (poemId: string, type: ReactionType) => {
    if (!currentUser) { navigateTo('auth'); return; }
    const success = await supabaseService.toggleReaction(poemId, currentUser.id, type);
    if (success) refreshData();
  };

  const allPoems = [...adminPoems, ...userPoems];
  const selectedPoem = allPoems.find(p => p.id === selectedPoemId);
  const hideReactions = currentUser?.user_metadata?.hide_reactions || false;

  return (
    <div className="min-h-screen flex flex-col bg-echo-bg text-echo-text selection:bg-neutral-800">
      <Header currentView={currentView} onNavigate={navigateTo} />
      <main className="flex-grow">
        {currentView === 'home' && <Home dailyLine={dailyLine} onNavigate={navigateTo} />}
        {(currentView === 'feed' || currentView === 'user-feed') && (
          <div className="pt-10 animate-fade-in">
            <header className="mb-12 text-center space-y-4">
              <h2 className="instrument-serif text-6xl md:text-8xl italic opacity-95 tracking-tighter">
                {currentView === 'feed' ? 'Read' : 'Echoes'}
              </h2>
              <p className="text-[10px] uppercase tracking-[0.5em] opacity-80 font-bold">
                {currentView === 'feed' ? 'Curated Introspection' : 'Community Resonance'}
              </p>
            </header>
            <Feed 
              poems={currentView === 'feed' ? adminPoems : userPoems} 
              onSelectPoem={(id) => navigateTo('detail', id)} 
              followingIds={followingIds}
              onNavigateUser={(userId) => navigateTo('user-profile', userId)}
              onToggleReaction={handleToggleReaction}
              hideReactionCounts={hideReactions}
            />
          </div>
        )}
        {currentView === 'detail' && selectedPoem && (
          <PoemDetail 
            poem={selectedPoem} 
            onBack={() => navigateTo(previousView)} 
            currentUser={currentUser}
            onEdit={() => handleEdit(selectedPoem)}
            onDelete={() => handleDelete(selectedPoem.id)}
            onNavigateUser={(userId) => navigateTo('user-profile', userId)}
            onToggleReaction={handleToggleReaction}
            hideReactionCounts={hideReactions}
          />
        )}
        {currentView === 'create' && (
          <CreatePoem 
            onPublish={handlePublish} 
            onUpdate={handleUpdate}
            initialPoem={editPoem}
            onCancel={() => { setEditPoem(null); navigateTo('home'); }} 
          />
        )}
        {currentView === 'admin' && <AdminPortal onPublish={handlePublish} onCancel={() => navigateTo('home')} />}
        {currentView === 'leaderboard' && <Leaderboard />}
        {currentView === 'profile' && <Profile />}
        {currentView === 'user-profile' && <Profile userId={targetUserId} />}
        {currentView === 'auth' && <Auth />}
        {currentView === 'about' && <About />}
        {currentView === 'contact' && <Contact />}
        {currentView === 'privacy' && <Privacy />}
      </main>
      <Footer onContactClick={() => navigateTo('contact')} onPrivacyClick={() => navigateTo('privacy')} />
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { supabase, authService, supabaseService } from '../services/supabaseService.ts';
import { Poem, UserProfile } from '../types.ts';
import { getResonanceColor } from '../utils.ts';

interface ProfileProps {
  userId?: string | null;
}

const Profile: React.FC<ProfileProps> = ({ userId: externalUserId }) => {
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [avatarUrl, setAvatarUrl] = useState('');
  const [hideReactions, setHideReactions] = useState(false);
  const [userEchoes, setUserEchoes] = useState<Poem[]>([]);
  const [isFollowing, setIsFollowing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);

  const isOwnProfile = !externalUserId || (currentUser && currentUser.id === externalUserId);
  const targetId = externalUserId || currentUser?.id;

  const loadProfileData = async (uid: string) => {
    setLoading(true);
    try {
      const [prof, echoes, session] = await Promise.all([
        supabaseService.getUserProfile(uid),
        supabase.from('echoes').select('*').eq('user_id', uid).order('created_at', { ascending: false }),
        supabase.auth.getSession()
      ]);

      const sessUser = session.data.session?.user;
      setCurrentUser(sessUser);

      if (prof) {
        setProfile(prof);
        if (isOwnProfile) setHideReactions(sessUser?.user_metadata?.hide_reactions || false);
      }

      if (echoes.data) {
        setUserEchoes(echoes.data.map(d => ({
          id: String(d.id),
          title: d.title || '...',
          content: d.content || '',
          author: d.author || 'Anonymous',
          userId: d.user_id || '',
          timestamp: new Date(d.created_at).getTime(),
          score: Number(d.score) || 0,
          genre: d.genre || 'Echo',
          tone: d.tone || 'melancholic',
          backgroundColor: d.background_color || '',
          visibility: 'echoes',
          likesCount: 0, // Placeholder
          dislikesCount: 0 // Placeholder
        })));
      }

      if (sessUser && !isOwnProfile) {
        const following = await supabaseService.getFollowingIds(sessUser.id);
        setIsFollowing(following.includes(uid));
      }

      if (isOwnProfile && sessUser) {
        setDisplayName(sessUser.user_metadata?.display_name || '');
        setUsername(sessUser.user_metadata?.username || '');
        setAvatarUrl(sessUser.user_metadata?.avatar_url || '');
      }
    } catch (err) {
      console.error("Profile load failed", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (targetId) loadProfileData(targetId);
  }, [targetId]);

  const handleUpdateProfile = async () => {
    setActionLoading(true);
    try {
      await authService.updateProfile({ 
        display_name: displayName,
        username: username,
        avatar_url: avatarUrl,
        hide_reactions: hideReactions
      });
      setIsEditing(false);
      if (targetId) loadProfileData(targetId);
    } catch (err) {
      alert("Metamorphosis failed.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleFollowToggle = async () => {
    if (!currentUser || !targetId || actionLoading) return;
    setActionLoading(true);
    try {
      if (isFollowing) {
        await supabaseService.unfollowUser(currentUser.id, targetId);
        setIsFollowing(false);
      } else {
        await supabaseService.followUser(currentUser.id, targetId);
        setIsFollowing(true);
      }
      loadProfileData(targetId);
    } catch (err) {
      console.error("Follow action failed", err);
    } finally {
      setActionLoading(false);
    }
  };

  const generatePhantomAvatar = () => {
    const seed = Math.random().toString(36).substring(7);
    setAvatarUrl(`https://api.dicebear.com/7.x/shapes/svg?seed=${seed}&backgroundColor=0a0a0a,111111`);
  };

  if (loading) return <div className="min-h-screen flex items-center justify-center italic instrument-serif text-2xl opacity-40">Tuning into frequency...</div>;

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 space-y-20 animate-fade-in">
      <header className="border-b border-echo-border pb-16 space-y-12">
        <div className="flex flex-col md:flex-row gap-12 items-center md:items-start">
          <div className="relative group">
            <div className="w-32 h-32 md:w-48 md:h-48 border border-white/10 rounded-sm overflow-hidden bg-neutral-900 shadow-2xl transition-all hover:border-white/30">
              {(isOwnProfile ? avatarUrl : profile?.avatarUrl) ? (
                <img src={isOwnProfile ? avatarUrl : profile?.avatarUrl} alt="Identity" className="w-full h-full object-cover opacity-80" />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-[10px] uppercase tracking-widest opacity-20">No Sigil</div>
              )}
            </div>
            {isEditing && (
              <button 
                onClick={generatePhantomAvatar}
                className="absolute -bottom-4 left-1/2 -translate-x-1/2 bg-white text-black px-4 py-1.5 text-[8px] uppercase tracking-[0.3em] font-black hover:bg-neutral-200 transition-all whitespace-nowrap shadow-xl"
              >
                Generate Sigil
              </button>
            )}
          </div>

          <div className="flex-grow space-y-6 text-center md:text-left w-full">
            <div className="flex justify-between items-start">
               <p className="text-[10px] uppercase tracking-[0.4em] opacity-90 font-black text-white">Identity Anchor</p>
               {!isOwnProfile && currentUser && (
                 <button 
                   onClick={handleFollowToggle}
                   disabled={actionLoading}
                   className={`px-8 py-2 text-[10px] uppercase tracking-[0.3em] font-black transition-all border ${isFollowing ? 'border-white/20 text-white/60 hover:border-red-500/40 hover:text-red-400' : 'border-white bg-white text-black hover:bg-transparent hover:text-white'}`}
                 >
                   {actionLoading ? '...' : isFollowing ? 'Unfollow' : 'Follow'}
                 </button>
               )}
            </div>

            {isEditing ? (
              <div className="space-y-6">
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[8px] uppercase tracking-widest opacity-40">Display Name</label>
                    <input 
                      type="text" 
                      value={displayName}
                      onChange={e => setDisplayName(e.target.value)}
                      placeholder="Fragment Observer"
                      className="instrument-serif italic text-4xl bg-transparent border-b border-white/20 w-full focus:outline-none text-white pb-2"
                    />
                  </div>
                  <div className="flex items-center space-x-3">
                    <input 
                      type="checkbox" 
                      id="hide_reactions"
                      checked={hideReactions}
                      onChange={e => setHideReactions(e.target.checked)}
                      className="accent-white"
                    />
                    <label htmlFor="hide_reactions" className="text-[10px] uppercase tracking-widest opacity-60">Hide Like/Dislike counts globally</label>
                  </div>
                </div>
                <div className="flex gap-4 pt-4">
                  <button onClick={handleUpdateProfile} disabled={actionLoading} className="px-6 py-2 bg-white text-black text-[10px] uppercase tracking-widest font-black hover:bg-neutral-200 transition-all">
                    {actionLoading ? 'Encrypting...' : 'Save changes'}
                  </button>
                  <button onClick={() => setIsEditing(false)} className="px-6 py-2 border border-white/20 text-white text-[10px] uppercase tracking-widest font-black hover:bg-white/10 transition-all">Discard</button>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="space-y-2">
                  <h1 className="instrument-serif italic text-6xl md:text-8xl text-white leading-none">
                    {isOwnProfile ? (displayName || 'Anonymous') : (profile?.displayName || 'Anonymous')}
                  </h1>
                  <p className="instrument-serif text-3xl opacity-40 italic">@{isOwnProfile ? (username || 'observer') : (profile?.username || 'observer')}</p>
                </div>

                <div className="flex justify-center md:justify-start space-x-8 text-[10px] uppercase tracking-[0.2em] font-bold opacity-60">
                  <span>{profile?.followersCount || 0} Followers</span>
                  <span>{profile?.followingCount || 0} Following</span>
                </div>

                {isOwnProfile && (
                  <button 
                    onClick={() => setIsEditing(true)} 
                    className="text-[10px] uppercase tracking-widest opacity-40 hover:opacity-100 transition-all border-b border-white/20 pb-1"
                  >
                    Modify Identity
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </header>

      <section className="grid grid-cols-1 md:grid-cols-2 gap-10">
        <div className="p-10 border border-white/20 bg-white/5 space-y-6 rounded-sm">
          <p className="text-[10px] uppercase tracking-widest opacity-90 font-black text-white">Mean Resonance</p>
          <div className="text-7xl instrument-serif text-white font-bold">{profile?.avgScore || 0}%</div>
        </div>
        <div className="p-10 border border-white/20 bg-white/5 space-y-6 rounded-sm">
          <p className="text-[10px] uppercase tracking-widest opacity-90 font-black text-white">Total Echoes</p>
          <div className="text-7xl instrument-serif text-white font-bold">{profile?.totalPoems || 0}</div>
        </div>
      </section>

      <section className="space-y-12">
        <header className="flex justify-between items-center border-b border-white/10 pb-4">
          <h2 className="instrument-serif text-4xl italic">{isOwnProfile ? 'Your Recorded Echoes' : 'Public Echoes'}</h2>
          <p className="text-[10px] uppercase tracking-widest opacity-30">{userEchoes.length} Fragments persists</p>
        </header>

        <div className="space-y-6">
          {userEchoes.map(echo => {
            const resonanceColor = getResonanceColor(echo.score);
            return (
              <div key={echo.id} className="p-8 border border-white/5 hover:bg-white/[0.02] transition-all group rounded-sm space-y-6">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                  <div className="space-y-2">
                    <h3 className="instrument-serif text-3xl group-hover:italic transition-all">{echo.title}</h3>
                    <p className="text-[10px] uppercase tracking-widest opacity-30 font-black">{echo.genre} · {new Date(echo.timestamp).toLocaleDateString()}</p>
                  </div>

                  <div className="flex flex-col items-end gap-2 min-w-[120px]">
                    <span className="text-[9px] font-mono font-bold opacity-40 uppercase tracking-widest">Resonance: {echo.score}%</span>
                    <div className="w-full md:w-32 h-1 bg-white/10 rounded-full overflow-hidden">
                      <div 
                        className="h-full transition-all duration-1000"
                        style={{ 
                          width: `${echo.score}%`, 
                          backgroundColor: resonanceColor,
                        }}
                      />
                    </div>
                  </div>

                  <button 
                    onClick={() => window.location.hash = `#/p/${echo.id}`}
                    className="px-6 py-2 border border-white/10 hover:border-white text-[9px] uppercase tracking-widest opacity-40 hover:opacity-100 transition-all font-black text-white"
                  >
                    Enter Frequency
                  </button>
                </div>
              </div>
            );
          })}
          {userEchoes.length === 0 && (
            <div className="text-center py-20 italic opacity-20">The void is silent here.</div>
          )}
        </div>
      </section>
    </div>
  );
};

export default Profile;

/**
 * Echo Pages Validation Service
 * Protects the sanctuary from junk, spam, and forbidden language.
 */

const RATE_LIMIT_MS = 60000; // 1 minute between posts
const DAILY_LIMIT = 20;
const MIN_LENGTH = 1;

// Local blacklist for immediate rejection
const BLACKLIST = ['nazi', 'hitler', 'porn', 'nsfw', 'f*ck', 'sh*t']; 

export const validationService = {
  checkRateLimit(userId: string): { allowed: boolean; reason?: string } {
    const now = Date.now();
    const lastPost = localStorage.getItem(`echo_last_post_${userId}`);
    const postHistory = JSON.parse(localStorage.getItem(`echo_history_${userId}`) || '[]');

    // 1. Minimum Interval Check
    if (lastPost && now - parseInt(lastPost) < RATE_LIMIT_MS) {
      const remaining = Math.ceil((RATE_LIMIT_MS - (now - parseInt(lastPost))) / 1000);
      return { allowed: false, reason: `Frequency flooding detected. Re-tune in ${remaining}s.` };
    }

    // 2. Daily Volume Check
    const today = new Date().toDateString();
    const postsToday = postHistory.filter((p: string) => new Date(parseInt(p)).toDateString() === today);
    if (postsToday.length >= DAILY_LIMIT) {
      return { allowed: false, reason: "Your daily resonance is exhausted. Return with the next moon." };
    }

    return { allowed: true };
  },

  recordPost(userId: string) {
    const now = Date.now();
    localStorage.setItem(`echo_last_post_${userId}`, now.toString());
    const history = JSON.parse(localStorage.getItem(`echo_history_${userId}`) || '[]');
    history.push(now.toString());
    localStorage.setItem(`echo_history_${userId}`, JSON.stringify(history.slice(-20)));
  },

  validateContent(content: string): { valid: boolean; reason?: string } {
    const text = content.trim();

    if (text.length < MIN_LENGTH) return { valid: false, reason: "Fragment is too brief to echo." };

    // Maximum length check removed to allow "any length"

    // Junk/Spam detection (e.g., repeated characters)
    if (/(.)\1{20,}/.test(text)) return { valid: false, reason: "Structural static detected (excessive repetition)." };

    // Local profanity check
    const containsBlacklist = BLACKLIST.some(word => text.toLowerCase().includes(word));
    if (containsBlacklist) return { valid: false, reason: "Forbidden vocabulary detected." };

    return { valid: true };
  }
};

import React, { useState, useEffect } from 'react';
import { Poem } from '../types.ts';
import { CONFIG } from '../config.ts';
import { supabase } from '../services/supabaseService.ts';
import { ADMIN_EMAILS } from '../constants.ts';
import { geminiService } from '../services/geminiService.ts';
import { validationService } from '../services/validationService.ts';

interface CreatePoemProps {
  onPublish: (poem: Partial<Poem>) => Promise<void>;
  onUpdate?: (id: string, updates: Partial<Poem>) => Promise<void>;
  onCancel: () => void;
  initialPoem?: Poem | null;
}

const CreatePoem: React.FC<CreatePoemProps> = ({ onPublish, onUpdate, onCancel, initialPoem }) => {
  const [title, setTitle] = useState(initialPoem?.title || '');
  const [content, setContent] = useState(initialPoem?.content || '');
  const [isPublishing, setIsPublishing] = useState(false);
  const [isGeneratingTitle, setIsGeneratingTitle] = useState(false);
  const [safetyError, setSafetyError] = useState<string | null>(null);
  const [regenCount, setRegenCount] = useState(0);
  const [user, setUser] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      const u = session?.user ?? null;
      if (!u) { window.location.hash = '#/auth'; return; }
      setUser(u);
      setIsAdmin(!!u.email && ADMIN_EMAILS.includes(u.email));
    });
  }, []);

  const handleGenerateTitle = async () => {
    if (!content.trim() || regenCount >= CONFIG.MAX_TITLE_REGEN || isGeneratingTitle) return;

    const localVal = validationService.validateContent(content);
    if (!localVal.valid) {
      setSafetyError(localVal.reason || "Invalid fragment.");
      return;
    }

    setIsGeneratingTitle(true);
    setSafetyError(null);
    try {
      const analysis = await geminiService.analyzePoem(content.trim());
      if (!analysis.isSafe) {
        setSafetyError(analysis.errorReason || "Violated Resonance detected.");
        return;
      }
      setTitle(analysis.suggestedTitle);
      setRegenCount(prev => prev + 1);
    } catch (err) { console.error("Title Generation Failed:", err); }
    finally { setIsGeneratingTitle(false); }
  };

  const handleAction = async () => {
    if (!content.trim() || isPublishing) return;
    if (!user) return;

    if (!initialPoem) {
      const rateCheck = validationService.checkRateLimit(user.id);
      if (!rateCheck.allowed && !isAdmin) {
        setSafetyError(rateCheck.reason || "Frequency limit reached.");
        return;
      }
    }

    const localVal = validationService.validateContent(content);
    if (!localVal.valid) {
      setSafetyError(localVal.reason || "Structural dissonance detected.");
      return;
    }

    setIsPublishing(true);
    setSafetyError(null);

    try {
      if (initialPoem && onUpdate) {
        await onUpdate(initialPoem.id, { title: title.trim(), content: content.trim() });
      } else {
        const poemDraft: Partial<Poem> = {
          title: title.trim(),
          content: content.trim(),
          author: user.user_metadata?.display_name || user.email?.split('@')[0] || 'Anonymous',
          userId: user.id,
          timestamp: Date.now()
        };
        await onPublish(poemDraft);
        validationService.recordPost(user.id);
      }
    } catch (err: any) {
      setSafetyError(err.message || "Transmission interrupted by forbidden frequencies.");
      setIsPublishing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fade-in relative">
      {safetyError && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-3xl animate-fade-in">
          <div className="max-w-xl w-full bg-gradient-to-b from-red-950/20 to-black p-12 border border-red-500/20 text-center space-y-10 shadow-2xl rounded-sm">
            <div className="w-20 h-20 mx-auto border border-red-500/40 rounded-full flex items-center justify-center animate-pulse">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-red-500/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
            </div>
            <div className="space-y-4">
              <h3 className="instrument-serif italic text-4xl text-red-500/90 tracking-tight">Forbidden Resonance</h3>
              <p className="serif-font text-lg italic opacity-60 leading-relaxed text-white">
                "{safetyError}"<br/>
                The Sanctuary requires purity of thought and rhythm.
              </p>
            </div>
            <button 
              onClick={() => setSafetyError(null)}
              className="w-full py-5 border border-red-500/30 hover:border-red-500 transition-all text-[10px] uppercase tracking-[0.5em] font-black text-red-500/80"
            >
              Adjust Frequency
            </button>
          </div>
        </div>
      )}

      <div className="space-y-12">
        <header className="flex justify-between items-center border-b border-echo-border pb-8">
          <div>
            <h2 className="instrument-serif text-5xl italic text-white">{initialPoem ? 'Refine Fragment' : 'Commit Fragment'}</h2>
            <p className="text-[9px] uppercase tracking-widest opacity-30 mt-1">
              {isAdmin ? "Admin Publication" : "Community Echo"}
            </p>
          </div>
          <button onClick={onCancel} className="text-[10px] uppercase tracking-widest opacity-30 hover:opacity-100 px-4 py-2 border border-echo-border transition-all text-white">Discard</button>
        </header>

        <div className="space-y-16">
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Title (Optional)</p>
              {regenCount < CONFIG.MAX_TITLE_REGEN && content.length > 10 && (
                <button 
                  onClick={handleGenerateTitle}
                  disabled={isGeneratingTitle}
                  className="text-[8px] uppercase tracking-widest opacity-40 hover:opacity-100 transition-opacity border-b border-white/20 pb-0.5"
                >
                  {isGeneratingTitle ? 'Tuning...' : 'Generate with AI'}
                </button>
              )}
            </div>
            <input 
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="The Echo of..."
              className="w-full bg-transparent border-b border-echo-border py-4 focus:border-white focus:outline-none instrument-serif text-4xl transition-colors text-white"
            />
          </div>

          <div className="space-y-4">
             <p className="text-[10px] uppercase tracking-[0.4em] opacity-30 text-white font-bold">Fragment</p>
             <textarea 
               value={content}
               onChange={(e) => setContent(e.target.value)}
               placeholder="Whisper into the void..."
               className="w-full h-80 bg-transparent border border-echo-border p-8 focus:border-white focus:outline-none transition-all serif-font text-2xl italic leading-relaxed whitespace-pre-line text-white/90"
             />
          </div>

          <div className="pt-8">
            <button 
              onClick={handleAction}
              disabled={isPublishing || !content.trim()}
              className="w-full py-6 bg-echo-text text-echo-bg text-[11px] uppercase tracking-[0.4em] font-bold hover:bg-white transition-all disabled:opacity-20 flex items-center justify-center space-x-4"
            >
              {isPublishing && <div className="w-4 h-4 border-2 border-echo-bg/30 border-t-echo-bg rounded-full animate-spin" />}
              <span>{isPublishing ? 'Analyzing Resonance...' : (initialPoem ? 'Update Echo' : 'Commit to the Void')}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

